window.__D("text/hemshech-ayin-beis/c013",{"p":[[3601331191,"ושום ענין בהשם רק מה שעל ידו הוא נפנה לקוראיו בשמו כו', דבהכחות עצמי' אא\"ל שאינו מרגיש בהם שום ענין, שהרי מובן שאא\"ל כחות גלוים רק כשיש כחות נעלמים עצמי' כו', אבל בהשם אינו מרגיש שום צורך וענין כלל רק מה שנפנה ע\"י לקוראיו כו', וזהו מצד פשיטות השם שאינו בו בבחי' מציאות כו' (וע' משנת\"ל מענין השם בד\"ה אני לדודי וד\"ה אתם נצבים), וכמו\"כ הע\"ס הגנוזות אינם בבחי' מציאות רק כמו שמות לבד שנעשים ע\"י הקריאה כו'.\n<b>ויובן</b> זה עד\"מ באדם בקריאת שמות דכחות הפרטי' וכמו בש' חכם או בש' חסדן שזה מביא ומגלה את הכח מההעלם אל הגילוי, והיינו שממשיך גילוי משרש ומקור הנעלם והעצמי של הכח ההוא, וכידוע בענין השבחים כשמשבחים אותו בש' חכם ה\"ז מעורר כח חכמתו הנעלמה שגם אם משכיל השכלות בכח מקור שכלו הנה כאשר משבחים אותו שהוא חכם גדול מתגלים אצלו עי\"ז שכלי' שהן באופן אחר מהשכלי' הקודמים והיינו שבאים מכח החכ' הנעלמה כו', ולכן אנו רואין שגם כאשר לא נמצא גילוי אור שכל במוחו, וגם אינו מוכן להשכיל דהיינו שאין הכנה כלל בנפשו להשכיל ולהתחכם כו' מתחדש בו שכלי' חדשים מכח חכמתו ההיולי העצמי עי\"ז שקוראין אותו בש' חכם שמשבחים אותו בזה, וכן בקריאת ש' חסדן מעוררים כח החסד שבו, שגם שלא יש שום התעוררות חסד כלל בלבו ואינו רוצה כלל להתחסד, הנה ע\"י שמשבחים אותו במדת החסד מתעורר כח החסד ההיולי העצמי להתחסד ביותר כמו מצד תוקף העצמות כו', וז\"ע השבחים שהיו תלמידי הרשב\"י משבחים אותו בכמה שבחים שזהו בכדי לעורר הכחות הנעלמים כו'\nוכמ\"ש במ\"א. ונמצא שקודם שקראוהו חכם לא הי' בו גילוי החכ' כלל וגם לא הי' יודע בעצמו מחכמתו, שהרי זהו בהאופן שאינו מוכן כלל להשכיל, ואז אין בו שום גילוי וידיעה מחכמתו כלל דבשעת שיש הכנה בנפשו להשכיל ולהתחכם, הנה להיותו חכם בעצם הרי בשעה שעוסק במושכלות ומוכן להשכיל יש בו ידיעה מחכמתו גם טרם שבאה ההשכלה בגילוי כו', אבל כאשר אינו מוכן כלל להתחכם אז אין בו ידיעה מחכמתו, וכידוע דהכח ההיולי העצמי אינו בבחי' הרגש כלל שאינו נודע גם מציאותו כו' (ומ\"מ ענין ידיעת עצמו יש בו גם כשאינו מוכן להשכיל, והוא שיודע בעצמו שביכולתו להשכיל ולהתחכם כו', וכנודע דענין ידיעת עצמו הוא מהכחות הנעלמים דוקא שיודע כח הנעלם שלו שכחו הוא בדבר הזה כו', וזהו הסבה מה שמתעורר ע\"י השבחים כמו בש' חכם מפני שיודע בעצמו כחו ויכולתו העצמי בכח הזה ואלו לא הי' גם בידיעת עצמו שבכחו להתחכם לא הי' התגלות גם ע\"י השבחים רק מפני שבידיעת עצמו יודע את כחו כו', אך א\"ז ידיעה מחכמתו רק מה שיודע עצם כחו שביכולתו להתחכם כו', דהנה ידיעה מחכמתו\nא\"ז רק מה שיודע שישכיל ויתחכם כ\"א הוא ידיעת השכלת הדבר טרם שמשכיל אותו כו', והוא כי להיותו חכם בעצם והוא מוכן להשכיל ידוע ומורגש אצלו בבחי' העלם ובבחי' מקיף השכלת הדבר עוד טרם שמשכיל כו', וענין ידיעת עצמו הרי א\"ז ידיעת השכלה כלל כ\"א מה שיודע שביכולתו להשכיל ולהתחכם כו', שזהו רק ידיעה כללי' בלבד כו', וה\"ז בדוגמא כמו השם שנמצא בהעלם בהחיות שלהחיות שעי\"ז הוא נפנה לקוראין אותו בשמו כו'), וע\"י קריאת השם חכם נתגלה בו חכ' מכח חכמתו הנעלמה שזהו בבחי' התחדשות וכאלו עתה נעשה חכם בקריאה והתעוררות זו כו' (והשכלי' באמת הן התחדשות כי השכלי'"],[3601331192,"הבאים מכח החכ' ההיולי העצמי המה באמת באופן אחר לגמרי מהשכליים שממקור השכל הנק' כח המשכיל והוא בחי' אור חדש כו' כנודע).\n<b>וכמו\"כ</b> יובן למע' בענין קריאת שמות והשבחים למע' הוא שע\"י קריאת ש' חכם עד\"מ נעשה בחי' החכ' בכח הנעלם שבה כו', דהנה למטה בנפש האדם הרי עכ\"פ נמצא בו כח החכ' הנעלמה גם קודם שקוראין אותו בש' חכם, רק שאינו בבחי' גילוי כלל ולא בבחי' מקור לגילוי עד שההתגלות הוא התחדשות כו' כנ\"ל, אך זהו רק בההתגלות לבד, אמנם למע' כ\"ה בעצם הכח דקודם הקריאה אינו נמצא כלל בחי' החכ' בהעלם ונעשה ע\"י הקריאה כו', וז\"ע אין מציאות לגנוזות, דהיינו שהע\"ס הגנוזות אינם בבחי' מציאות כלל, וע\"י הקריאה הוא שנעשה, שע\"י שקוראין אותו בש' חכם נעשה בחי' החכמה בבחי' כח נעלם, וע\"י קריאת ש' חסיד נעשה בחי' חסד בבחי' כח נעלם כו', באופן שקודם הקריאה הוא פשוט בתכלית שגם בהעלם לא ימצא מציאות מקור אורות הנאצלים ונעשה רק ע\"י הקריאה והעלאת מ\"ן, וכמו שהגילוי מן ההעלם נעשה ע\"י העלאת מ\"ן (שזהו כן גם בכחות האדם כנ\"ל) כמו\"כ גם ההעלם נעשה באותו פעם מן עצמות הפשוט כו', וזהו שהע\"ס הגנוזות אינם במציאות כלל מצ\"ע ונעשים רק ע\"י הקריאה והעלאת מ\"ן\nכו'. והנה הע\"ס הגנוזות הם שמות פרטי' ונתהוו מכללות ענין שמו כו', וכמארז\"ל עד שלא נבה\"ע הי' הוא ושמו בלבד שהוא בחי' ש' כללי שלמע' משמות פרטי' כו', וי\"ל שזהו מה שבאוא\"ס ב\"ה יש מקום שכאשר יקראוהו בש' חכם וחסיד יהי' התהוות הגנוזות כו' (וכמו עד\"מ באדם למטה שע\"י ידיעת עצמו מתעורר ע\"י הקריאה ושבח כנ\"ל, כמו\"כ למע' ע\"י בחי' שמו הגדול מתהווים הע\"ס הגנוזות כו'), וי\"ל שזהו החקיקה באוא\"ס שיהי' תופס מקום ההעלאת מ\"ן, דהנה מה שההעלאת מ\"ן מעורר זהו מפני הפשיטות כו', וכמשנת\"ל (ד\"ה אח\"מ) במשל המים דמפני שהן חומר זך וצלול ע\"כ נראה בהם פנים המסתכלים בהם כו', דכמו\"כ הוא באוא\"ס דמצד הפשיטות ע\"כ ההעלאת מ\"ן מעורר כו', אבל מצד הפשיטות דאוא\"ס הרי אין שום דבר תופס מקום כלל כו', וע\"ז הוא החקיקה באוא\"ס שההעלאת מ\"ן יהי' בבחי' תפיסת מקום שימשיכו בחי' השמות הנ\"ל (היינו שיתהוו הע\"ס בהעלם ע\"י הקריאה כו'), וכן באוא\"ס שלפה\"צ שנת\"ל שם דקודם ההתעוררות ותחלת התגלות הרצון וקודם ההמלכה הי' הרצון בהעלם והוא בחי' חפץ חסד ושם קדום\nהנמלך כו', י\"ל דענין קדימת הנמלך זהו ההשרשה בעצמותו שיהי' תופס מקום העלאת מ\"ן כו'. וזהו מ\"ש בזהר בתחלתו בריש הורמנותא דמלכא גליף גליפו בטה\"ע פי' הורמנותא דמלכא הוא רשות ורצון המלך כשעלה ברצה\"פ לברוא כו', והוא כמא' כד סליק ברעותי' למברא עלמא כו', ואו' בריש הורמנותא פי' כשהוצרך בעל הרצון שיתגלה רצונו ויהי' הרצון לברוא כו', ולא הי' למטה מי שיעורר אותו ברצון זה מאחר שהכל הי' עדיין בבחי' א\"ס עצמו כו', והי' העלאת מ\"ן מיני' ובי' כו', והו\"ע במי נמלך בנשמותיהן ש\"צ שעלה לפניו ית' מה שעתיד להתענג בנשמותיהן של צדיקים בעבודה שלהם במס\"נ ובקיום התומ\"צ כו', זה העונג עלה בבחי' העלאת מ\"ן לפניו שעי\"ז יתעורר ברצה\"פ להאציל ולברוא כו'. ואמנם להיות כי בחי' עונג זה שמקבל מביטול הנשמות והנבראים לא נחשב עונג כלל בעצמו' אוא\"ס מאחר שהנאצל נאצל רק מהארה דהארה לבד מעצמותו וכ\"ש הנברא כו', וא\"כ מה"],[3601331193,"תופס מקום הביטול והעלאת מ\"ן שלהם לגבי עצמות אוא\"ס כו', וע\"כ הוצרך בתחלה בעל הרצון הפשוט שיאיר אור חסד עליון מצ\"ע שיחפוץ בעונג זה ויהי' נחשב בעיניו כו', ולא מצד שיתפוס מקום אצלו באמת העונג הזה רק משום כי חפץ חסד הוא כו', וזהו גליף גליפו בטה\"ע פי' שבעצמות א\"ס חקק בחקיקה אור חסד פשוט להיות מחמתו דוקא סבת כח ועוז לעלות בהעלאת מ\"ן שיתעורר כבי' בבחי' רצון כו', וז\"ע שמו הגדול שזהו בחי' חפץ חסד ששם הנמלך קדום דהיינו שמשם שרש החקיקה שיתפוס מקום ההעלאת מ\"ן כו', וכ\"ה בבחי' רצון הכללי דא\"ק, וכידוע דכללות הענין מה שבאתעדל\"ת אתעדל\"ע הוא ממחה\"ק דא\"ק, שא\"ז ע\"פ טו\"ד שמחייב הדבר כך כי אין ערוך כלל, רק מפני שכך עלה במחה\"ק דא\"ק להיות באתעדל\"ת אתעדל\"ע כו' וכמ\"ש במ\"א בדרוש לרוקע הארץ, וזהו הרצון הכללי דא\"ק להיות המשכת הע\"ס הגנוזות ע\"י הקריאה בשמות כו'.\n<b>וזהו</b> כמים הפנים לפנים דע\"י העלאת מ\"ן דבחי' פנים תתאין עי\"ז הוא בחי' פנים עילאין כו', דאוא\"ס מצ\"ע אינו בערך ובגדר הספי' כלל דלאו מכל אילין מדות כלל כו' ואנת הוא חד ולא בחושבן שאינו בבחי' שייכות לע\"ס כלל כו', רק ע\"י העלאת מ\"ן דפנים התחתונים הם ע\"ס דאצי' נעשים פנים העליונים דע\"ס הגנוזות להיות מקורים להמשכת האור בהע\"ס דאצי' כו', ובחי' פנים העליונים הוא שנעשה בבחי' הפרסא וכמ\"ש בזהר הנ\"ל מטולמ\"ט עד ההוא פריסא כו', ובד\"כ הוא בחי' מל' דא\"ק או דעתיק כו', וכמשנת\"ל (ד\"ה אדם כי יהי') דכללות ההשתל' הוא מבחי' מל' לבד והיינו שגם בבחי' המל' דא\"ק שהיא מדרי' אחרונה שבא\"ק אין הספי' מצ\"ע כו', כי הכל הוא אוא\"ס הפשוט שאינו בערך הספי' כו' רק ע\"י העלאת מ\"ן דבחי' פנים תתאין כו', וקודם שנאצלו הנאצלים הי' ההעלאת מ\"ן מיני' ובי' וכמ\"ש בע\"ח דבעתיק יחוד מ\"ה וב\"ן הוא מיני' ובי' כו' וכמשנת\"ל באוא\"ס שלפה\"צ, ואחר שנאצלו הנאצלים מציאות הע\"ס הגנוזות הוא ע\"י העלאת מ\"ן כו', וה\"ז כמשל המים שאין להם שום גוון והם\nפשוטים בעצם ורק מה שנראה בהם פנים וגוון המסתכל, והפנים הנראים הן המים עצמם הפשוטים ואין כאן ב' פנים כו'. כמו\"כ הוא באוא\"ס היינו בחי' הכתר שהוא פשוט בתכלית ואין בו שום ציור וגוון דע\"ס מצ\"ע רק שע\"י הרדיפה והעלאת מ\"ן דע\"ס דאצי' נראה ונגלה בבחי' הכתר בחי' ע\"ס הגנוזות להיות בבחי' מקור לע\"ס כו', והוא בבחי' הפרסא דהיינו בחי' המל' כנ\"ל, והע\"ס הגנוזות הן האוא\"ס עצמו שהן ג\"כ בבחי' פשיטות כו', ומהם נמשכים האורות דאצי' שהן ג\"כ בבחי' א\"ס שהרי נעשים ע\"י העלאת מ\"ן, וכל ענין ההעלאת מ\"ן הוא שיהי' המשכת מ\"ד, וא\"כ באופן שנעשים ע\"י ההעלאת מ\"ן כ\"ה ההמשכה שהוא בבחי' א\"ס כו', וגם מובן כי הפרסא אינה מעלמת להיותה בבחי' אבני שיש טהור שנראים בה הפנים המסתכלים כו', וממילא גם ההמשכה אינו בבחי' מהות אחר כ\"א הוא האוא\"ס דבחי' הכתר כו', וזהו א\"ת מים מים שלא לחלק בין הע\"ס הגנוזות שהן בחי' פנים עילאין ובין הע\"ס בחי' פנים תתאין המקבלים מהם דהכל הוא מהות אחד כו', וכמ\"ש בספד\"צ רפ\"ה יהי רקיע בתוך המים להבדיל בין הקדש ובין\nקה\"ק עתיקא לזעירא אתפריש ואתדביק לא אתפריש ממש והיינו שהפרסא שבכתר אינו מפרס ומבדלת בבחי' העלם ממש ומאיר בחי' הארת פנים דע\"ק בפנים דז\"א כו' (והנה ההפרש בין ההמשכה דרך הכלים ובין דרך פרסא כבר נת\"ל שזהו"],[3601331194,"כמו המשכת אור שכל ע\"י אותי' ובין ההמשכה ע\"י משל שמעלים על האור יותר מן האותי' כו', ונת' ההפרש בין משל וחידה דבמשל הכוונה הוא לגלות האור כו', וע\"כ עכ\"פ האור מאיר דרך המשל כו', ובכל המשכה מב' מדרי' מובדלות אא\"ל ההמשכה דרך הכלים לבד שזהו כמשל האותי' כ\"א גם דרך פרסא שזהו כמו המשל כו', והיינו שהפרסא זהו לבוש על בחי' הכלים כו', וכמ\"ש הפרד\"ס בשער הצחצחות פ\"ו הנ\"ל דשרשי הכלים ושרשי האורות מאירים בהפרסא (והיינו שמתהווים ומתגלמים בהפרסא דכתר כו') וע\"י הפרסא מאירים בחכ' כו', וכ\"ה בכל המשכה ממדרי' למדרי' שהוא שלא בהדרגה שזהו ע\"י הכלים וע\"י הפרסא כו'. אמנם כמו שיש חילוקים באותי' וכמו אותי' המח' ואותי' שבחכ' ואותי' שברצון כו' שהאותי' שהן בבחי' דקות ורוחני' יותר ה\"ה מגלים את האור יותר כו', וכמו\"כ הוא בענין המשלים דעם היותו משל מ\"מ הוא בבחי' דקות שאינו מעלים על האור, וכמו ענין אבני שיש טהור דמחזי כי אידוותא דימא, שעם היותם אבנים שנגלדו ה\"ה כמו מים כו', וז\"ש בספד\"צ הנ\"ל אתפרש ואתדבק ולא אתפרש ממש, דע\"ה\nהפרסא היא הפרש וכמו הפסק בין ע\"ק לזעיר, ומ\"מ אתדבק בחי' זעיר בע\"ק ומתייחד בו כו', וי\"ל דהיינו בבחי' רצוא מלמטלמ\"ע והוא העלאת מ\"ן הנ\"ל, ולא אתפרש ממש היינו שגם דרך הפרסא מאיר בחי' הארת פנים דע\"ק בחי' אור פני מלך חיים בבחי' פנים דז\"א כו').\n<b>והנה</b> הארת פנים דע\"ק בפנים דז\"א זהו כאשר ז\"א מסתכל בפנים דא\"א וכדאי' באד\"ר דקל\"ג סע\"ב ת\"ת פנים דלבר (הוא בחי' פנים דז\"א) אית זמן דנהרין כו' כד אתגליין תפוחין דלעילא (בחי' תרין תפוחין שהן הארת פנים כו' כמ\"ש בהבי' דאלה מסעי כו'), ומנהון נהירין לש\"ע עיבר כו', והוא ע\"י הסתכלות דז\"א וכמ\"ש באד\"ר כד ז\"א מסתכל במצחא דא\"א מקבל ש\"ע נהורין כו' וכמ\"ש בע\"ח שער א\"א פי\"ד וט\"ו. ובעבודה הוא בחי' אה' בתענוגים והוא האה' הבאה ע\"י הראי' דוקא והו\"ע לאסתכלא ביקרא דמלכא כו', דהנה בכל ידיעה באלקות יכול להיות בב' אופנים אם שהוא בבחי' השגה לבד או בבחי' ראי', וכמו בההארה אלקית המהווה את העולם הרי מובן ומושג היטב איך שהאלקות מהווה את העולם ומחי' אותו וכמ\"ש ואתה מחי' את כולם וא\"ת מחי' אלא מהווה כו', דהארה אלקי' מתלבש בכל נברא להוותו ולהחיותו כו' כי אין דבר עושה א\"ע ולא חי מעצמו כו' וכמשנת\"ל (ד\"ה ואלה שמות). אך כאשר הוא בבחי' השגה לבד הגם שהוא עבודה אמיתי' וזה כל האדם להיות בהשגה זו לייגע א\"ע להבין הענין\nהיטב שיונח ויוקלט הענין במוחו ולהתפעל מזה באה' שירצה בהאלקות ובהגילוי דהאור האלקי כו', ומ\"מ בהשגה לבד אין הענין מאיר בגילוי כ\"כ דהגם שמבין ומשיג הענין היטב ומאיר אצלו כו', מ\"מ אין עצם הענין אצלו בגילוי ממש, וממילא אינו נקלט כ\"כ בפנימי' בנפשו להיות בו תמיד ורק בשעת ההתבוננות אז מאיר ונרגש אצלו, ואח\"כ מסתלק ממנו וממילא גם האה' חולפת ועוברת כו'. אבל כאשר היא בבחי' ראי' וכמו שאו מרום וראו מי ברא אלה כו', שרואה אמיתי' הדבר בעין שכלו איך שהאלקות מהווה ומחי' את העולם כו', שזהו ע\"י שקידת העבודה בהשגה והתבוננות טובה וע\"י ההעמקה שמעמיק דעתו בחוזק בההשגה עד שבא לידי הכרה ולידי ראי' שרואה אמיתי' הענין כו', דאז ה\"ז מאיר בנפשו בבחי' גילוי אור ממש ונקלט מאד בפנימי' נפשו ואינו נפסק ומסתלק ממנו לעולם כו'."],[3601331195,"<b>וכמו</b> כאשר רואה אדם איזה דבר טוב ויפה הרי הדבר עומד תמיד נגד עיניו כו', ואינו דומה לשמיעה דכאשר שומע איזה ענין ומצייר בשכלו טוב הדבר ומתפעל בזה ה\"ז רק לפי שעה ואח\"כ נשכח ומתעלם הענין אצלו, היינו שמתעלם אצלו טוב הדבר ההוא כו', וממילא אינו מתפעל כו', אבל כאשר ראה טוב הדבר ה\"ז אינו מתעלם אצלו לעולם ותמיד הוא לעיניו טוב ויופי הדבר כו'. וכמו\"כ הוא בראיית עין השכל באלקו' שאין הדבר מסתלק ממנו כו', והאה' שעי\"ז היא בבחי' דבקות שנדבק ממש בהאור האלקי כו'. וזהו בהאור האלקי המתלבש בעולמות כו', ולמע' מזה הוא ההתבוננות בעצמות אוא\"ס כו', והוא איך שכל הריבוי שבעולמות בריבוי הנבראים ובריבוי האור והחיות שבהם כו' כ\"ז הוא בחי' הארה חיצוני' שמבחי' המל' דמלכותך מכ\"ע בחי' התפשטות המלוכה בריבוי עם דאלף אלפים ישמשוני' וריבו ריבבן כו', וכמו\"כ בנבראים למטה ובכולם יש הארה אלקי' המהווה ומחי' כל נברא ונברא בפרט כו', אבל יחיד חי העולמי' מלך דחי העולמים הוא מבחי' מלך לבד, אבל עצמו' אוא\"ס הוא יחיד שהוא יחיד ומיוחד בעצם\nשאינו בגדר מספר ובגדר ריבוי כלל כו'. והנה יחיד הוא שמיוחד בעצם, ואחד הוא היחוד מצד העולמות שהוא א' בז\"ר וארץ וד\"ר כו', כי הכל בטל ומיוחד בתכלית שאינם בבחי' מציאות בפ\"ע כלל כו', וכמשנת\"ל בכ\"ד ענין ה' אחד בכמה אופנים, שגם בזה יש בחי' השגה שהיא ג\"כ עבודה אמיתי' כו', ויש בחי' ראי' שע\"י העמקת דעתו יתאמת אצלו הדבר בבחי' ראי' ממש כו', וזהו עיקר העבודה האמיתי' להיות בבחי' ראי' לאסתכלא דוקא ביקרא דמלכא כו', ועי\"ז האה' היא אה' פנימי' ממש בהתקשרות ודבקות אמיתי בעצמות אוא\"ס ובבחי' תענוג פנימי שמתענג על ה' ונדבק בו בכל עצם נפשו כו'. ואה' זו היא אה' דאהרן, דאהרן אותי' נראה שהמשיך בנש\"י להיות בהם אה' זו דבחי' הסתכלות כו', וזה הי' עבודתו בהעלאת הנרות דאור המנורה הוא בחי' אור אבא כו', וכידוע ההפרש בין אור המנורה ואש המזבח, דאש המזבח הוא בחי' ה\"ג שבמל' ושרשם מבחי' גבו' דאימא כו', ואור המנורה הוא בחי' אור אבא שזהו בחי' הראי' באלקו' כו', והז' נרות הן ז' מדות והוא שהמדות יקבלו בחי' אור אבא כו', וזהו האה'\nשע\"י בחי' הראי' וההסתכלות דלאסתכלא ביקרא דמלכא כו', וזהו בחי' הסתכלות דז\"א מלמטלמ\"ע ועי\"ז נמשך בחי' הארת פנים מלמעלמ\"ט, וכמ\"ש עיני ה' אל צדיקים כו' עין ה' אל יראיו, דכאשר מתחלה עיני תמיד אל הוי' מלמטלמ\"ע עי\"ז נמשך השפע מלמע' בחי' עין ה' כו', וי\"ל שזהו ההמשכה ע\"י התו' שהיא בבחי' המשכה מלמעלמ\"ט ומאיר בזה בחי' עצמות אוא\"ס בגילוי ממש כו' (וענין ההמשכה בזה י\"ל שהראי' דאלקו' היא בבחי' התיישבות בנפשו כי זה שע\"י הראי' נעשה בבחי' רצוא מלמעלמ\"ט ה\"ז מצד החידוש דבר שמתפעל מאד בנפשו, ולכן הדבקות בזה הגם שהיא בבלתי מורגש לגמרי מ\"מ היא בבחי' התלהבות ובבחי' כליון כו', והענין מה שזהו אצלו בבחי' חידוש דבר הוא מפני שהוא בעצמו הוא מהות דבר בפ\"ע עדיין שאינו בבחי' ביטול ממש להיות בבחי' כלי אל האור שיתיישב אצלו ע\"כ הוא בבחי' רצוא כו', אבל ההמשכה מלמעלמ\"ט הוא שנעשה בבחי' ביטול ממש שהוא כלי ממש לאלקו' וע\"כ הראי' אצלו בבחי' התיישבות ובא הגילוי דאוא\"ס בבחי' קיום המצות בפו\"מ שכ\"ז הוא כלים אל הגילוי כו', וכמו משה דודבר ה' אל משה פנים אל"],[3601331196,"פנים בבחי' ראי' ממש והי' כלי לזה שהי' אצלו בבחי' התיישבות כו', כי לא הי' בבחי' מהות ומציאות אחר כלל וע\"כ הי' הראי' אצלו בבחי' התיישבות בתומ\"צ כו', וי\"ל שזהו בחי' שושבינא דמלכא ושושבינא דמטרוניתא דאהרן הי' שודמ\"ט להיות בחי' האה' בתענוגי' מלמטלמ\"ע ומשה שוד\"מ בחי' המשכת הראי' מלמעלמ\"ט כו').\n<b>וזהו</b> כמים הפנים אל הפנים דפנים תתאין הן בבחי' הסתכלות לגבי למע' ועי\"ז נראים ומתגלים פנים עילאין כו', והוא ע\"י לבושין דמצות שהן בחי' אבני שיש טהור תר\"ך מצות כמשנת\"ל שע\"י נמשך גילוי האור, והן הלבושים שעשה משה ועשית בגדי קדש כו', והיינו שנמשך בהם וע\"י גילוי אוא\"ס כו', וזהו ע\"י הקדמת האה' דרעו\"ד אה' בתענוגים כנ\"ל שעי\"ז הוא בחי' הגילוי ע\"י הלבושים דמצות כו'. והנה כמים הפנים אל הפנים כן לב האדם אל האדם ב' בחי' אדם אדם עילאה ואדם תתאה בחי' ז\"א ומל', ופי' אדם תתאה היינו בחי' המל' כמו שהיא בבי\"ע כו' וכמשנת\"ל, וענין לב האדם אל האדם הוא בחי' העלאת מ\"ן דבי\"ע לבחי' ז\"א דאצי' כו', ועז\"א כמים הפנים אל הפנים דפנים תתאין ע\"ס דאצי' מעלים מ\"ן לפנים עילאין בחי' ע\"ס הגנוזות ועושין עי\"ז בחי' פנים למע' להיות המשכת מ\"ד כנ\"ל, שזה אינו דבר חדוש כ\"כ להיות שאינו רחוק ערכם כ\"כ שהרי גם אצי' הוא אלקו' ממש ואיהו וחיוהי חד ואיהו וגרמוהי חד כו', כן לב האדם אל האדם דאדם תתאה מעלה ג\"כ מ\"ן לאדם עילאה, דהגם\nדבי\"ע רחוק ערכם מאד מבחי' ז\"א דאצי' שזהו עדיין ממדרי' עצמי' דאצי' ובי\"ע הן נבראי' נפרדי' בבחי' יש כו', ומ\"מ ה\"ה מעלים מ\"ן לבחי' ז\"א דאצי', וכפי אופן העלאת מ\"ן שלהם נעשה בחי' הפנים בבחי' אדם עילאה להיות המשכת מ\"ד כו', וזה גופא הוא ע\"י בחי' כמים הפנים אל הפנים שנת\"ל דקודם האצי' הי' בבחי' עתיק וכן באוא\"ס שלפה\"צ ההעלאת מ\"ן מיני' ובי' והו\"ע גליף גליפו בטה\"ע שנמשך חסד פשוט בעצמות א\"ס בחי' חפץ חסד הוא להיות ההעלאת מ\"ן תופס מקום שז\"ע החקיקה בעצמות ע\"י בחי' החסד כו' כנ\"ל, וע\"כ גם העלאת מ\"ן דבי\"ע תופס מקום בבחי' אדם עילאה כו'. והענין דמאחר שכללו' הענין דבאתעדל\"ת אתעדל\"ע הוא לא מה שהדבר מחייב כן רק מפני שכך עלה ברצונו ית' כנ\"ל, והרי מה שעלה ברצונו הוא העבודה דבי\"ע כו', וכידוע דתכלית הכוונה הוא בעולמות בי\"ע דוקא שז\"ע במי נמלך בנשמותיהן ש\"צ, היינו בעבודה דנש\"י ובקיום המצות למטה דוקא דסוף מעשה זו היא דוקא שעלה במח' ורצון תחלה בבחי' הרצון הנעלם בחי' כי חפץ חסד כו' (וכמשנת\"ל דשם הנמלך קדום כו'), וע\"כ\nלב האדם התחתון מעורר לב האדם העליון עם היותם באין ערוך ויש פרסא המפסקת ביניהם כו', וממילא גם ההמשכת מ\"ד הוא שגם ההמשכה בבי\"ע ה\"ז אלקו' ממש כו', דכמו שההמשכה מבחי' פנים עילאין לבחי' פנים תתאין הוא אותו האור ממש כי הפרסא אינה פרסא המעלמת שהרי הפנים תתאין נראים בפנים עילאין כו', כמו\"כ מה שלב האדם התחתון מעורר וממשיך מ\"ד מאדה\"ע ע\"י העלאת מ\"ן שלו ה\"ז גילוי אלקו' ממש כו'. והנה לכאו' א\"מ והלא בין אצי' לבי\"ע הפרסא היא מפסקת ומעלמת כו', וע\"ה שאינו בבחי' העלם גמור ח\"ו מ\"מ מה שנמשך הוא רק אור של תולדה לבד כו', איך הוא שמ\"מ נמשך גילוי אלקו' ממש בבי\"ע כו'. אך הענין הוא דמה שהפרסא היא בבחי' הפסק זהו בענין ההתהוות כו', אבל ע\"י העבודה והעלאת מ\"ן נמשך"],[3601331197,"גילוי אלקו' בעולם כו', וכ\"ה גם באצי' כו', שהרי באצי' יש ג\"כ פרסא בין חו\"ב לז\"א שהגילוי בז\"א אינו כמו בחו\"ב כו' וכמשי\"ת, וז\"ש באד\"ר הנ\"ל פנים דלבר אית זמן דנהרין ואית זמן דלא נהרין כו', והענין הוא כמשנת\"ל דבאצי' יש ב' מדרי' כמו שאצי' הוא מצ\"ע וכמו שאבא עילאה מקננא באצי' כו', והיינו בחי' הביטול דחכ' כו', והו\"ע הרדיפה הנ\"ל העלאת מ\"ן דבחי' הסתכלות כו' כנ\"ל, וכמו\"כ הוא בבי\"ע שע\"י עבודה והעלאת מ\"ן נמשך גילוי אלקו' כי אין הפרסא מעלמת כו', והעבודה בבי\"ע הוא לזכך הפרסא ולהפוך הצמצום לאור כו' וכמשי\"ת, וגם העבודה בבחי' רעו\"ד כו', ועי\"ז גם בבי\"ע מאיר אלקו' בגילוי ממש כו'.\n<b>ועפ\"ז</b> יובן מ\"ש וספרתם לכם ממחרת השבת כו', פי' וספרתם הוא ל' ספירו' ובהירות כו' ואו' וספרתם לכם שיהי' הגילוי לכם דגם בבי\"ע יהי' גילוי אלקו' כו', ושרש ההמשכה הוא ממחרת השבת, שבת הוא בחי' חכ' כו', ובכדי שיהי' גילוי אלקו' למטה זהו ע\"י ההמשכה מבחי' עצמו' שלמע' מאצי' כו', וז\"ש ממחרת השבת לא ממחרת היו\"ט, דיו\"ט הוא מוחין דאימא ושבת מוחין דאבא, וע\"כ או' ממחרת השבת דהיינו מלמע' מהחכ' כו', וע\"י מה הוא ההמשכה עז\"א מיום הביאכם את עומר התנופה, עומר הוא שעורים מאכל בהמה והוא בירור הנה\"ב כו', דזה הוא העבודה התמידי' דנשמות דבי\"ע לברר ולזכך את הנה\"ב שלא יהי' חומרי וגס ולא יומשך אחרי חומרי' העולם כ\"א יהי' בטל ונכנע לנה\"א כו', עד שגם הנה\"ב יהי' בטל לאלקו' כו', וע\"י זיכוך הנה\"ב נעשה זיכוך הפרסאות למע' כו' (וגם נעשה עי\"ז תקון הכלים כו'). וענין עומר התנופ\"ה הוא כמ\"ש והניף את העומר כו' לרצונכם שזהו בחי' רעו\"ד כו', והיינו שצ\"ל ב' הענינים העבודה בזיכוך הנה\"ב וגם צ\"ל העבודה דרעו\"ד לאסתכלא ביקרא דמלכא\nשזה מעורר בבחי' עצמות אוא\"ס כו'. ועז\"א שבע שבתות תמימות תהיינה, דהנה שבת הוא בחי' חכ' ותמימות הוא שלמות השבת היינו בחי' שבת שבתון שבתו של שבת שזהו המשכת בחי' עתיק בחכ' כו', וזהו תמימות ע\"ד שא' במשנה דערכין שנה תמימה להביא חדש העבור, והיינו דתמימה הוא השייך להשנה ומ\"מ גם בלא זה הוא שנה כו', ולמע' הוא בחי' ע\"ס הגנוזות לגבי ע\"ס הגלויות שהגנוזות שייכים אל הגלויות שה\"ה מקורי האורות כו', ומ\"מ הגלויות בעצמן הן ע\"ס שלמות מפני הבדלת הערך דהגנוזות (שאינם בבחי' מקור ממש) אא\"ל שבלא זה הוא חסרון ח\"ו (ועמשנת\"ל ד\"ה פדה בשלום). אמנם בהמשכת וגילוי בחי' פנים עילאין זהו בחי' השלמות והתמימות כו', וזהו שא' במד\"ר אימתי הן תמימות כשישראל עושין רש\"מ, וידוע דערש\"מ הוא קיום המצות שע\"י רעו\"ד כו', שעי\"ז נמשך בחי' תמימות הנ\"ל, וזהו וספרתם לכם שהגילוי יהי' לכם דוקא, ושרש ההמשכה הוא ממחרת השבת כו', והוא ע\"י עומר התנופה בירור וזיכוך הנה\"ב ורעו\"ד כו', ועי\"ז שבע שבתות תמימות תהיינה שלימות השבת שבת שבתון בחי' שבתו של שבת כו'."],[3601331198,"<h3>בס\"ד. ש\"פ בהוב\"ח, העת\"ר</h3>\n<b>כי</b> תבאו אל הארץ כו' ושבתה הארץ שבת לה', שש שנים תזרע שדך כו' ובשנה השביעית שבת שבתון יהי' לארץ כו', וצ\"ל מ\"ש כי תבאו כו' ושבתה משמע דמיד בבואם ושבתה הארץ, ואיך שייך שביעית קודם השש שנים, וכמו שאו' אח\"כ שש שנים תזרע כו' ובשנה השביעית כו', וגם אינו שייך שביתה קודם עבודה כו'. גם צ\"ל מה\"ע שביתת הארץ, הלא השביתה לכאו' הוא לבנ\"א העובדים כו', וכאן הכוונה שביתת הארץ, שהרי שארי עבודות מותר בשביעית רק עבודת הארץ אסור, וצ\"ל מה\"ע שביתת הארץ כו'. ובזהר אי' ע\"ז ר\"א פתח זאת תורת העולה האי קרא אוקמוהו בכנס\"י והוא עליית המל', ומסיים ושבתה הארץ נייחא ודאי. ולהבין כ\"ז ילה\"ק משנת\"ל בענין כמים הפנים אל הפנים שהן פנים עילאין ופנים תתאין, פנים עילאין ע\"ס הגנוזות ופנים תתאין ע\"ס דאצי' כו', דע\"ס הגנוזות אין להם מציאות אפי' בהעלם ונעשים רק ע\"י העלאת מ\"ן כו', וכמ\"ש בזהר ברדיפו דההיא מח' עילאה מטי ולא מטי עד ההיא פרסא. ונת' דהפרסא היא בחי' כתר שהיא הפרסא שבין המאציל לנאצלים כו', וברדיפא דההיא מח' שזהו\nהעלאת מ\"ן דחכ' בפרט והע\"ס בכלל כו', עי\"ז נעשים הע\"ס הגנוזות כו'. ונת' דההעלאת מ\"ן הוא בחי' אה\"ר אה' בתענוגים שע\"י הראי' באלקות שעי\"ז נעשים הע\"ס הגנוזות שהן א\"ס ממש, וכמו\"כ ההמשכה היא א\"ס כו', כן לב האדם אל האדם, אדם תתאה הוא בחי' מל' היורדת לבי\"ע שמעורר ומעלה מ\"ן בלב אדה\"ע, ונמשך עי\"ז גילוי אלקו' בבי\"ע, דע\"י העבודה למטה בזיכוך הפרסאות ובבחי' רעו\"ד נמשך גילוי אוא\"ס בבי\"ע כו', וההמשכה היא ע\"י לבושי המצות שז\"ע אבני שיש טהור תר\"ך מצות כשהן בבחי' ערש\"מ שע\"י נמשך גילוי אוא\"ס ב\"ה גם בבי\"ע כו'.\n<b>והנה</b> כ\"ז משנת\"ל בענין כמים הפנים אל הפנים זהו בחי' פרסא הראשונה שבין אוא\"ס המאציל אל האצי' כו', שע\"י פרסא זו מאיר גילוי אוא\"ס כי אינה פרסא המעלמת כו', והגילוי הוא גם בבי\"ע כו', שע\"י העבודה למטה בבחי' רעו\"ד נמשך גילוי אוא\"ס ב\"ה גם בבי\"ע כו'. אמנם הפרסא השני' היא באצי' בין המוחין אל המדות היינו בין חו\"ב לז\"א והוא הרקיע שע\"ג חיוון עילאין, וכמ\"ש ועל ראשי החיות רקיע כעין הקרח הנורא דמבטן מי יצא הקרח כו', דשרשה מבחי' הבינה והוא בחי' החשמל שנמשך מחיצוני' בינה ונעשה בחי' פרסא בין הבינה אל הז\"א ומלביש ומקיף לזו\"ן כו' כנודע. והענין הוא דהרי כתי' הנסתרות לה' אלקינו והנגלות לנו ולבנינו דחו\"ב הן בחי' נסתרות עדיין שלמע' מבחי' העולמות וכמא' אלפיים שנה קדמה תו' לעולם כו', ובחי' ז\"א הוא הנגלות כו' להיות בבחי' מקור לעולמו' כו', וידוע דמוחין ומדות הם מהותים נבדלים בעצם, דמוחין הן ביטול דכל גיא שוטה דגאות הוא מחמת השטות היפך החכ', אבל חכ' הוא ביטול, דחכ' בפרט וכן מוחין בכלל הן בחי' ביטול וזהו\nמצד הריבוי גילוי אור שבמוחין ה\"ז פועל הביטול בנפש כו', ולכן בחכ' דוקא אתברירו, דענין הבירור הוא הפרדת היש וביטול היש, והוא ע\"י החכ' דוקא, לפי שחכ' הוא ביטול ופועל הביטול בכל דבר כו', וע\"ה שהמוחין הן תוקף בנפש והוא"],[3601331199,"העדר ההתפעלות שאינו מתפעל משום דבר ואינו נופל בעצמו ואינו אובד עצמו בשום דבר (ער פארלירט זעך ניט), הנה זהו התיישבות לא ישות, דענין ההתיישבות הו\"ע האמת כו' וקושטא קאי כו', אבל בעצם הוא בחי' ביטול כו', ולכן העדר ההתפעלות הוא שבדבר שא\"צ להתפעל אינו מתפעל כלל, אבל בדבר שצריכים להתפעל ה\"ה מתפעל בפנימי' ביותר רק שאינו בהתגלות ואינו אובד עצמו ח\"ו, אבל הענין נוגע לו בפנימי' ביותר וזהו מצד הביטול ולכן מתעורר מאד, ונוגע לו הענין בפנימיותו כו', משא\"כ המדות הן בבחי' יש, וכמו אהוי\"ר גם בעבודה הוא יש מי שאוהב ויש מי שירא כו', ואהוי\"ר שאינן בבחי' יש אינן במדרי' המדות וכמו אה' עצמי' שזהו התקשרות עצמי וכן יראה פנימי' א\"ז מדות כו', אבל המדות הן בבחי' ישות כו', ויסוד המדות הוא הרגש עצמי דבלא הרגש עצמי אא\"ל המדה, ומוחין אינם הרגש עצמי ואדרבה הרגש עצמי מונע ומעכב לענין המוחין כו' וכמ\"ש במ\"א ונת' ג\"כ לעיל (ד\"ה כי ה' יתן חכ' ובכ\"ד), וידוע דמוחין הן בבחי' עלי' ודביקות למעלה ולכן ג\"ר דכל פרצוף הן בחי' שבת כו',\nוהמדות הן בבחי' ירידה והמשכה למטה כו', והמוחין הן בבחי' הבדלה וכמו מוחין דגדלות הן בבחי' הבדלה, והמדות הן בבחי' המשכה כו', וכללות ענין המדות הוא התפשטות הנפש ולכן נק' אברים וכמו אברין דמלכא חסד דרועא ימינא כו', מפני שהן בבחי' התפשטות מן הנפש כו', והמוחין הן עצמי' והן בבחי' העלם בעצמו כו', וכידוע דגם בחי' התפשטות והתגלות המוחין הוא מחמת בחי' קטנות המוחין כו', דיותר משהעגל רוצה לינק הפרה רוצה להניק, אבל זהו קטנות מוחין בחי' מוחין דב\"ן כו', אבל גדלות המוחין הוא לעצור ולעכב בעצמו דוקא כו' וכמ\"ש במ\"א (וכמשנת\"ל ד\"ה הנ\"ל דכמו כללות ההפרש בין עונג ורצון דעונג הוא בהעלם בעצמו דוקא והרצון הוא במרוצה לאיזה דבר כו', כמו\"כ הוא במוחין ומדות שהמוחין הן בבחי' דבקות למע' והמדות הן בבחי' ירידה לאיזה דבר כו'). ולהיות שהן מהותים נבדלים בעצם ע\"כ צ\"ל פרסא ביניהם כו', אמנם הפרסא היא ג\"כ מחברת אותם כו', והוא להיות לידת המדות מן המוחין ושיומשך מהמוחין אל המדות כו' רק שזהו המשכה שלא בהדרגה כו', והיינו שע\"י הפרסא\nנעשה ממהות מוחין מהות מדה כו' וכמשנת\"ל (ד\"ה ויקחו לי תרומה), והפרסא היא מבינה שהרי ע\"י הפרסא נעשה לידת המדות וע\"כ מבינה דמשם שרש הז\"א משם היא ג\"כ הפרסא כו'. והענין הוא דהנה נת\"ל (ד\"ה ואתה תצוה) דהפרסא יש בה ג\"כ העלם וגילוי, והיינו שהוא העלם לגבי מדרי' העליונה וגילוי קצת לגבי מדרי' התחתונה כו', והוא שהמוחין מתעלמים בהפרסא, ועל המדות הוא בבחי' אור מקיף כו', והיינו דכאשר מתפעל בשכלו על הענין נמשך זה ע\"י דעת המתפשט ללב שהלב נמשך אחר המוח והוא ביטול המדות שמתבטלים ע\"י האו\"מ כו' (והו\"ע ההתעלמות שע\"י מיצר הגרון שזהו ע\"ד ענין ההשתוממות כו' וכמשנ\"ת שם), ועי\"ז מקבלים אור המוחין להיות לידת המדות כו', ומאחר שע\"י הפרסא נמשך או\"מ מהמוחין על המדות ע\"כ הפרסא היא מהמוחין היינו מבחי' בינה כו', וזהו שמבו' במ\"א דת\"ת דאימא שנעשה כתר לז\"א זהו הפרסא דהיינו בחי' המקיף הנ\"ל (בלק\"ת בהביאור דעל כל כבוד מבו' דת\"ת דאי' הן בחי' המדות שבשכל כו' והיינו דההתפעלות שכלי מאיר ע\"י דעת המתפשט בלב והוא בחי' מקיף הנ\"ל), ומ\"מ ההמשכה מהמוחין אל המדות אינו בהדרגה כו',"],[3601331200,"דמה שנמשך מהמוחין אל המדות הוא בחי' האחרונה שבמוחין (והוא הבכן כו') ונעשה מהות מדה כו', וזהו מי ברא אלה מי בחי' בינה ברא אלה ע\"י המסך והפרסא כו', וכ\"ה בזהר בראשית ד\"ל ע\"א דמי ברא אלה הו\"ע מבטן מי יצא הקרח כו', ובפ' לך דפ\"ה סע\"ב כ' דמבטן מי יצא הקרח הו\"ע מי העיר ממזרח כו', וברבות פ' בא פט\"ו אי' בא אברהם התחיל להאיר שנא' מי העיר ממזרח הרי מפרשי' העיר כמו האיר, והיינו שע\"י הפרסא והלבוש נמשך ג\"כ האור והגילוי מבינה לז\"א כו'.\n<b>והענין</b> הוא דהנה אי' בזהר יתרו דס\"ז ע\"א ברזא דשמא קדישא אית מלך וכהן כו', פי' שמא קדישא הן הע\"ס דאצי' ונק' שמא קדישא לפי שכל הגילוי אור דע\"ס הוא מבחי' מל' דא\"ק ובשרש שרשו מבחי' מל' דא\"ס שהוא בחי' שם בלבד כו', ופי' ברזא דשמא קדישא הוא בחי' החכ' שנק' רזא דשמא, וכ' הרמ\"ז לפי שהחכ' אינו מאיר בגילוי ממש באצי' רק ע\"י התלבשותו באימא (וצ\"ע ממ\"ש בע\"ח שמ\"ז פ\"ד, וי\"ל דס' ההשתל' הוא שחכ' מתלבשת בבינה כו', וכמו נה\"י דאי' נעשה מוחין לז\"א, ובתוכם גם בחי' נה\"י דאבא רק שהן בבחי' התלבשות בנה\"י דאי' כו', גם המעבר דבינה ה\"ז ג\"כ התלבשות כו' וכמשנת\"ל (ד\"ה ויהי ביום השמיני), גם י\"ל דז\"ע מוחין דאבא שלמע' מהשתל' והכוונה כאן על בחי' יחוד פנימי דאו\"א כו' וכ\"כ במ\"א, וההתלבשות בפנימי' בינה אינו בבחי' התעלמות כו', דפנימי' בינה משתווה כמו פנימי' החכ' וכמ\"ש באוצ\"ח דכשם שפנימי' אבא פנימי' עתיק כן פנימי' בינה פנימי' עתיק כו' ומ\"מ ה\"ז התלבשות כו'), וברזא דשמא קדישא ר\"ל דאופן המשכת האור בבחי' חכ' הנק' רזא דשמא\nקדישא (כן נר' בפי' הרמ\"ז) הוא מבחי' מלך וכהן כו', אית מלך לעילא ברזא דקה\"ק וכהן משמש תחותי' ופי' הרמ\"ז מלך לעילא הוא בחי' מל' דא\"ק שנעשה עתיק לאצי' כו', דהנה בחי' א\"ק נחשב עדיין מבחי' הא\"ס כו' וכמשנת\"ל (ד\"ה אח\"מ) דא\"ק זהו בחי' עצמו' א\"ס שאחה\"צ כו', ולכן נק' א\"ק שזהו בחי' אדם שעלה במח' בא\"ס קדמון לכל הקדומים שהוא ג\"כ בבחי' א\"ס כו', ובחי' מל' דא\"ק הוא שנעשה בחי' כתר ועתיק לאצי' כו', ולכן בחי' מל' דא\"ק ממוצע בין הא\"ס לנאצלים שיש בו ממדרי' התחתונה שבא\"ס שזהו בחי' מל' דא\"ק הנק' סוף מדרי' הא\"ס כו', וגם הוא שרש ומקור וראש לכל הנאצלים בבחי' הכתר כו', והיינו שבו וע\"י מתחברים תמיד עולמות הא\"ס בעולם הנאצלים כי הוא מקבל השפע מעולם הא\"ס (בחי' א\"ק) ומביא וממשיך לעולם הנאצלים כו', וכידוע דבחי' מל' הוא בחי' מקבל ובחי' משפיע שז\"ע ואמונה כל זאת וקיים עלינו ל' נקבה ול' זכר, שמקבלת מהספי' שלמע' ומשפעת במדרי' שלמטה ממנה כו' וכמ\"ש במ\"א, וכמו\"כ הוא בבחי' מל' דא\"ק שמקבלת מעולם הא\"ס בחי' א\"ק ומשפעת בנאצלים כו'.\n<b>וזהו</b> אית מלך לעילא בחי' מל' דא\"ק שנק' מלך מב' טעמים להיותו בחי' מל' דא\"ק, ומפני שהוא שרש ומקור לנאצלים כו', ובחי' מל' דא\"ק ה\"ז בבחי' הבדלה מהנאצלים וכשנעשה בחי' כתר ה\"ז בבחי' מקור לנאצלים כו', ברזא דקה\"ק הוא בחי' הכתר וכידוע דקדשים הם חו\"ב והכתר שעליהם הוא בחי' קה\"ק כו', וכהן משמש תחותי' ברזא דאור קדמאה הוא בחי' חכ' דאצי' דחח\"ן מימין שהוא קו החסד כו', ולכן נק' כהן דכהן הוא בחי' חסד ולהיות שהחכ' היא ג\"כ חסד ה\"ז בחי' כהן כו', והרמ\"ז פי' דכהן הוא בחי' חסד דאריך שמתלבש בחכ' ואז גם החכ' היא בחי' חסד כו', דהנה פי' כהן הוא עובד"],[3601331201,"וכמ\"ש לכהנו לי ות\"א לשמשא קדמי, וכן פי' רש\"י כהונה הוא ל' שירות, וכמו עד\"מ המשמש לרבו שגורם עי\"ז תוס' שפע וברכה מרבו, דענין השימוש הוא ב' דברים, הא' ההעלאה וכמו שהמשמש ממלא החסרון והו\"ע העלאת מ\"ן כו', והב' ההמשכה שנמשך עי\"ז כו', וכמו גבי יצחק דכתי' ועשה לי מטעמים כו' בעבור תברכך נפשי כו', כי ההמשכה מלמע' צריכה על מה לחול והיינו ההעלאת מ\"ן והעיקר הוא ההמשכה רק שצריכים לזה העלאה מלמטלמ\"ע כו', וז\"ע השירות בחי' העלאת מ\"ן להיות תוס' ברכה ושפע כו', וכמו בעבודת כה\"ג ביוהכ\"פ שנכנס לקה\"ק עי\"ז נמשך סליחת עוונות, וכמש\"א בסדר העבודה כלי כפרה לעמך נתתו שהוא הי' הכלי להמשכת האור דאוא\"ס ב\"ה להיות סליחת עוונות ע\"י העלאת מ\"ן שלו בבחי' הביטול שלמע' מטו\"ד שז\"ע העבודה שלו בהקטרת קטרת לפני ולפנים בבחי' ביטול עצמי דיחידה כו', ולכן הי' העבודה בבגדי בד ובגדי לבן דוקא שזהו בחי' הרצ\"פ שלמע' מטו\"ד כו' וכמ\"ש במ\"א. וכמו\"כ יובן למע' בהעבודה דבחי' כהן בחי' חכ' בהעלאת מ\"ן לבחי' הכתר (והו\"ע כמים הפנים כו' רדיפו דההיא\nמח' עילאה כו' שנת\"ל), וההעלאת מ\"ן היא בבחי' אה\"ר ואהב\"ת שזהו בחי' חסד דאריך המלובש בחכ' כו', ה\"ז גורם תוס' הארה והמשכה חדשה מבחי' הכתר לחכ' תחלה שהיא הכלי אל האור והגילוי כו', וממנה מסתעפת ההמשכה לכל מה שלמטה ממנה בקוין כו'.\n<b>ועוי\"ל</b> בפי' מאה\"ז הנ\"ל אית מלך לעילא ברזא דקה\"ק מלך הוא בחי' בינה, וכידוע בפי' אלקי' חיים ומלך עולם דקאי על הבינה, דז\"א הוא בחי' עולם ובינה נק' מלך עולם כו', וזהו ג\"כ ברזא דקה\"ק שנק' הבינה כן מפני שכתר וחכ' מלובשים בה וכידוע דהתגלות עתיק הוא בבינה, כי חכמה הוא בחי' כח מ\"ה בחי' אין בבחי' נקודה שאינו בבחי' התפשטות לאורך ורוחב לכן אין שם עדיין העונג בהתגלות ממש, ובבינה שהוא התגלות הדבר בהשגה בהתרחבות באו\"ר שם מתגלה התענוג כו' וכמ\"ש בסי' בכוונת המקוה, וסבת ההתרחבות דבינה זהו גופא מבחי' תענוג, דכל התרחבות הוא מבחי' העונג דוקא וכמו מים מצמיחים כו', וכמו שמועה טובה תדשן עצם כו', וכן התרחבות ההשגה הוא מצד העונג דוקא כו', וכנראה ביותר בענין ההתבוננות דכשמתבונן באיזה ענין אלקי הנה כשיש לו חיות ועונג בהענין נמצאים אצלו כמה ענינים שבזה מתרחב הענין עד שמושג אצלו בטוב כו', והיינו התענוג בעצם ענין ההשגה עושה התרחבות, ובהתרחבות ההשגה מתגלה התענוג כו', ולכן נק' בינה קדה\"ק קדשים הוא חו\"ב שהן\nתרדל\"מ, וקדש בחי' עתיק המתגלה בבינה כו'. וכהן משמש תחותי' הוא בחי' חסד דאצי' שהוא המשכה והתפשטות התגלות ראשונה הנמשך ומתגלה מבחי' בינה כו', וכמא' חסד שירותא דעלמא עילאה, עלמא עילאה הוא בחי' בינה הנק' יום ההוא שבבחי' העלם עדיין בחי' עדאתכ\"ס כידוע, והתחלת הגילוי הוא בחי' החסד כו', ולכן נק' כהן המשמש תחות הבינה היינו שבחי' החסד מקבל ההשפעה מבינה, ובו וע\"י נמשך ההשפעה מהבינה בכל האצי' וכמ\"ש בזהר אמור דק\"ג ע\"ב ע\"פ יומם יצוה ה' חסדו דא עננא דאהרן כו', שהוא הממשיך בכל המדות כו' יומא דאזיל עם כולהו יומין כו', וזהו והוכן בחסד כסאו שהחסד הוא בחי' כסא למלך עילאה היושב על הכסא, והכסא היא בחי' מרכבה אל המלך המקבלת השפעת אורו כו', וכמו האבות הן המרכבה בחי' חג\"ת שהן מרכבה לאו\"א כו' וכמ\"ש בתו\"א פ' יתרו. אית מלך"],[3601331202,"לתתא כגוונא דההוא מלך עילאה והיינו בחי' מל' דאצי' שהיא מקור לבי\"ע וכמ\"ש ותתן טרף לביתה שמשפעת אור וחיות לבי\"ע כו', ונק' ג\"כ מלך העולם על עולמות בי\"ע ולכן נק' מלך לתתא כו', ותחותי' אית כהן דמשמש לי' רזא דמיכאל כה\"ר והיינו בחי' חסד דברי' והו\"ע מיכאל מקריב נשמותיהן ש\"צ ע\"ג המזבח, מזבח היא בחי' מל' דאצי' (ואע\"ג דמל' זהו בחי' המלך כנ\"ל אך יש כמה מדרי' במל', ובמ\"א מבו' דמלך זהו בחי' כתר מל' והוא בחי' הרוממות שבמל' בחי' והים עומד עליהם מלמעלה כו', וע\"י י\"ב בקר שהן ד' מחנה שכינה דעיקרם הוא בחי' החסד שזהו מיכאל כו' הוא ההעלאה בבחי' מל' והמשכת האור ממל' כו', ובחי' כתר מל' הוא בחי' המל' כמו שהיא באצי', וזהו בחי' המלך כו', ומזבח הוא בחי' מל' היורדת לבי\"ע, ולכן הי' המזבח בחצר אוהל מועד וידוע דהחצר הוא נגד עולמות בי\"ע כו', ובמ\"א מבו' דבחי' מל' המלובש בהיכל ק\"ק דברי' זהו בחי' המלך, וידוע דהיכל קה\"ק דברי' מתאחד ממש באצי' כו' שזהו בחי' כח\"ב דברי' המתאחד באצי' כו', ומזבח הוא בחי' ה\"ג דמל' ונר' שזהו בחי'\nיסוד שבמל' שבבחי' רצוא כו', והוא בחי' מל' היורדת לבי\"ע כו'), ומיכאל מקריב כו' היינו כל העלאת מ\"ן מלמטלמ\"ע מביא אותם ע\"ג מזבח שיעלו לבחי' המל', ועי\"ז המלך בחי' מל' דאצי' משפיע למטה בבי\"ע כו'. נמצא דבחי' חסד דברי' הוא כהן דלתתא שע\"י עולה אתעדל\"ת ומעלה אותם ע\"ג המזבח (והיינו שפועל בנבראים דבי\"ע להיות בהם הביטול לאלקו' שזהו העלאת מ\"ן שלהם כו', וכמו שמלאך גבריאל מעורר נשמות בג\"ע וכן למטה חצות לילה אקום להודות לך כו' כידוע, כמו\"כ מיכאל מעורר ע\"י בחי' החסד להיות בנבראים בחי' הביטול והעלאת מ\"ן כו', או שמעלה בחי' העלאת מ\"ן שלהם במדרי' עליונה יותר וכמו העלי' בהיכל קה\"ק דברי' שמתאחד באצי' כו'), ועי\"ז יהי' ההמשכה מבחי' מל' לבי\"ע וההמשכה היא ג\"כ ע\"י בחי' חסד דבריאה כו'. ונמצא יש ג' מדרי' כהן, הא' בחי' רב חסד דאריך הממשיך מאוא\"ס המאציל אל הנאצלים, הב' בחי' חסד דז\"א הממשיך אור הבינה, הג' חסד דברי' הממשיך מבחי' מל' דאצי' כו' (וי\"ל שז\"ע כה\"ג סגן וכהן הדיוט כו').\n<b>והנה</b> בזהר ויחי דרי\"ז ע\"א אי' כה\"ג לעילא כה\"ג לתתא, לבושין דיקר לעילא לבושין דיקר לתתא כו', והיינו דכשם שהכהן למטה הי' עבודתו בלבושים דוקא, דגם כהן המשוח צריך ללבושים, דהרי בסוף ב\"ר ובזמן ב\"ש הי' כהן המרובה בגדים דהיינו שכל התעוררות האור הוא ע\"י הלבושים כו' וכמ\"ש במ\"א, אך גם המשוח בשמן המשחה שזהו שהגילוי מלמע' כו' מ\"מ הי' צריך ללבושים כו', שזה הי' חטא בני אהרן דמחוסרי בגדים נכנסו כו' וכמשנת\"ל סד\"ה אח\"מ, כמו\"כ למע' כל בחי' כהן צריך ללבושים, דלהיות הגילוי אור הוא ע\"י הלבוש דוקא וכמ\"ש בזהר פקודי דרכ\"ט ע\"א דבגדי כהן הם ע\"ד ויבא משה בתוך הענן, שהענן הי' לבוש למשה שעי\"ז הי' ביכולתו לקבל את האור כו', כמו\"כ הן הלבושים של הכהן שע\"י יוכל האור להתקבל כו'. והן ג' מיני לבושי' שהן ג' בחי' פרסאות, הא' הפרסא שבין אוא\"ס המאציל אל הנאצלים בחי' אבני שיש טהור כו' שעי\"ז הוא גילוי אור הכתר בחכ' כו', והב' הפרסא שבין הבינה לז\"א, וכמ\"ש המק\"מ פ' בשלח דס\"א ע\"א בש' הרח\"ו ז\"ל בפי' הוד והדר לבשת אשר נו\"ה\nדבינה הם נעשים חשמל בבחי' מלבוש ע\"ג ז\"א (כמדומה דאי' בת\"ז הוי' אד' בנו\"ה וביסוד מתאחדים ומשתלבים זע\"ז כו', וי\"ל"],[3601331203,"שההתכללות הוא ע\"י ת\"ת דאי' דמשם שרש החשמל כמ\"ש במאו\"א), והיינו שעי\"ז יוכל לקבל אור הבינה כו', והג' הפרסא שבין אצי' לבי\"ע שע\"י הפרסא דוקא יוכל להתקבל אור האצי' בבי\"ע כו'. ובזהר פ' פקודי שם נר' שיש בבגדי כהן ב' מדרי' בחי' אספה\"מ ובחי' אספשא\"מ, והוא דכללות ההפרש בין הפרסא שלמע' מאצי' והפרסא שבאצי' ושמאצי' לבי\"ע, דהפרסא שלמע' מאצי' היא בחי' אספה\"מ שנק' אבני שיש טהור כו', וב' פרסאות הנ\"ל הן בחי' אספשא\"מ. והענין דהנה נת\"ל בענין כמים הפנים אל הפנים שזהו בחי' אה\"ר ואהב\"ת הבאה ע\"י הראי' וההסתכלות באוא\"ס וזהו בחי' החכ' שהיא בחי' ראי' כו', וידוע דחכ' נק' זה בחי' אספה\"מ וכמו משה נתנבא בזה כו', אמנם בחי' הפרסא שבין בינה לז\"א שעי\"ז מאיר אור הבינה בז\"א הרי כבר נת\"ל דבינה נק' ג\"כ כה כדמותינו בחי' שמיעה והשגה שאינו תופס בהעצם ה\"ז בחי' אספשא\"מ כו', אך בזה גופא יש הפרש בין הפרסא שבין הבינה לז\"א דהגילוי הוא מבחי' הבינה ובין הפרסא שבין אצי' לבי\"ע שהגילוי הוא מבחי' המל'. ובעבודה הוא ההפרש בין אהוי\"ר שכלי'\nובין אהוי\"ר טבעי' כו', דאהוי\"ר שכלי' הוא שבא ע\"י השגה והתבוננות כו', ויש בזה ב' אופנים אם שהעיקר הוא התגלות המדות או שהעיקר הוא המוחין, וההפרש אם ההתבוננות הוא בבחי' חיצוני' המוחין או פנימי' המוחין כו', אך גם חיצוני' המוחין הוא בבחי' השגה ממש שמשיג בטוב את הענין האלקי ומעמיק דעתו בזה עד שבא לידי תשוקה גדולה ברשפי אש במדות שבלב באה' ויראה כו', והוא שכחות נפשו האלקי' הן בהתגלות גמורה כו', ופועל גם על הנה\"ב שגם הוא ירצה באלקו' והיינו שכל הכחות של הנה\"ב הן ג\"כ לה' בשעת התפלה עכ\"פ מחמת הארת כחות נה\"א שהן בהתגלות (וא\"ז שפועל עליו בבחי' מקיף לבד כי באופן כזה לא יפעל בנה\"ב שירצה באלקו' כו', כ\"א זהו ע\"י ההתלבשות דנה\"א בנה\"ב דכחות הנה\"א מלובשים בכחות הטבעי' דנה\"ב, והיינו שההשגה אלקי' היא בשכל הטבעי דנה\"ב גם הוא מבין ומשיג את הענין האלקי ובהתפעלות האה' דנה\"א גם הוא מתפעל בהתפעלות אלקי כו', והו\"ע החקיקה מבפנים שבנה\"ב שנעשה בבחי' ביטול כו', וצ\"ל שזהו מ\"ש בסש\"ב דבבינוני הנה\"ב הוא כישן א\"ז שמתבטל\nממילא כ\"א ע\"י שהעבודה היא בכחות הטבעי' כו' וה\"ז בו בבחי' הרגש פנימי שמשו\"ז ה\"ה מתבטל כו', ונק' כישן מפני שאינו מתהפך בזה מהות הנה\"ב ויכול להיות חוזר וניעור ע\"כ ה\"ז רק כמו ישן כו', אבל מ\"מ זהו שהנה\"ב מתבטל ע\"י הרגש פנימי כו', והיינו שההשגה האלקי' דנה\"א היא בבחי' הרגש פנימי בנה\"ב שגם הוא מבין הענין האלקי, וכן האה' האלקי' היא בהנה\"ב בבחי' הרגש פנימי שגם הוא מתעורר באה' כו', ויש שצ\"ל התעסקות יותר עם הנה\"ב להבינו את הענין האלקי, ובפרט בהכחות פרטים שלו לפעול בהם ההכנעה והביטול כו', ומ\"מ ה\"ז רק כישן מפני שאינו מתבטל בעצם מהותו כו'). וגם לאחר התפלה שמסתלק האור מהנה\"ב מ\"מ התגברות התגלות הנה\"א הוא כ\"כ בשעת התפלה וכ\"כ הוא בבחי' הרגש פנימי בנה\"ב עד שעיקר חפצו ורצונו ועיקר התענוג שלו הוא לעבוד את ה' בכל הכחות שלו, ועניני עוה\"ז אינו חפץ בהם ועוד מאוסים בעיניו, כי הכחות הטבעי' הגם שלא נתהפכו בעצם מהותם, הרי נתבטלו ע\"י התגברות הכחות דנה\"א שגם הם חפצם ותשוקתם הוא בעניני אלקו', ואין להם שום חפץ ותענוג בענינים הגשמי' רק כל חפצם הוא"],[3601331204,"בעניני אלקו' דוקא כו', והעיקר כאן הוא המדות דנה\"א שהן בהתגלות שהיא האה' ברשפי אש כו', אך א\"ז רק מדות לבד היינו רק התגלות אהוי\"ר טבעי' לבד דאז הוא בבחי' מקיף וא\"ז בבחי' הרגש פנימי וא\"ז רק לפי שעה כו', וגם מה שפועל בנה\"ב א\"ז פעולה פנימי' שלא ירצה בעניני העולם ומכ\"ש שימאס בהם, ושהתענוג שלו יהי' באלקו' כו' רק בבחי' הסכם לבד שמסכים אל הביטול דנה\"א, או שמתבטל מן האו\"מ דנה\"א, וכ\"ז רק לפי שעה כו', וכאן הוא שהתגלות המדות הוא ע\"י השגה גמורה באלקו' ועי\"ז דוקא מתעורר באהוי\"ר שזהו בחי' הרגש פנימי הן בההרגש האלקי שבההתבוננות הוא בהרגש פנימי והן האה' עצמה היא בתוכיות לבו בפנימיותו וכל לבבו ממולא מהאהבה שחפץ באמת באלקו' כו', וזה פועל בהנה\"ב ג\"כ שגם הלב בשרי רוצה באלקו' וממולא באה' זו שאין לו אה' אחרת היינו שאין לו רצון ותענוג בדבר אחר כ\"א באלקו' כו', וצ\"ל שהחומרי' שלו הוא בעצם בדקות וגם נפשו האלקי' אינו בבחי' גסה\"ר במדרי' נמוכה רק הוא באיזה מע' ומדרי' עליונה כו', והא בהא תלי' דמפני שהנה\"א הוא באיזה מע'\nומדרי' עליונה אינו נתפס בגוף ונה\"ב חומרי כ\"כ כו', והיינו שבכללות מדריגתו בשרשו ומקורו ה\"ה באיזה מע' ומדרי' עליונה כו' (ויש לפעמים אשר נשמה גבוה דוקא באה בגוף חומרי יותר (מפני שביכולתו לתקן גם גוף גס וחומרי ולכוונה זו נתלבש באופן כזה), ולזה צריכה הנשמה להתעלם בכדי שתהי' נתפס בגשם כזה, אבל כאשר היא בהתגלות הנה לפי אופן מע' ומדרי' הנפש ולפי אופן התגלות שלה לפי ערך כזה הוא התפיסא שלה כו').\n<b>והאופן</b> הב' הוא שהעיקר הוא המוחין, והוא שהמדות אינן בהתגלות כ\"כ וכ\"ש שאינן במורגש רק גילוי המוחין בהשגה גדולה באלקו' בריבוי השתל' המדרי' ובאופני הגילוים בכל מדרי' ומדרי' איך ובאיזה אופן הוא הגילוי כו', ואיך שהכל הוא בטל לגבי עצמות דכולא קמי' כלא כו' והוא בבחי' הנחה טובה במוחו (עס לייגט זעך בא עם א(דער ענין זייער גוט), דע\"ה שזהו רק שמשיג בשכלו וגם הוא בהביטול דעולמות והשתל', ה\"ז מ\"מ בבחי' הנחה טובה במוחו כו' שז\"ע שיש לו השגה גדולה באלקו', דהיינו שגם בענינים שאינם בהשגה כ\"כ ה\"ה משיג אותם בטוב וכמו באופני הגילוים ובאופן הביטול כו', וההשגה היא לא ע\"י לבושי השגה כ\"א בעצם הענין שתופס בזה עצם ענין האלקי שמאיר בגילוי במוחו ולבו כו', וזהו גילוי בחי' אור הבינה היינו גילוי ההשגה שהמוחין דנה\"א מאירים בגילוי כו', וגם מתפעל בזה בלבו בתוקף האהבה רק שאינו בהתגלות ובמורגש כו', וגם בנה\"ב ה\"ז פועל בעצם מהות הנה\"ב, וגם אם הוא חומרי וגשמי יותר ה\"ה מתבטל ע\"י גילוי אור המוחין כשהן בבחי' פנימי'\nובבחי' גילוי ממש כו', ולא כמו באופן הא' בהתגלות המדות שזהו שהחומרי שלו הוא בעצם בדקות כנ\"ל, וגם שזה הוא ע\"י התגברות התגלות דנה\"א, וע\"ה שא\"ז מן המקיף לבד דנה\"א כ\"א שפועל בו בהנה\"ב כו' כנ\"ל, מ\"מ זהו רק שההתגלות דנה\"א פועל בו, דלהיות שהאה' בנה\"ב בעצם מהותו מצ\"ע שהרי לא נהפך בעצם מהותו כו', ה\"ז רק מה שההתגברות דנה\"א פועל בו כמו בדרך הכרח, ע\"ה שהוא רוצה באלקו' כנ\"ל, מ\"מ מפני שאינו בעצם מהותו מצ\"ע ה\"ז כמו דבר הכרחי ע\"י כח עליון שפועל בו כו', וע\"כ הביטול שלו הוא רק כאשר הנה\"א הוא בהתגלות, והיינו שעם הנה\"א ה\"ה ג\"כ בטל והיינו שהו\"א בטל אבל זהו עם הנה\"א דוקא, אבל אם לא יהי' התגלות הנה\"א כ\"כ לא יהי'"],[3601331205,"הביטול שלו כו', ובאופן הב' הוא שמתבטל בעצם ויש בו הביטול תמיד, כי הביטול הוא בו מצ\"ע שמשתנה בטבעו כו'. וזהו\"ע חכמי לב דפי' בלק\"ת מהאריז\"ל שהן מוחין דאו\"א המלובשים בז\"א, ונק' חכמי לב שהן בבחי' לב אחד לאבשבש\"מ, שכ\"ה גם באופן הא' הנ\"ל שכל חפצו ורצונו הוא באלקו' כו', ובפרט באופן הב' שנעשה הביטול בעצם המהות דנה\"ב ה\"ה בבחי' לב א' לה' לבדו כו'. ועז\"נ ואתה תדבר אל כל חכמי לב ועשו בגדי קדש כו' שעושין לבושים לכהן להיות גילוי בחי' הבינה בז\"א שזהו ע\"י הלבוש והמסך שבין בינה לז\"א כו' (וי\"ל דבאצי' הן בחי' כלים ממש כמ\"ש במ\"א, ובברי' אי' עילאה מקננא בכורסי' הן בחי' לבושים כו'), והיינו קיום המצות ע\"י אהוי\"ר שכלי' שעי\"ז ממשיכים גילוי אור הבינה כו', ומדרי' הא' בלבושי' הו\"ע ערש\"מ שממשיכים גילוי רצה\"ע והוא ע\"י העבודה דרעו\"ד ואהבה בתענוגים כו', והמדרי' הב' היא המשכת המוחין ע\"י קיום המצות באהוי\"ר שכלי' כו'. גם י\"ל דמדרי' הא' הוא לבוש התו' שגם התו' היא בחי' לבוש כמ\"ש עוטה אור כשלמה ונק' משל הקדמוני כו', והיינו\nשע\"י התו' נמשך בחי' הראי' באלקו' כו', והמדרי' הב' הן לבושי' דמצות וכמו השגת הנשמות בג\"ע שהוא ע\"י לבושי המצות, וידוע דהלבושי' בגעה\"ע הוא ע\"י כוונת המצות והיינו בחי' אהוי\"ר הנ\"ל, והמדרי' הג' היא בקיום המצות בקבעומ\"ש ובהתגלות האה' המוסתרת כמ\"ש בסש\"ב פט\"ז, ועז\"א ועשו בגדי קדש על כללות ישראל והן בחי' הלבושים דמיכאל כה\"ר הנז' בזהר פ' פקודי דרכ\"ט ע\"א בחי' הלבושים דחסד דברי' (ובמדרי' פרטי' זהו בבחי' יצי' ועשי', וי\"ל דזהו שע\"י העבודה דעשי' מגיעים לבחי' הברי' כו'), והוא קיום המצות בפו\"מ בהתגלות האהמ\"ס שגם עי\"ז ממשיכים אלקות והוא המשכת הארת אצי' בבי\"ע כו', וע\"כ בלבושים אלו לא נאמר לקדשו אלא לכהנו לי, והיינו מפני שאינו נמשך בזה גם מבחי' המוחין, רק הוא בחי' כהן ושירות שנמשך הארת מל' דאצי' בבי\"ע כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ושבתה הארץ, דהנה ארץ הוא בחי' מל', וארז\"ל במד\"ר למה נק' שמה ארץ שרצתה לעשות רצון קונה כו', והיינו שהמל' היא תמיד בבחי' רצוא, וכמ\"ש למען יזמרך כבוד ולא ידום נהו\"ת קארי תדיר לנהו\"ע כו', וזהו מפני שבמל' אינו מאיר גילוי אור ע\"כ היא בבחי' רצוא תמיד כו', אמנם כאשר ממשיכים גילוי אוא\"ס במל' אז היא בבחי' שביתה ונייחא, וזהו ושבתה הארץ שביתת הארץ בחי' מל' ע\"י הגילוי דאוא\"ס ב\"ה כו'. וזהו כי תבאו אל הארץ פי' כאשר תמשיכו גילוי האור בבחי' מל' תהי' ההמשכה שיהי' עי\"ז שביתת הארץ כו', וע\"י מה הוא ההמשכה עז\"א שש שנים תזרע כו' והיינו ע\"י תומ\"צ שנק' זריעה וכמ\"ש אור זרוע לצדיק זרע הקב\"ה תומ\"צ כו', וכמו במצות בבחי' ערש\"מ, מקום הוא בחי' מל' וערש\"מ שממשיכים גילוי אוא\"ס במל' כו', ונמצא מ\"ש ושבתה הארץ אין הכוונה שמיד יהי' שנת השביעית כי צ\"ל תחלה הששה שנים, רק או' שע\"י ההמשכה תהי' השביתה ונייחא לארעא, וההמשכה היא ע\"י הששה שנים כו'. וזהו שאו' בזהר ע\"ז זאת תורת העולה והוא שהמל' היא תמיד\nבבחי' עלי' ורצוא כו', וכאשר ממשיכים האור במל' דא הוא נייחא ודאי כו', וזהו כי תבאו אל הארץ כאשר תמשיכו גילוי אור א\"ס במל' אז ושבתה הארץ כו', וזהו ע\"י שש שנים תזרע שדך דהיינו תומ\"צ וגם זריעה היא עבודת"],[3601331206,"הבירורים תנא סדורא דפת נקיט החורש הזורע כו', דחרישה מרפי ארעא בחי' ביטול כו', ועי\"ז ובשנה השביעית שבת שבתון יהי' לארץ כו'."],[3601331207,"<h3>בס\"ד. ש\"פ במדבר, העת\"ר</h3>\n<b>וידבר</b> ה' אל משה במדבר סיני באהל מועד כו', שאו את ראש כל עדת בנ\"י למשפחותם לבית אבותם כו', לגולגלותם כו' תפקדו אותם לצבאותם אתה ואהרן, וצ\"ל למה מודיע שהפ' נאמרה במד\"ס באה\"מ מה נוגע זה, ולמה דוקא בפ' זו הלא כל פרשי' התו' נא' במד\"ס באה\"מ ולמה בפ' זו דוקא מודיע זאת. גם מ\"ש למשפחותם לבית אבותם לגולגלותם מהו כל האריכות הזאת ומה המה הענינים האלו. גם מ\"ש תפקדו כו' אתה ואהרן צ\"ל למה הי' צ\"ל המספר ע\"י משה ואהרן דוקא כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דבכללות ההשתל' יש ג' פרסאות כללי' וכמו באדם למטה יש ג' הבדלות כללי', הא' חצר הכבד שמפסיק בין אברי הנשימה לאברי המזון, והב' מיצר הגרון שמפסיק בין המוחין למדות והג' קרומא דחפיא על מוחא כו'. כמו\"כ למע' יש ג' פרסאות כללו' דבפרטי' יש ריבוי פרסאות כמשנת\"ל, אך בכללות הן ג' פרסאות הפרסא הראשונה היא שבין למע' מאצי' ובין האצי' והוא מה שהכתר הוא בחי' פרסא בין המאציל לנאצלים, ופרסא זאת היא בבחי' אבני שיש טהור בחי' אספה\"מ שע\"י מאיר גילוי אוא\"ס כו', ובעבודה הוא\nלבושי המצות שע\"י רעו\"ד בחי' ערש\"מ כו', והפרסא השני' היא בין הבינה לז\"א שע\"י נמשך גילוי אור הבינה כו', והוא בחי' אספשא\"מ כו', ובעבודה הוא קיום המצות שע\"י אהוי\"ר שכלי' כו', והפרסא היא בין אצי' לבי\"ע שע\"י נמשך הארת המל' בבי\"ע כו', ובעבודה הוא קיום המצות בבחי' קבעומ\"ש ובהתגלות האהבה המסותרת כו'.\n<b>והנה</b> כל המסכים והפרסאות הנ\"ל הכל הוא במדרי' הקדושה ולא הי' מזה עדיין התהוות היכלות דנוגה והע\"ש דנוגה שמהם נמשך השפעת גשמי' מאד, והן כל הנבראים דעולם התחתון שהן בבחי' יש ממש שזהו מבחי' הנוגה כו' (וגם בתחלת הברי' קודם החטא הי' בבחי' יש ממש רק שקודם החטא הי' מבחי' הטוב דנוגה ולא היו מסתירים כ\"כ על אלקות וכמשנת\"ל (ד\"ה בא אל פרעה), וי\"ל דאז הי' הטוב דנוגה במדרי' גבוה יותר ולכן לא הסתיר כ\"כ כו', וע\"י החטא נעשה תערובות טו\"ר כו', וגם עולמות בי\"ע הרוחני' ההיכלות הן בחי' טוב שבנוגה כו' וכמ\"ש במ\"א), שכ\"ז לא הי' התהוות כזאת ע\"י הפרסאות הנ\"ל, שהרי גם ע\"י הפרסא שבין אצי' לבי\"ע נמשכים הכלים דמל' דאצי' שנעשי' נר\"ן לבי\"ע כו', והכלים הנ\"ל הגם שהאור הוא בהם במיעוט מאד, וכמשנת\"ל המשל מהתחלקות אור השכל בריבוי תי' וצירופי' כו', מ\"מ הרי יש בהם הארה מהאורות ממש ואיך אפשר שיהי' מזה נבראים בבחי' יש ודבר נפרד והשפעת גשמי' כו', אלא שבשביל"],[3601331208,"זה הי' ענין שבה\"כ דתהו שנשברו הכלים ונפלו לנוגה דבי\"ע כו'. וידוע ענין שבה\"כ שזהו עד\"מ פירוד האותי', דהנה תי' שלמה הרי מאיר בה אור שכל וכמו בתי' אדון שיושכל ויושג בה ענין האדנות, אבל כשנפרדו האותי' ונתפזרו להיות כל אות בפ\"ע הרי לא יובן ממנה שום שכל דענין האדנות כו', ואינו דומה להתחלקות השכל בכמה תי' שמ\"מ יש מאור השכל ממש בכל תי' ותי' שמובן ממנה חלק מן השכל, משא\"כ בפירוד האותי' הרי אינו מובן בהאותיות כלל מן השכל, ומ\"מ נשאר בחי' רשימו בעלמא בכל אות כי מחמת שמתחלה היו מצורפי' יחד והי' ההשכלה מאיר בה ע\"כ גם בהפרדם נשאר איזה רשימו בכל אות שכך הוא ענין הרוחני שמניח רושם כו', וכמו ביהכנ\"ס שחרב קדושתו עליו, וכמא' והשימותי את מקדשיכם קדושתן אע\"פ שהן שוממין כי דבר שבקדושה אינו נעקר ממקומו לגמרי כו'. וכך עד\"מ זה יובן ענין שבה\"כ שהכלים בשלמותן היינו שהן כלים לאורות כמו התי' שהיא כלי לאור השכל, אמנם שבה\"כ הוא שנשבר כל כלי לכמה פירורים שאזי נסתלקו מהם האורות עליונים דתהו רק שנשארו בהם רפ\"ח ניצוצין\nשז\"ע רשימו מהאורות שנשארו בשברי הכלים כו', וע\"י שבה\"כ נעשו בבחי' יש, דכאשר היו כלים לאורות היו בבחי' ביטול, וכמו המוציא אוכלין פחות מכשיעור בכלי פטור אף על הכלי מפני שהכלי טפלה לו שהכלי היא טפל למה שבתוכה, וכמו\"כ בכלים דתהו הגם שלא הי' האור בהתלבשות ממש בהכלי מ\"מ הי' בהם אחיזת האור כו', ולפשנת\"ל (ד\"ה נשא הב') הישות דכלים דתהו הי' שרצו רק לקבל לעצמן ולא להשפיע כו', הרי הי' בהם עכ\"פ הקבלה לעצמן כו' וע\"כ הי' הכלי מ\"מ בבחי' ביטול אל האור כו', וע\"י שבירת הכלים נעשה הכלי בבחי' יש ומציאות ביותר כו', ומזה נעשה בחי' ק\"נ דבי\"ע והו\"ע הפרסאות דק\"נ שנק' כעין החשמל וכמ\"ש במאו\"א ערך חשמל, והן אותי' המעלימים ומסתירים לגמרי, וכמשנת\"ל בענין לבושי עור הבהמה שהן בחי' העלם והסתר עד שנעשה עי\"ז השפעת גשמי' וכל הנבראים הגשמי' כו'. והנה עצם ההתהוות הוא בכח הא\"ס ממש וההתהוות בפועל היא ע\"י הארה האלקי' המהווה מאין ליש כו', רק שזהו ע\"י התלבשות באותי' אלו, וכמו איהו וגרמוהי חד לברוא בהם וע\"י מאין ליש שהאור הוא דוקא\nהמהווה רק בכדי שיהי' מציאות דבר הוא ע\"י הכלים כו', כמו\"כ בכדי שיהי' מציאות יש ממש זהו ע\"י העלם והסתר אור האלקי באותי' ופרסאות דק\"נ באופן שלא יהי' נרגש האור האלקי בהנברא ויהי' בבחי' מציאות יש כו', ובזה יש כמה חילוקי מדרי' באופן התעלמות האור בעולמות בי\"ע ע\"י הפרסאות הנ\"ל דלפי אופן כזה הוא מציאות הנברא כו', וכן כל ידיעה והשגה אלקי' שבהנבראים לאחר שנתהוו הכל הוא ע\"י הפרסאות, וכמו בהיכלות עליונים הרי ידוע דכל קבלת אור וחיות המלאכים דהיינו ההשגה האלקי' שלהם שזהו המזון שלהם הכל הוא ע\"י ההיכלות כי מעמד ומצב המלאכי' הוא בההיכלות שבכל עולם, וכל הגילוי' שלהם הכל הוא ע\"י ההיכלות כו', שהן מבחי' הטוב שבנוגה כו' כנ\"ל, וכן הוא בהשגת האדם למטה שאנו יודעים ומשיגים עניני אלקות ע\"י הדברים הגשמי' שזהו ע\"י הפרסאות הנ\"ל, דהשגה זו היא באין ערוך כלל לגבי השגה אלקי' שלא ע\"י הגשם כו'. והנה יש שרש ומקור לשבה\"כ דתהו גם בע\"ס הגנוזות קודם שנתגלה כללות האצי' כו', דהנה הפרד\"ס שער הצחצחות פ\"ו כ' שהע\"ס הגנוזות הן שרשי הכלים כו', וכ' א\"כ כמו שבע\"ס"],[3601331209,"הגלויות העצם מתפשט בהם כן בשרשם העצם מתפשט בהם כו', וכיון שיש שם שרש התהוות הכלים א\"כ הי' גם שם שרש ענין השבירה שהיתה בבחי' הכלים דנקודים דהיינו שהאור נסתלק מן הכלי ונכלל במקורו ושרשו והכלי נשבר כו', וכמ\"ש במב\"ש ש\"ב ח\"ג פ\"ו שנפ' שם ז' מלכין שבי\"ס המקוריות ושרשי' לאצי' כו' (וע\"ה שמדבר שם בענין השבירה בהה' פרצופים דכתר ואו\"א כו' נר' שם היטב הכוונה גם על הגנוזות כו'), ועמ\"ש בת\"ז תי' ס\"ט דקי\"ד ע\"א במח' דאיהו מוחא אוף הכי חב כו', דאיהו נביעו דאילנא דחי' דאיהו אור קדמון אור צח אור מצוחצח כו', מובן מזה דשרש השבירה הוא בהגנוזות כו', וכידוע דשבה\"כ וחטא עה\"ד הו\"ע א' כו'. ומסיבת זה יכול להיות התהוות החכ' דאצי' שאם לא הי' השבירה לא הי' משתלשל אוא\"ס ב\"ה כ\"כ למטה מטה דהיינו עד בחי' עשי', והחכ' נק' ג\"כ עשי' קמי' ית' וכמ\"ש כולם בחכ' עשית שגם החכ' היא בחי' עשי' כו', וכידוע דעולם האצי' נק' עשי' דכללות דזהו מחמת בחי' הכלים דאצי' שהן בבחי' מציאות דבר כו', וסבת ירידה זו הי' ע\"י השבירה שהיתה לפני האצי' כו',\nוהיינו דכמו שהתהוות היש דבי\"ע הוא ע\"י שבה\"כ שנתהוו עי\"ז היכלות דנוגה המבדילים ומפסיקים היינו שמסתירים על האור שיהי' באפשר להיות התהוות היש כו', כמו\"כ בחי' הכלים דאצי' סבת התהוותם בבחי' מציאות דבר הוא ע\"י השבירה בשרשי הספי' כו', וי\"ל דאפשר הכוונה על בחי' חיצוני' הכלים שנת\"ל (ד\"ה זה יתנו) שהן בחי' לבושי' כו', אמנם מובן מזה שיש גם פרסאות המבדילות למע' מאצי' וכמ\"ש בת\"ז שם ואערב תמן חשך דאפסיק בין עלת העלות למו\"ס כו', ועי\"ז הוא התהוות בחי' הכלי' דאצי' כו'. וכ\"ז הוא ע\"י צמצום הראשון שהי' באוא\"ס דהעלם הצמצום נושא שיהי' המשכת האור ע\"י העלמות והסתרים דוקא דשרש כל ההעלמות הן מהצמצום הראשון כו', וגם ענין שבה\"כ הוא ע\"י הצמצום כי להיות שהצמצום הוא בחי' גבו' נמשך מזה הגבו' דתהו בבחי' תוקף הישות והמציאות כו', וגם כי טבע הגבו' להיות מזה פסולת וכמו פסולת הזיעה שבא מן החום הטבעי ובזה הוא שרש הפסולת דשבה\"כ דתהו וגם הוצרך להיות משו\"ז ענין השבירה בכדי להפריד הסיגים והפסולת כו' וכמ\"ש במב\"ש.\n<b>ומכל</b> הנ\"ל יובן דענין הצמצום הוא ב' ענינים הא' להעלים את האוא\"ס הבל\"ג שהי' מאיר בגילוי קודם הצמצום והי' ממלא כל מקום החלל כו' וע\"י הצמצום נתעלם להיות בבחי' העלם כו', והב' בהאור שנמשך בהעולמות להיות בבחי' מדה וגבול ולבוא בבחי' צמצום ומיעוט בהתלבשות בכלים כו', והיינו שכל גילוי אור הוא ע\"י התלבשות דוקא ולא יש בעולמות גילוי אור כמו שהוא בעצם שלא ע\"י התלבשות כו', ולעתיד הקב\"ה מוציא חמה מנרתקה ויהי' גילוי בלי לבושי' וכמ\"ש ולא יכנף עוד מוריך כו', אבל עתה גם ברוכ\"ד הגילוי הוא ע\"י התלבשות כו', וכמ\"ש בפע\"ח שער הק\"ש פט\"ו דעכשיו כל הגילוים הן מחיצוני' עתיק והן ז\"ת דעתיק המתלבשי' באריך ואריך מתלבש באו\"א כו', וגם להיות ההמשכה דרך מסכים ופרסאות שזהו בחי' העלם יותר מבחי' הכלים כו' וכמשנת\"ל, ועוד יהי' פרסאות שע\"י שבה\"כ שג\"ז יש עד רום המעלות כו' כנ\"ל, ויש בזה כמה חלוקי מדרי' בכללות ההשתל' אבל בכללו' ה\"ז בחי' העלם יותר מהפרסאות דס' השתל' כו', וכ\"ז הוא ע\"י הצמצום לצמצם ולהעלים את האור כו'. וזהו\nמה שנא' בפ\"ר דק\"ש הוי' אלקינו הוי' ב' שמות הוי' וש' אלקי' באמצע וידוע דש' אלקי' הוא בחי' צמצום כו', וכן"],[3601331210,"קודם יגמה\"ר נא' ב' שמות הוי' ופסיק טעמא בגווייהו. והענין הוא דב' שמות הוי' הא' הוא ש' הוי' שבאוא\"ס שלפה\"צ וכמא' עד שלא נבה\"ע הי' הוא ושמו לבד ומבו' במ\"א דש' זה הוא ש' הוי', וכידוע שיש ד' אותי' הוי' גם באוא\"ס שלפה\"צ כו' (לבד בחי' שמו העצמי דבעצמותו ממש הוא הוי' בלא אותי' והוא אמיתת היותו כו') וכמ\"ש מזה בד\"ה ועשית ח\"ש רנ\"ו, והב' הוא ש' הוי' שבאור הקו שלאחה\"צ כו', ובד\"כ הוא ש' הוי' שבאוא\"ס הסוכ\"ע והש' הוי' שבהאור דממכ\"ע כו', וש' אלקי' הוא בחי' הצמצום כו', ונת' דהצמצום הוא בהב' מדרי' הנ\"ל, וז\"ע ש' אלקי' הנא' באמצע והיינו ב\"פ הוי' ואלקי' והוא הוי' ואלקי' דבחי' אוא\"ס הבל\"ג והוי' אלקי' בהאור שבא בבחי' מדה וגבול בעולמות כו'. והנה נת\"ל (ד\"ה ויהי הענן והחשך ויאר) דהאוא\"ס הבל\"ג לא נתעלם תוך העלם הצמצום רק שנתעלם במקורו והאור שבמדה וגבול הוא שבא בתוך העלם הצמצום כו', וי\"ל שזהו ע\"ד המבו' במ\"א בענין ד\"ע וד\"ת שהוא דעת המשפיע ודעת המקבל שהן שני הפכים, דדעת המקבל שהיא דעה תחתונה הוא שהמקבל הוא בחי' יש\nוהכח השופע הוא אין וכמו החכ' מאין תמצא הרי החכ' היא היש ודבר מה והכח השופע עליו ומהווה אותו הוא האין, ולגבי הכח השופע הוא להיפך שהחכ' פרטי' הנשפע ממנו הוא רק הארה בעלמא וכל\"ח לגבי העצמו' ונק' החכ' אין באמת והעצמות הוא היש כו', וכמו\"כ בהתהוות כל העולמות המוגבלים מאוא\"ס ב\"ה מאין ליש כו' נק' אור האצי' בש' אין לגבי בי\"ע שהם היש ודבר מה, ובאמת הוא בהיפך שאצי' הוא אמיתי' היש כי הוא העצם וכל דיירי ארעא כל\"ח שהן בחי' אין באמת כו'. ובאמת הרי ב' דעות הנ\"ל ה\"ה באלקו' גופא וכמ\"ש כי אל דעות ה' כו', והיינו דלגבי אוא\"ס שלמע' מבחי' מקור לעולמות הדעה היא שלמע' יש ולמטה אין כו', כי לגבי עצמות אוא\"ס באמת כל העולמות אינם תופסים מקום וכל\"ח שהן בבחי' אין ממש כו', אבל לגבי ההארה האלקי' שהיא בבחי' מקור לעולמות הרי היש תופס מקום ואא\"ל שהוא בבחי' אין לגמרי כו', כ\"א הדעה בזה הוא שהנברא הוא בחי' יש ונתהווה מאין דבר מלא דבר כו'. ועד\"ז הוא בענין הצמצום דלגבי האו\"מ אין הצמצום נוגע כלל וה\"ה לאחה\"צ כמו שהוא לפה\"צ ממש,\nכי לגבי האוא\"ס הבל\"ג אין הצמצום תופס מקום וע\"כ הוא נמצא לאחה\"צ ממש כמו שהוא לפה\"צ כו', והגם שע\"י הצמצום נתעלם האור וההתעלמות היא שהוא כאלו אינו כו' וכמשנת\"ל (ד\"ה ויקרא), מ\"מ ה\"ה נמצא כמו שהוא ממש גם לאחה\"צ ובידיעתו ית' ה\"ה בגילוי ממש לאחה\"צ כמו קוה\"צ כו'. אמנם לגבי האו\"פ הרי האור מתצמצם ומתעלם ממדרי' למדרי' כו', והגם דאני ה' לא שניתי גם בהאו\"פ משום דכ\"ז הוא בחי' העלם לבד, וכמ\"ש בסש\"ב פנ\"א שאור וחיות כדור הארץ החומרי הוא ממל' דמל' דעשי' שבתוכה מל' דיצי' כו' שבתוכן ע\"ס דאצי' המיוחדות במאצילן ב\"ה כו', והעלם וגילוי אין זה שינוי כו' כמ\"ש במ\"א, מ\"מ ה\"ה בהעלם ע\"י הצמצום כו', משא\"כ בהאו\"מ הרי ההעלם רק בידיעתנו לבד היינו לגבי העולמות והוא שהאוא\"ס מעלים א\"ע כבי', אבל לגבי האוא\"ס היינו בידיעתו ית' הוא בבחי' גילוי ממש כו'. ואחר כל הנ\"ל בריבוי הצמצומים והעלמות והסתרים בכללות ההשתל' הנה בכדי שיהי' גילוי אוא\"ס בעולם זהו דוקא ע\"י היפך הצמצום המסתיר שלא יסתיר ויעלים כלל, והו\"ע אתהפכא חשול\"נ דחשך הוא בחי' הצמצום ופי' חשך אינו"],[3601331211,"דוקא שהוא דבר המחשיך כמו חשך וערפל כ\"א שהוא בחי' התעלמות והסתר, וכמו כבוד אלקי' הסתר דבר כו' שא\"ז שיש דבר המסתיר כ\"א שהדבר מתעלם ומסתתר מצ\"ע כו', והיינו באוא\"ס הבל\"ג שאינו מתעלם בחשך והעלם הצמצום כ\"א ענין הצמצום הוא שהאוא\"ס מתעלם בעצמו שאינו בבחי' גילוי כו', וגם חשך הצמצום הוא שמעלים ומסתיר על האור כו' והוא בהאו\"פ שבא בהתלבשות ובהעלם במסכים ופרסאות כו' כנ\"ל דבכ\"ז צ\"ל אתהפכא חשול\"נ כו', וכמ\"ש בזהר בהקדמה ד\"ד ע\"א מאן מנכון די חשוכא מהפכין לנהורא וטעמין מרירו למתקא עד לא ייתון הכא.\n<b>וביאור</b> ענין מהפך חשול\"נ ומרירו למתקא, הנה כתי' ויקרא אלקי' לאור יום ולחשך קרא לילה, וצ\"ל הד' לשונות אור ויום חשך ולילה, דלכאו' אור ויום הם דבר א' וכן חשך ולילה, אמנם מל' הפסוק משמע דאינו כן שהרי או' שקרא אלקי' לאור יום משמע שהם שני דברים וקרא והמשיך את האור שיאיר ביום. אך הענין הוא דאור וחשך הם חו\"ג אור הוא חסד שהוא בחי' גילוי וחשך הוא בחי' גבו' שהוא העדר הגילוי כו' (והו\"ע הוי' ואלקי' שהוא בחי' הגילוי ובחי' הצמצום להעלים ולהסתיר וכמו שמש ומגן הוי' אלקי' כו'), והקב\"ה קרא לבחי' אור דחסד שיאיר ביום וכמ\"ש חסד אל כל היום כו', ולילה הוא זמן החשך כו', ובד\"כ עוה\"ז ועוה\"ב הוא יום ולילה דעוה\"ז נמשל ללילה שהוא חשך ולא אור, וגילוי דלעתיד נמשל ליום וכדאי' במדרש אמתין עד שיאיר היום דהיינו הגאולה דלעתיד כו', וזשה\"כ להגיד בבקר חסדך ואמונתך בלילות פי' כי בקר שהוא בחי' יום נק' בש' חסד ע\"ש בחי' חסד אל שמאיר ביום כו', אבל בלילה הוא בחי' אמונה בלבד כו', והיינו כי יש ברכה והודאה דענין ההודאה הוא\nשמודה שהדבר הוא כן הגם כי אינו משיג זאת בשכלו שז\"ע החשך והעלם הדבר ממנו כו' וכמו\"כ ענין האמונה הוא בדבר שאינו מושג כו', וזהו ואמונתך בלילות דעוה\"ז שנמשל ללילה שבה חשך כפול ומכופל ואינו מאיר גילוי אלקותו ית' בגילוי לעין כל שהרי בה' נברא העוה\"ז וכמ\"ש בהבראם בה' בראם כו', והיינו דהתהוות העולמות הוא מבחי' המל' שהיא רק הארה לבד, ובנין המל' הוא מהגבו' דבכדי שיהי' הארה זו שיהי' בבחי' מקור לעולמות צ\"ל ריבוי צמצומים כו', וכמשנת\"ל בענין וגבורתך ידברו כו', וגם הארה זאת היא מתעלמת ומסתתרת כו' וכמשנת\"ל באורך, וע\"כ למטה הוא בחי' העלם והסתר שאינו מושג האור האלקי ולא נשאר רק בחי' אמונה לבד כו', וידוע דבאמונה יכול להיות שלא יהי' בבחי' הרגש פנימי כלל וכמו גנבא אפום מחתרתא כו', דבהשגה הרי מאיר האור בגילוי ובבחי' הרגש פנימי כו', משא\"כ באמונה יכול להיות בבחי' העלם לגמרי והיינו שהגם שהוא מודה ומ\"מ יהי' ח\"ו היפך אלקו' כו', וזהו ע\"י הפרסאות דק\"נ המעלימים ומסתירים לגמרי כו' כנ\"ל. אך הנה כתי' נר ה' נשמת אדם\nשנש\"י נמשלו לנר דכמו שהנר מאיר את חשכת החשך הגשמי כן נש\"י שנמשלו לנר הם המאירים את זמן החשך שנמשל ללילה, והיינו שע\"י עבודתם הם ממשיכים בחי' ש' הוי' שיאיר בש' אלקי' כו', דברה\"ע הי' ע\"י ש' אלקי' המסתיר על האור דש' הוי' בכדי שיוכל להיות ההתהוות כו', ומזה הוא בחי' החשך וההסתר למטה כו', אבל נש\"י ממשיכים גילוי ש' הוי' והו\"ע הברכה ברוך אתה הוי' להיות גילוי ש' הוי' בעולם כו'. והענין הוא דהנה ידוע דהוי' ואלקי' הן בחי' אורות וכלים דש' הוי' הוא שרש האורות וש' אלקי' הוא שרש הכלים, וכנ\"ל דש' אלקי' בשרשו הוא"],[3601331212,"הצמצום הראשון שהי' באוא\"ס שמזה נתהוו הכלים, דבשרשן הוא בחי' נקודת הרשימו מקור הכלים כו' וכמשנת\"ל (ד\"ה ויהי ביום השמיני), וש' הוי' הוא אור הקו הנמשך מאוא\"ס אחה\"צ ומתלבש בנקודת הרשימו ובהכלים דא\"ק ועקודים וכלים דאצי' שבזה מתעלם האור ומתמעט ממדרי' למדרי' כו', ועיקר פעולת הכלים הוא בעולמות בי\"ע שנתמעט עי\"ז האור ביותר עד שנעשה מקור ליש כו' וכמשנ\"ת כ\"ז בד\"ה הנ\"ל, וגם עוד זאת שנמשך האור ע\"י כמה מסכים ופרסאות המעלימים על האור כו' כמשנת\"ל. וע\"ז עבודת האדם להמשיך גילוי ש' הוי' שיאיר בגילוי ממש תוך הכלים והעולמות עד שגם למטה יהי' גילוי אור כו', והיינו ע\"י עבודתו לברר ולזכך את החשך שלו ולהאיר אור נפשו האלקי' כו'. דהנה הנה\"א נתלבש בנה\"ב והיינו שהכחות האלקי' נתלבשו בכחות טבעי' וכל השגה אלקי' היא בשכל הטבעי וכה\"ג בכל הכחות כו', שזהו שהכחות דנה\"א באו בהגשמה בהתלבשות זאת שאין ההשגה דנה\"א באלקו' למטה כמו שהיא למע' שהנשמה עצמה משגת אלקו' שהיא השגה אלקי' ממש, ולמטה ה\"ה בבחי' השגה טבעי' שהתפיסא דאלקו' היא\nבאופן אחר לגמרי, וזהו עד\"מ כמו תפיסת האור בהכלי דהיינו מה שהכלי תופסת האור שהאור בא בהגשמה כו', ובפרט בהשגה טבעי' דנה\"ט שהוא מק\"נ, וביותר כשנתפס בחומרי' שמעלים ומסתיר על האור דנה\"א שהן כדוגמת המסכים המבדילים כו'. וזאת היא עבודת האדם להסיר ההעלמות וההסתרים שבנפש שלא להמשך אחרי הטבעי' והחומרי' ולהכניע ולכוף א\"ע בכל פרט, שבזה מסיר כללו' ההעלמו' וההסתרי' מהנפש והוא ראשית העבודה לצאת מעניני החומרי' שלו והו\"ע שכחי עמך כו' שבזה מסיר באמת חומרי' הגסות דנה\"ב כו', וכמו\"כ מסיר ההעלמות וההסתרים שבעולם כי גם את העולם נתן בלבו כו', וגם לברר ולזכך הכחות טבעי' שלו והוא ע\"י התגלות הנה\"א בהשגה והתבוננות אלקי שזהו פועל הביטול בכחות הטבעי' שלא יהיו בחומריות ואדרבה יהיו ג\"כ לאלקות כו', וגם שיזדככו מחומריותם בעצם ויהיו כלים לאור הנשמה כו', וכמו חומר המוח שהוא כלי לאור השכל הרי ע\"י ההתעסקות בענינים שכלי' מזדכך חומר המוח ונעשה כלי יותר לאור השכל כו', וכמו\"כ הוא בעבודה שע\"י היגיעה וההתעסקות בהכחות הטבעי' שלו\nבעניני אלקות ה\"ה מזדככים ונעשים כלים לאור אלקי כו', ובשקידתם בעבודה מזדככים ביותר ונעשי' יותר כלים לאור הנשמה ואור האלקי הכל במדרי' עליונות יותר כו' (ובפנימי' הכוונה הוא שנעשי' כחות אלקית וכמשנת\"ל ד\"ה פדה בשלום נפשי). והנה ידוע דע\"י בירור וזיכוך הנה\"ב נעשה עלי' בנה\"א והעלי' הוא שמתעלי' מבחי' גרמוהי לבחי' חיוהי דשרש הנשמות הוא מבחי' גרמוהי בחי' פנימי' הכלים כו', וע\"י העבודה למטה מתעלים בבחי' איהו וחיוהי חד שהו\"ע לאשתאבא בגופא דמלכא כו' וכמ\"ש בתו\"א ד\"ה זכור ושמור בדבור א', ועי\"ז מעורר כן למע' שיזדככו הכלים דע\"ס ויתעלו ממדרי' איהו וגרמוהי חד למדרי' איהו וחיוהי חד, והיינו שהכלים יהיו כמו האור ממש, וכמו כלי החכ' שנק' ג\"כ חיוהי, וכמו בת\"ת שהכלי היא ג\"כ ש' הוי', כן יהי' עליית הכלים שיהיו כמו האור כו' (וי\"ל שז\"ע שילוב אד' בהוי' שנת\"ל ד\"ה מצה זו), ועי\"ז ה\"ה בחי' כלים לאור עליון יותר והיינו להאור שלמע' מהכלים כו'. וז\"ע ושמרו דרך הוי' כי הכלים הן משארי שמות שאינן נמחקים ש' אל בחסד וש' אלקי' בגבו' כו', אך האורות הם מש' הוי' כו', וההפרש הוא"],[3601331213,"דש' הוי' הוא בחי' גילוי ושארי השמות הן בחי' העלם ומעלימים על האור דש' הוי' כו', ושמרו דרך הוי' הוא להמשיך יחוד האור בכלי והיינו שהאור יהי' בגילוי בהכלי והכלי לא יעלים על האור כו', וזהו ע\"י שהכלי מתהפך ונעשה ג\"כ כמו האור עי\"ז מאיר הש' הוי' בגילוי ממש כו', והגילוי הוא מ\"מ ע\"י הכלי דהיינו בבחי' או\"פ ומאיר בזה האור כמו שהוא בלי שום העלם רק כמו שהוא בעצם, והכלי אינה מעלים על האור ומאיר בגילוי כמו שהוא כו', והוא גילוי האו\"פ רק שמאיר בגילוי כמו שהוא בעצם כו', וז\"ע שהנשמות הן נר הוי' שממשיכים את הש' הוי' שיהי' בגילוי ממש כו'.\n<b>וזהו</b> מאן דמהפך חשול\"נ שמהפך לאור חשכת הגוף והנה\"ב וחשכת העולם ועי\"ז ממשיך ש' הוי' שיאיר בגילוי בעולם כו', שהרי ע\"י הצמצום הוא שהגילוי שבעולמות הוא רק כמו שהאור בא בהתלבשות כו' כנ\"ל, וע\"י שמברר ומזכך החשכות שלו שהכחות הטבעי' נעשים כלים לאור אלקי כו' כנ\"ל, נעשי' הכלים למע' שיהי' כמו האור ומאיר בהם אור העצמי והכלי אינו מעלים שיהי' גילוי האור כמו שהוא בעצם כו'. וענין מרירו למתקא הוא כי יש שקדים המרים ושקדים מתוקים, ונודע כי אין לך עשב מלמטה שאין לו מזל מלמע' כו', ונמצא כי יש בשורשן ג\"כ ב' מיני השפעה כי שוקד הוא ל' השפעה וכמו כי שוקד אני על דברי כו', והיינו שבהשתל' יש ב' מיני המשכות והן בחי' חו\"ג חסד הוא בחי' מתיקות וגבו' בחי' מרירות כו'. והענין הוא דהנה כתי' ביום ההוא יהי' הוי' א' ושמו א', וארז\"ל אטו האידנא לאו א' הוא ותי' על ה' אחד לא כעוה\"ז העוה\"ב בעוה\"ז על הטוב מברך הטוב והמטיב ועל הרעה מברך דיין האמת אבל עוה\"ב כולו הטוב והמטיב, ועל ושמו א' תי' עכשיו לא כמו שאני נכתב אני נקרא\nנכתב בש' הוי' ונק' בש' אד' ולעתיד נכתב בש' הוי' ונק' בש' הוי', והיינו כי ב' שמות הוי' הא' הוא שלמע' מהשתל' והב' הוא ש' הוי' דהשתל' והן בחי' סוכ\"ע וממכ\"ע, ובשרשן ש' הוי' הא' הוא האוא\"ס שלפה\"צ וש' הוי' הב' הוא האור שבא ע\"י הצמצום לפ\"ע העולמות כו' וכנ\"ל, ועכשיו הוא ההמשכה מש' הוי' דהשתל', ובזה יש ב' המשכות דבחי' חו\"ג וע\"כ על הטובה מברך הטוב והמטיב על החסד והטוב שמטיב כו', ועל ההיפך מברך כו' על השפעת בחי' הגבו' כו', וזהו ג\"כ שעכשיו נכתב בהוי' ונק' באד' דש' הוי' דס' השתל' המשכתו הוא ע\"י ש' אד' שהוא בחי' הצמצום וההעלם דאנת אשתמודעא אדון על כולא כו', והוא בחי' העלם הכלים והעלם המסכים להיות מציאות היש כו', וגם הוי' ואד' הן בחי' רחמים ודין כו' דהוי' הוא בחי' רחמים (והן בחי' הרחמים דס' השתל' כו') ואד' הוא ל' דין רק דאל\"ף שבאד' הוא ממתיק את הדין דאד' כו' כי שרשו מבחי' אלף דאהי' כו' וכמ\"ש במ\"א. אבל לעתיד כולו הטוב והמטיב כי לעתיד יאיר גילוי ש' הוי' דלעילא שלמע' מהשתל' כי הצמצום לא יעלים ויסתיר\nלעתיד ויהי' בגילוי בחי' האוא\"ס שלפה\"צ כו', וכן בכללות ההשתל' יהי' גילוי בחי' עצמות אוא\"ס ב\"ה דלית שמאלא בהאי עתיקא שאין שם בחי' גבו' כלל והגבו' הן ג\"כ חסדים והן בחי' תגבורת החסדים כו', ולכן לעתיד נכתב בש' הוי' ונק' ש' הוי' והיינו שהגילוי דש' הוי' דלעילא יהי' ע\"י ש' הוי' דלתתא שלא יהי' שום העלם והסתר ויהי' הש' הוי' דלעילא בבחי' גילוי ממש כו', וגם יהי' בבחי' או\"פ שז\"ע שיאיר ע\"י ש' הוי' דהשתל' שהוא בחי' או\"פ ויהי' הגילוי בבחי' פנימי' כו', וזהו שיהי' כולו הטוב ומטיב מפני שיהי' גילוי ש' הוי' דלעילא דלית שמאלא בהאי עתיקא"],[3601331214,"כו'. והמשכה זו הוא ע\"י דטעמין מרירא למתקא שגם השפעת הגבו' שבס' השתל' טועם למתקא שאו' גם זו לטובה, וא\"כ אין כאן ב' השפעות מאחר שטועם גם מרירו למתקא עי\"ז נמשך גילוי עצמות אוא\"ס שלמע' מהשתל' דכולא טוב כו'.\n<b>וז\"ש</b> כי נר מצוה ותו\"א ודרך חיים תוכחת מוסר, דמצות הן בחי' נר וכלי דרמ\"ח פקודין רמ\"ח אברי' דמלכא שהן בחי' אברי' וכלי' דז\"א כו', ותו' הוא בחי' אור המאיר ומתלבש בהכלים כו' והן בחי' ש' אד' וש' הוי' כו', ודרך חיים הוא בחי' הדרך ומבוא לחיים העליונים בחי' חיים עצמי' שלמע' מהשתל' כו', והוא למע' מהתו' הנק' עץ החיים דהיינו בחי' האור המאיר בז\"א כו', והוא כענין מ\"ש היש בה עץ אם אין ואי' בזהר שלח דקנ\"ח ע\"ב דקאי על מ\"ש היש ה' בקרבנו אם אין דפי' באד\"ר דקכ\"ט ע\"א דשאלתם הי' אם ההשפעה שלהם הוא מבחי' ש' הוי' דז\"א או מבחי' אין שהוא בחי' ש' הוי' דלעילא בחי' הכתר כו', וזהו ג\"כ אם יש בה עץ בחי' ש' הוי' דז\"א הנק' אילנא דחיי אם אין הוא בחי' ש' הוי' דלעילא הנק' מקור החיים כו', וכמ\"ש כי עמך מקו\"ח בחי' עד שלא נבה\"ע הי' הוא ושמו בלבד כו', וזהו בחי' דרך החיים שלמע' מבחי' עה\"ח כו'. ועז\"א ודרך חיים תוכחת מוסר שע\"י תוכחת מוסר שמקבל באה' מפני שיודע שזהו לטובתו שעי\"ז זיכוך ונקיון נפשו עי\"ז נמשך בחי' דרך חיים\nדלית שמאלא בהאי עתיקא שבאמת נעשה כולו טוב והגבו' הן בחי' תגבורת החסדים כו'. והענין בעבודה דהנה כתי' בית יעקב לכו ונלכה באור הוי' פי' בית יעקב הם הנשמות השפלות והנמוכות שבישראל, דיעקב הוא ל' עקב שהן מדרי' התחתונות שבנשמות שהן בבחי' גסה\"ר שהרוחני' שבהם הוא בבחי' גסות כו', וגם כענין שנא' עון עקבי יסובני והוא כענין אפי' נחש כרוך על עקבו, דהיינו לפי שהנשמה היא מבחי' עקביים שהיא הבחי' היותר תחתונה במדרי' ע\"כ הנחש הוא היצה\"ר כרוך עליו ביותר דהיינו שמקושר מאד בתאוות נפשו הבהמית וגופו ומדותיו הטבעי' ואינו יכול לצאת מהם, עד שאינו מועיל לו כלל ההתבוננות ליפרד מתאוות גופו ולהיות לבו מתלהב לדבקה בו ית', וגם שמבין ברוח בינתו איך דכולא קמי' כלא כו' ואיך שהוא ית' יחיד ומיוחד, ואיך כי לו יאתה לדבקה בו ולהבטל אליו מכל וכל כו', מ\"מ אין אור האה' מאיר כלל בלבו מחמת רוב התקשרותו ביותר בהחומר גופני כו' (וגם מה שמבין ברוח בינתו כו' הוא בבחי' חיצוני' לגמרי שאינו נקלט במוחו ואינו נכנס ללבו רק ידיעה חיצוני'\nושטחי' לבד כו'), וזהו מפני שהוא מבחי' עקביים אשר ע\"כ הנחש כרוך על עקבו כו', והו\"ע סרכות הריאה שנסרך ונדבק מאד בחומרי' הגוף כו' וכמ\"ש בלק\"ת ד\"ה מי אל כמוך. ומ\"מ או' בית יעקב לכו ונלכה כו' דגם בית יעקב שהם נשמות הנמוכות בבחי' הריחוק בתכלית, הנה אדרבה מחמת הריחוק הגדול יש להם תקומה נפלאה להיות כי מפני גודל עוצם ריחוקם כשמשפיל א\"ע והוא במרירות גדולה על הפחיתות שלו ומעורר ר\"ר על נפשו ה\"ה מעורר בחי' רחמים העליוני' בחי' רחמים פשוטים שלמע' מהשתל' כו', וכידוע בענין הרחמים שיש בזה ב' מדרי' הא' הרחמים שמצד הדעת וההרגש והן למע' בחי' הרחמים דס' השתל' כו', והב' בחי' רחמים פשוטים שלמע' מהשתל' שאינם מצד ההרגש רק מפני שטבע המרומם להיות נמשך אל השפל כו', וע\"כ עיקר הרחמים הוא דוקא על השפל במדרי', וע\"כ דוקא על בחי' בית יעקב נופל הרחמנות יותר להיות שזהו בחי'"],[3601331215,"ומדרי' נמוכה ביותר וירדה ונתפסה בחומרי' הגוף ונה\"ב ביותר שזהו ירידה אחר ירידה כי לא די שירדה בירידת המדרי' אלא אף גם זאת שנתלבשה בבחי' גלות כו', שע\"ז נופל הרחמנות יותר מעל נשמה שלא ירדה כ\"כ כו', וע\"כ כאשר מעורר ר\"ר על נפשו ממשיך מבחי' יגמה\"ר שהן בחי' רחמים פשוטים דעצמות אוא\"ס ב\"ה, ועי\"ז בית יעקב לכו ונלכה באור הוי', והיינו בבחי' האור דש' הוי' שבעצמות כו', וי\"ל באור הוי' היינו בהאור דש' הוי' דהשתל', וע\"ד בי נשבעתי נאום הוי' במה שמלובש בש' הוי' כו', והיינו בחי' עצמות אוא\"ס שלמע' מהשתל' כו'. ובכדי להיות התעוררות רחמים היינו שיעורר ר\"ר על נפשו צ\"ל תוכחת מוסר והו\"ע הביטוש שיבטש א\"ע ויהי' רע בעיניו השפלות והפחיתות שלו ובפרט עוצם ריחוקו יהי' רע בעיניו מאד ויהי' נבזה ושפל בעיני עצמו ועי\"ז מעורר ר\"ר על נפשו כו', ובזהר תרומה דקס\"ו ע\"א פי' תוכחת מוסר הוא הבירור והזיכוך כו', והו\"ע קדש עצמך במותר לך שמחמיר ע\"ע ביותר גם בדברים המותרים שעי\"ז מזדכך החומרי' הגסות ג\"כ כו', וגם עי\"ז יהי' ההתעוררות רחמים\nכו', וע\"י כ\"ז הוא גילוי בחי' ש' הוי' דלעילא כו'. וז\"ע דטעמין מרירו למתקא שע\"י שטועמין את המר למתוק דבעבודה הו\"ע הביטוש שמבטש ומשפיל א\"ע ומעורר ר\"ר על נפשו וגם מה שמסגף ופורש א\"ע גם מדברים המותרים בכדי לתקן נפשו כו', עי\"ז ממשיך בחי' עצמות אוא\"ס ב\"ה שיאיר בגילוי בעולם שז\"ע הוי' אחד ושמו אחד כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש במדבר סיני באהל מועד, דהנה מדבר הוא ל' דבור והיינו בחי' דבר ה' המקור לעולמות בדבר ה' שמים נעשו והוא בחי' מל' כו', דהנה מל' נק' לפעמים בש' ארץ ולפעמים בשם מדבר, ארץ ג\"כ דומם רק שראוי לזריעה כי יש בה לחלוחית שיוכל להיות בה צמיחה, ומדבר הוא ארץ חרבה ויבשה שאינו ראוי לזריעה כו'. והדוגמא מזה למע' דארץ הוא כשמאיר עדיין בגילוי ההארה האלקי' שאינה מוסתרת כ\"כ כו', ומדבר הוא שמוסתר האור האלקי לגמרי ואינו נראה ונגלה כלל כו', והוא באלקו' מדרי' תחתונה שבא בבחי' העלם והסתר ביותר כו', וכמו בנשמות דנשמה שהיא נמוכה ביותר ה\"ה נתפסת בגשם ביותר כו', כמו\"כ הוא בההארה האלקי' שהיא מדרי' תחתונה ה\"ה מתעלם ביותר כו'. אך הנה כתי' מי זאת עולה מן המדבר ואי' במד\"ר כל עילויו מן המדבד כי יש מדבר בקדושה וכמ\"ש מזמור לדוד בהיותו במדבר יהודה צמאה לך נפשי כו', שבמדבר נעשה הצמאון ביותר, וכמ\"ש רעבים גם צמאים נפשם בהם תתעטף דלכאו' מה\"ע רעבים גם צמאים דאם הוא רעב אינו צמא, אך הן מדרי' באה' דיש אה'\nשהיא עד\"מ רעב ללחם ויש אה' גדולה יותר שהוא עד\"מ הצמא למים כו', וז\"ע מדבר שהוא תוקף הצמאון מפני העדר הגילוי כו', וכמו שאו' ע\"ז כן בקדש חזיתיך הלואי בקדש חזיתיך בתוקף האה' כזו כו', וזהו במד\"ס הוא תוקף האה' והרצוא שנעשה ע\"י הריחוק כו', וסיני הוא שממנה ירדה שנאה כו', והו\"ע שנאו רע שמצד הריחוק אדרבה הוא מואס ברע ונמשך בבחי' תוקף הרצוא לאלקות כו' (ובמדרי' עליונות בחי' במד\"ס הו\"ע אה\"ר דרעו\"ד כו'), ועי\"ז הוא ההמשכה בחי' גילוי אוא\"ס, שז\"ע באהל מועד דמועד הוא מל' ונועדתי לך אותי' ונודעתי והו\"ע ושמי הוי' לא נודעתי להם לא ניכרתי להם במדות אמיתי' שלי"],[3601331216,"בחי' ד\"ע הנ\"ל, והיינו הגילוי דבחי' עצמו' אוא\"ס ב\"ה, והוא ההמשכה ע\"י תומ\"צ שע\"י הקדמת הרצוא דבמד\"ס נמשך בחי' עצמו' אוא\"ס בחי' דרך חיים הנ\"ל ע\"י תומ\"צ כו'. וז\"ע שאו את ראש בנ\"י דענין נשיאת ראש היינו הגבהת הראש והמוחין לבא לבחי' עצמות אוא\"ס שז\"ע לגולגלותם בחי' כתר כו', וגם שיהי' המשכת העצמות כו', וזהו תפקדו כו' אתה ואהרן דמשה ואהרן הן שושבד\"מ ושושבדמ\"ט, אהרן הוא שושבדמ\"ט שהמשיך בחי' אה\"ר בנש\"י שז\"ע העלאת הנרות כו', ומשה שושבד\"מ דהמשכת האור הוא ע\"י משה כו', וע\"כ בחי' נשיאת ראש שהוא רצו\"ש העלאה והמשכה זהו ע\"י משה ואהרן כו'. אמנם אופן העלי' ע\"ז אומר למשפחותם לבית אבותם, דהנה נת\"ל דהעלי' הוא ע\"י התעוררות רחמים, והנה אין קורין אבות אלא שלשה אברהם בחי' אה' ויצחק בחי' יראה ויעקב מדתו מדה\"ר ובחי' הרחמים דיעקב הוא על מדרי' עליונות שגם עליהם שייך רחמים דלגבי עצמות אוא\"ס גם בחי' האצי' הוא בחי' ירידה וכנודע דענין אצי' הוא אוריד ואמשיך בחי' שלך למטה ממדריגתך כו', וע\"כ גם על נשמות דאצי' שייך רחמים כו',\nומיעקב יצאו י\"ב שבטים שהן בחי' י\"ב בקר דברי' והיינו הרחמנות על נשמות דבי\"ע דמ\"ת בוכין כו', שהרי כל הנשמות שרשן הוא בבחי' חכ' דאצי' וכל נשמתא הוה קיימא בדיוקנאה קמי' מלכא קדישא בחי' ז\"א דאצי' כו', וכאו\"א אומר נשמה שנתת בי טהורה היא כו', ומה שירדה לבי\"ע ה\"ז ירידה גדולה ובפרט מה שירדה להיות נשמה נמוכה ה\"ז ירידה גדולה מאד כו', ומהי\"ב שבטים יצאו ע' נפש יוצאי ירך יעקב והוא הרחמנות על הירידה בגוף ונה\"ב שנתפס מאד בישות כו', וס' העלי' מלמטלמ\"ע תחלה למשפחותם הן ע' נפש דיעקב דתחלה צריך לעורר ר\"ר על חומרי' וגסות הגוף ונה\"ב שמעלים ומסתיר מאד כו', ואח\"כ לבית אבותם הן הי\"ב שבטים שהוא ההתעוררות רחמים על הנשמה שהיא נמוכה במדרי' כו' עד שבא לבחי' רחמים דיעקב כו'. וזהו וידבר ה' אל משה במד\"ס באה\"מ מפרט כאן שהי' במד\"ס ובאה\"מ שזהו בחי' רצו\"ש שז\"ע הנשיאות ראש, והוא ע\"י משה ואהרן דוקא בחי' שוד\"מ ושודמ\"ט, ואופן העלי' הוא כסדר המדרי' מלמטלמ\"ע למשפחותם לבית אבותם כו', ועי\"ז באים לגולגלותם בחי' הכתר כו'."],[3601331217,"<h3>בס\"ד. ליל א' דחה\"ש, העת\"ר</h3>\n<b>וידבר</b> אלקים את כה\"ד האלה לאמר אנכי ה' אלקיך, וצ\"ל מפני מה נא' במ\"ת ש' אלקי', הלא ידוע דש' אלקים הוא בחי' צמצום והעלם ובמ\"ת הי' גילוי אוא\"ס וכמ\"ש וירד ה' על ה\"ס שהי' גילוי אוא\"ס ממש שהי' נראה ונגלה לכל ישראל, ומפני מה או' כאן ש' אלקי' דוקא. והנה בפ' ראשון דק\"ש אומרים הוי' אלקינו הוי' אחד, וצ\"ל מהו\"ע ב\"פ הוי' והול\"ל ה' אלקינו אחד מהו\"ע ב\"פ הוי', ובאמצע נא' ש' אלקי' וכן קודם יגמה\"ר נא' ב' שמות הוי' ופסיק טעמא בגווייהו."],[3601331218,"<b>אך</b> הענין דהנה ידוע דב' שמות הוי' הן ש' הוי' דלעילא וש' הוי' דלתתא, ש' הוי' דלעילא הוא ש' הוי' שלמע' מהשתל' והוא האוא\"ס הסוכ\"ע, וש' הוי' דלתתא הוא הש' הוי' דס' השתל' בחי' ממכ\"ע כו', ובשרשן ש' הוי' דלעילא הוא הש' הוי' שבאוא\"ס שלפה\"צ וכמא' עד שלא נבה\"ע הי' הוא ושמו בלבד והוא שמו הגדול שהוא ש' הוי', כי מוסכם כמעט מכל המקובלים דגם בהאור שלפה\"צ שייך ש' הוי' (כ\"ה דעת הג\"א ועה\"ק והשל\"ה ופלה\"ר לבד הפרד\"ס שלו דעת אחרת בזה ודעת האריז\"ל בע\"ח נר' שהיא כדעת הג\"א), והו\"ע שמו הגדול כו', והגם שודאי גם השארי שמות יש להם שרש ומקור באוא\"ס שלפה\"צ (וכ\"מ בע\"ח בהתחלתו), הנה זהו בבחי' כח הגבול שבא\"ס שהרי שארי שמות הן בהכלים והיינו בהחיות שבהכלים עצמן לבד האור המתלבש בתוכן וכמ\"ש בלק\"ת בהבי' דאת שבתותי בש' הבעש\"ט ז\"ל, ושרשן הוא מן הרשימו כו', אבל ש' הוי' הוא בהגילוי דאוא\"ס שזהו בחי' האוא\"ס הבל\"ג כו', וש' הוי' דלתתא הוא בגילוי הקו. וכידוע דכללות הקו יש בו ש' הוי' אות י' הוא בראשית גילוי הקו קודם שמתלבש בפרצוף דא\"ק\nכו', וכמ\"ש בע\"ח שהקו נמשך ומתעגל וחוזר ונמשך כו', הרי נמשך תחלה וראשית המשכתו הוא האות יו\"ד והג' אותי' הו\"ה הוא כמו שמתלבש בג' עולמות בי\"ע הכללי' כו' וכמ\"ש במ\"א. והש' אלקי' שבאמצע הוא הצמצום הראשון שהי' באוא\"ס, דפעולת הצמצום הוא ב' ענינים, הא' הוא להעלים האוא\"ס הבל\"ג, דקודם הי' האוא\"ס מאיר בגילוי וכאשר מאיר גילוי אוא\"ס אז מה שנתפס בפשיטות הוא אלקות ומציאת היש הוא בבחי' התחדשות דבר שיש ג\"כ מציאת יש, וכאשר נתעלם האוא\"ס מה שנתפס בפשיטות בעולם הוא המציאות והישות והאלקות בא בבחי' התחדשות שיהי' גילוי אלקות כו', וההתעלמות דאור זה הוא שנתעלם ונכלל במקורו לא שנתעלם תוך העלם הצמצום כו', כי הצמצום אין ביכולתו להעלים ולהגביל את האור הבל\"ג, ומה שביכולתו להעלים ולהגביל הוא רק את האור שהאוא\"ס שיער בעצמו להאיר בבחי' מדה וגבול כו' אבל לא את האור הבל\"ג, כ\"א זהו שהאוא\"ס מעלים א\"ע כבי' כו', ולכן באמת הוא נמצא לאחה\"צ ממש כמו שהוא לפה\"צ כו', ובידיעתו ית' הוא שמאיר גם עתה בגילוי ממש במקום החלל כו'. והב' הוא\nשפעל הצמצום בהאור שלהאיר העולמות כו', ותחלה הוא מה שנבדל האור הזה בפ\"ע דקוה\"צ הי' מעורב וכלול בהפנימיות והי' במע' גבוה יותר וע\"י הצמצום נבדל להיות בפ\"ע שעי\"ז ירד ממדריגתו כו', ואח\"כ נמשך דרך דילוג הצמצום שעי\"ז בא בבחי' התחלקות מפני שנמשך שלא בהדרגה והיינו שנמשך דרך הצמצום שזהו מהות אחר מן האור וע\"י שנמשך דרך מהות אחר ה\"ה בא בבחי' התחלקות עי\"ז כו', ואח\"כ נתעלם תוך הכלים (דתחלת ענין הכלים הוא נקודת הרשימו כו') באופן שכל הגילוים בעולמות הוא בבחי' התלבשות שאינו עצם האור כו', כי מה שהכלי תופס אור א\"ז כמו שהאור הוא בעצם כו', וא\"כ הגילוי גם בעולמות היותר עליונים אינו האור כמו שהוא בעצם רק ע\"י התלבשות כו'. ועוד יש כמה מסכים ופרסאות בכללות ההשתל', וגם יש פרסאות המבדילות שבסבת שבה\"כ דתהו דגם פרסאות אלו ישנם ברוכ\"ד כו', דכ\"ז הוא ע\"י הצמצום שהי' באוא\"ס ב\"ה, וז\"ע ש' אלקי' שבאמצע הב' שמות דהוי' דהיינו בחי' הצמצום שפעל בב' המדרי' הנ\"ל, וא\"כ זהו ב\"פ הוי' אלקי' הא' הוי' ואלקי' שבאוא\"ס הבל\"ג והב' הוי'"],[3601331219,"ואלקי' שבהאור שבמדה וגבול הנמשך בעולמות כו'. ובכדי שיהי' גילוי אוא\"ס בעולם הרי צ\"ל היפך הצמצום והיינו להפוך הצמצום המסתיר שלא יסתיר ויעלים כו', וז\"ש בזהר מאן מנכון דחשוכא מהפך לנהורא וטעמין מרירא למתקא פי' חשוכא מהפך לנהורא שמהפך החשכות שלו ומזכך חומרי' הכחות הטבעי' שיהי' כלים לאור הנשמה כו', ועי\"ז נעשה הזיכוך למע' בהכלים שנעשים כמו האור ונעשים כלים לקבל אור עליון יותר והיינו האור כמו שהוא למע' מהכלים והכלים אינם מעלימים ומאיר בגילוי האור כמו שהוא בעצם, וטעמין מרירו למתקא הו\"ע המרירות והתעוררות רחמים על הריחוק (וזהו במדרי' תחתונות אך כמו\"כ גם המדרי' העליונות הן בבחי' ריחוק כו'), ועי\"ז נמשך גילוי בחי' עצמו' אוא\"ס הבל\"ג, והו\"ע ודרך חיים תוכחת מוסר שע\"י שמייסר א\"ע עי\"ז ודרך חיים גילוי בחי' חיים עצמי' בחי' כי עמך מקו\"ח כו', וכ\"ז נת\"ל באורך.\n<b>והנה</b> בכדי להבין בתוס' ביאור ענין היפך הצמצום לאור, יש להבין מ\"ש וידעת היום והשבות אל לבבך כי הוי' הוא אלקי' בשמים ממעל ועל הארץ מתחת אין עוד, וצ\"ל מהו\"ע בשמים ממעל ועל הארץ מתחת דמאחר דה' הוא אלקי' בשמים ממעל ממילא כמו\"כ הוא בארץ מתחת כו', שהרי בריאת השמים וארץ הי' בשוה וכמ\"ש בראשית ברא אלקי' את השמים ואת הארץ דשניהם נבראו מש' אלקי' כו', דכשם שבריאת הארץ אא\"ל מש' הוי' כמו\"כ ברי' השמים אא\"ל מש' הוי' כו', וכאשר מודיע דבאמת הוי' הוא אלקי' בשמים ממעל ממילא כמו\"כ הוא בארץ מתחת כו', וא\"כ מה צורך לומר ועל הארץ מתחת כו', גם מהו מוסיף באומרו אין עוד מאחר שאו' תחלה כי הוי' הוא אלקים בשמים ממעל ועל הארץ מתחת מהו אומרו עוד אין עוד כו', ובמד\"ר ואתחנן אמרו אין עוד אפי' בחללו ש\"ע, וצ\"ל מהו\"ע בחללו ש\"ע שזהו יחוד יותר ממ\"ש בשמים ובארץ כו', גם צ\"ל מ\"ש וידעת היום כו' כי הוי' הוא אלקי' הלא כבר נא' אתה הראת לדעת כי הוי' הוא האלקי' אין עוד מלבדו ומהו הציווי עוד וידעת היום כו'. אך הנה כללות הענין\nהוא דמ\"ש אתה הראת לדעת הוא בדרך מלמעלמ\"ט כו', דמ\"ש הראת הוא שנמשך להם מלמע' בחי' הראי' במהוע\"צ א\"ס ובמהו\"ע דהוי' ואלקי' כו', וכידוע דזה קאי על מ\"ת שהי' גילוי בחי' עצמות אוא\"ס ממש למטה כו' דבנש\"י הי' זה בבחי' גילוי או\"פ כו', וכן הדברות היו אצלם בבחי' גילוי המהות וכמ\"ש וכל העם רואים את הקולות רואים את הנשמע כו' שהדברות אנכי ולא יהי' לך הי' להם בגילוי ממש וראו אמיתי' אחדות ה' כו', וכמו שרש הנשמה למע' שרואה ממש איך שהוי' ואלקי' כו\"ח כו' (וכמ\"ש במ\"א ונת' ג\"כ לעיל דענין האמונה פשוטה דנש\"י למטה שמאמינים בחדוש העולם ובאחדות ה' בדרך אמונה פשוטה וא\"צ שום ראי' ומופת ע\"ז (ומה שיש בזה ענינים שכלי' הוא מפני שצ\"ל בבחי' ידיעה והשגה בכדי שיהי' בבחי' הרגש פנימי כו' אבל בעצם ה\"ז בנש\"י בבחי' אמונה פשוטה), הוא מראיית הנשמה למע', דלהיות דהנשמה למע' ה\"ה רואה ממש ענין התהוות יש מאין וענין ה' אחד, ומזה מתנוצץ בנשמה המלובשת בגוף ובא בבחי' אמונה כו'), ובמ\"ת נתגלה בהם שרש ומקור הנשמה וכמא' עכדו\"ד פ\"נ דהיינו התגלות\nבחי' מקיפים דנשמה כו', וזהו ג\"כ ענין אתה הראת דאתה בעצמך הראת למטה היינו שרש ומקור נשמתך כו', ועי\"ז הי' בהם הראי' ממש במהות אלקות"],[3601331220,"ואיך שה' ואלקי' כו\"ח כו', וכמו לעתיד דכתי' ונגלה כבוד ה' וראו כל בשר כו' וכתי' כי עין בעין יראו כו', כמו\"כ הי' במ\"ת כו' דכ\"ז הי' בבחי' גילוי מלמעלה שהראה להם אמיתית האלקות כו', והגילוי הי' בדרך מלמעלמ\"ט דבהתגלות עצמות אוא\"ס ב\"ה ממילא נראה ונגלה איך דכולא קמי' כל\"ח כו', ובאמת הכל מתבטל מפני הגילוי דאוא\"ס ורואין איך דה' אחד כו', וידוע דבמ\"ת הגם שהי' גילוי אוא\"ס למטה מ\"מ הרי לא נזדכך ולא נתבטל כו', אך י\"ל דנש\"י ראו איך שהמטה בטל באמת דלהיות שבהם הי' הגילוי בבחי' פנימי' ע\"כ ראו איך שהמטה בטל כו'. אמנם מ\"ש וידעת היום הוא בבחי' מלמטלמ\"ע שהאדם יהי' בו הידיעה וההכרה בכח עצמו איך שה' הוא אלקים כו', והידיעה היא בדרך מלמטלמ\"ע והיינו שמבחי' ש' אלקי' נבוא לידי ההכרה האמיתי' איך שה' הוא אלקי' כו', והוא שמהצמצום וההעלם נבין איך דהוי' הוא אלקי' כו', וגם בס' והדרגה מלמטלמ\"ע תחלה במדרי' התחתונות ואח\"כ במדרי' עליונות שעולים מדרגא לדרגא ביחוד דהוי' ואלקי' כו', דכך הוא בהעבודה שבדרך מלמטלמ\"ע שצ\"ל בהדרגה\nדוקא. וכמשנת\"ל ההפרש בין תו' לתפלה דבתו' יכולים לילך גם לעילא מדרגא, שבאם יעסוק גם בענינים שלמע' מהשגתו מ\"מ ע\"י יגיעה יבא עליהם וכמא' יגעת ומצאת כו', ומתעלה באמת בהשגתו עי\"ז שגם עניני' הקטנים בהשכלתם יבין אותם באופן אחר כו', ובתפלה אם ילך לעילא מדרגא לא יפעול מאומה ואדרבה יהי' מוטעה בנפשו ר\"ל, רק צריך לילך בהדרגה דוקא תחלה במדרי' התחתונות וכאשר הוא בעבודתו לפי אופן המדרי' ההם (אז עס מאנט זעך בא עם אוף דיא חלקי העבודה ע\"פ אותן הענינים) אז ביכולתו לילך למע' ממדרי' למדרי' כו', וזהו כללות ההפרש בב' מדרי' דבנשמות בחי' יעקב ובחי' ישראל כו' דישראל הוא מל' כי שרית עם אלקי' שמושל ושולט על השם אלקי' כו', והיינו בבחי' מלמעלמ\"ט גילוי ש' הוי' דאז ממילא נראה ונגלה איך דה' הוא האלקי' כו', ויעקב הוא עבודה בדרך מלמטלמ\"ע כו' וכמשי\"ת. וזה\"ע וידעת היום שהוא בדרך מלמטלמ\"ע כו', ומ\"ש בשמים ממעל ועל הארץ מתחת זהו בהב' מדרי' דהוי' ואלקי' שנת\"ל שזהו באוא\"ס הבל\"ג ובהאור שבמדה וגבול כו', ועז\"א בשמים ממעל ועל הארץ\nמתחת דהיינו היחוד דהוי' ואלקי' בב' המדרי' הנ\"ל, וכ\"ז הוא בהגילוי' שבעולמות ומש\"א אין עוד הוא בהעולם עצמו כו', והיינו דהיחוד דהוי' ואלקי' העיקר הוא מצד ש' הוי' ומ\"ש אין עוד הוא היחוד בש' אלקי' עצמו כו'.\n<b>ולהבין</b> זה צ\"ל מ\"ש וידעת היום והשבות אל לבבך מה\"ע אומרו היום דוקא הלא הידיעה היא תמידית כו'. אך הענין הוא דהנה כתי' ויהי ערב ויהי בקר יום אחד דיום הוא דוקא כאשר כלול מערב ובקר כו', ובמד\"ר בראשית ספ\"ג אי' בפי' יום א' א\"ר יודן שבו הי' הקב\"ה יחידי בעולמו שלא הי' בעולמו אלא הוא, עכ\"ל, וא\"כ פי' יום אחד שביום זה האיר בחי' אתה אחד כו', והגם דמע\"ב נבראו ביום הראשון וכדאי' במד\"ר שם ד' דברים נבראו ביום ראשון הרים שו\"א ואורה כו', י\"ל עפמ\"ש במד\"ר רפ\"ד ע\"פ יהי רקיע לחים היו ביום הראשון ונקרשו כו', ופי' לחים היו שלא היו עדיין בבחי' מציאות דבר כו'. והענין י\"ל עפמ\"ש במ\"א דפסוק בראשית מדבר בהתהוות האצי' דבראשית הוא בחי' חכ' וכמ\"ש ראשית חכ' כו', ואו' בראשית ב' ראשית הוא בחי' ח\"ע וח\"ת והיינו כמו שבחי' מל' כלולה בחכ' כו', אלקי' בחי' בינה ושמו\"א הן זו\"ן כו' וכמ\"ש"],[3601331221,"במ\"א, וא\"כ י\"ל דהתהוות יום ראשון הוא התהוות בחי' האצי' שאינם בבחי' מציאות וכידוע דאצי' נק' עולם האחדות כו', ומפרשי המד\"ר כ' דביום הראשון הי' מע\"ב בבחי' היולי כו', וא\"כ זהו כמ\"ש הרמב\"ן בפי' והארץ היתה תהו שהוא חומר הראשון שפשוט מכל צורה עדיין כו', ובע\"ח שמ\"א פ\"ג בפי' הפסוק מאפס ותהו נחשבו כי הא\"ס נק' אפס כי אין בו שום תפיסא כו', ואחריו יצא התהו והוא הכתר כו', כי הנה כתר הוא דוגמת חומר הקדום הנק' היולי שיש בו שרש כל הד' יסודות בכח ולא בפועל כו', וממ\"ש שם אח\"כ משמע דאפס ותהו זהו בחי' עתיק ואריך כו', וא\"כ ההתהוות דיום הראשון הוא גם למע' מאצי' והוא בחי' הכתר כו' וזהו דיום הראשון בגימט' כתר כו', וכידוע דאור שנברא ביום ראשון הוא בחי' כתר כו', וזהו שהי' הקב\"ה יחידי בעולמו, והיינו שהי' אז נראה ונגלה איך שהוא ית' אחד דגם מה שנתהווה אינו בבחי' מציאות דבר, שהרי בכתר נתהווה הכל ואינם בבחי' מציאות כלל כו'. ומזה צ\"ל מש\"א בק\"ש הוי' אחד שגם עכשיו הוא אחד כמו ביום אחד משום דלגבי עצמות אוא\"ס כולא קמי'\nכל\"ח כו', והיינו דהתהוות העולמות אינו עושה בו שום שינוי ח\"ו מפני שאינו נתפס ח\"ו בהעולמות כו', דע\"ה שהוא מקומו ש\"ע אין העולם מקומו להיות נתפס בו ח\"ו, ומה שבא בבחי' התלבשות בעולמות בבחי' כח הפועל בנפעל הוא רק הארה חיצוני' דבחי' מל' וכמ\"ש מלכותך מכ\"ע כו', וגם בהארה זו דבחי' מל' באמת גם בזה אין שום שינוי כלל דגם עז\"נ אין קדוש כה' כו', דהיינו בכלל במדרי' האצי' אינו בבחי' התלבשות ותפיסא ממש לעשות בזה איזה שינוי ח\"ו, משום דעם היותו מתלבש אינו בבחי' תפיסא כו' (ומה ששייך שינוי כמו כל מניע מתנענע בעצמו הוא בכלים דבי\"ע כו' וכמ\"ש במ\"א), אמנם גם הארה זו שבאה בבחי' התלבשות אינו תופס מקום לגבי העצמות כו' וע\"כ לגבי עצמות הכל כל\"ח כו' (וכן העולמות לגבי האור המתלבש הן כלא כו', דמאחר שאינו בבחי' תפיסא והוא קדוש ומובדל מהם וע\"כ הגם שהוא מחי' אותם מ\"מ אינן עושים שום שינוי, שזהו\"ע אתה הוא עד שלא נבה\"ע ואתה הוא משנבה\"ע דקאי על מ\"ש ואתה מחי' את כולם שזהו בחי' האותי' דמל' ששוין אחר הברי' כמו קודם הברי' משום\nשאינו בבחי' תפיסא כו' וממילא ה\"ה כל\"ח כו'). ובאמת העולמות הן בטלי' במציאות לאחר שנתהוו כמו קודם שנתהוו כו' כי האוא\"ס מאיר בגילוי בעולמות גם לאחר כל הצמצומים וממילא הכל בטל במציאות כו', וכמו ביום הראשון שהי' גילוי בחי' עצמות אוא\"ס ולא היו העולמות במציאות כנ\"ל, וכמו קוה\"צ דגליף גליפו בטה\"ע שזהו בחי' שרש העולמות כמו שהוא קוה\"צ כו', ושיער בעצמו בכח כל מה שעתיד להיות בפועל כו' (שזהו מבחי' כח הגבול שבא\"ס כו') הרי לא היו במציאות כלל דקוה\"צ אינו שייך ענין המציאות כלל וכלל כו', והיינו מצד הגילוי דאוא\"ס שמאיר בגילוי ממש ממילא לא יש ענין המציאות כו', שהרי ע\"י הצמצום נעשה בחי' המציאות וקוה\"צ לא הי' ענין המציאות כלל מפני הגילוי דאוא\"ס כו', וכידוע המשל בזה מאותיות שבעצם הנפש שהנפש מלאה אותי' כו', הרי אינם שם בבחי' מציאות כלל מפני התגלות אור הנפש שמאיר שם בגילוי ממש כו', וכמו\"כ הוא בגילוי אוא\"ס שלפה\"צ שאין האותי' דגליף גליפו בבחי' מציאות דבר כו' (וגם שזה גופא הוא א\"ס כו', וכמשנת\"ל ד\"ה ויהי הענן והחשך דגם כח הגבול הוא עצמות א\"ס כו'), וכן הי' הגילוי ביום הראשון דמע\"ב שהי'"],[3601331222,"הקב\"ה יחידי בעולמו שהי' נראה ונגלה איך שהכל בטל במציאות והוא ה' אחד כו', שהרי הכל נתהווה בבחי' הכתר ולא הי' בבחי' המציאות כלל מפני שאוא\"ס האיר בגילוי הי' נראה ונגלה איך שה' אחד כו', וכמו\"כ הוא ה' אחד גם עכשיו לאחר שנראי' בבחי' מציאות דבר, דבאמת אוא\"ס מאיר בגילוי בעולמות וה\"ה בטלי' במציאות ממש כו', וז\"ע ה' אחד לידע ולהאמין שגם עכשיו שהעולם נראה במציאות הוא באמת ה' אחד כמו ביום אחד דיום הראשון דמע\"ב כו'.\n<b>אמנם</b> ממ\"ש ויהי ערב ויהי בקר יום אחד משמע דאחד הוא דוקא כשיש ערב ובקר ומערב ובקר דוקא אנו יודעים ענין ה' אחד כו'. והענין הוא דיום הוא דוקא מערב ובקר דאין יום שאין לילו עמו דכשכולו יום או כולו לילה א\"ז יום כ\"א דוקא כשכלול מיום ולילה י\"ב שעות יום וי\"ב שעות לילה כו' (ורק לעתיד יהי' יום שכולו טוב וארוך שיהי' כולו יום, והיינו מפני שיהי' גילוי בחי' אוא\"ס הבל\"ג כו', והוא בחי' ש' הוי' דלעילא שכולו הטוב ומטיב כו' כמשנת\"ל (ד\"ה וידבר כו' במד\"ס) וע\"כ יהי' כולו יום כו', ובאמת גם לעתיד יהי' לילה ג\"כ רק שיהי' לילה כיום יאיר כו' וכמשי\"ת, וכמו ל\"ו שעות שמשה אותה האורה דמ\"מ הי' י\"ב שעות לילה כו', ובגילוי' דס' השתל' צ\"ל יום ולילה דוקא וכן יהי' בהגילוי דלעתיד כו'), ואע\"פ שאור וחשך הן מדרי' מיוחדות ומובדלות זמ\"ז, וכידוע דחשך א\"ז העדר האור כ\"א הוא ברי' בפ\"ע וכמ\"ש יוצר אור ובורא חשך כו', וכן עד רוכ\"ד יש הב' מדרי' דאור וחשך כו', וכתי' ויבדל בין האור והחשך דקודם ההבדלה היו משתמשים בערבובי' כו',\nולכאו' איך אור וחשך יכולים להיות בערבובי', אך זהו מפני שהן ב' ענינים מובדלים והיו שניהם יחד קודם ההבדלה כו' (וענין ההתכללות שלהם קודם ההבדלה שהיו בערבובי' י\"ל על ב' אופני', הא' שהאור הי' כלול בהחשך כו' והיינו בחי' החשך שהוא למע' מהאור והוא בחי' ישת חשך סתרו והוא בחי' הפנימי' דאוא\"ס שלמע' מהעולמות כו' (ואין הכוונה בזה על בחי' הפנימי' והעצמות דא\"ס רק על האור שלמע' מבחי' גילוי להאיר העולמות כו' והוא בחי' אור המאיר לעצמו כו'), והאור הוא בחי' חיצוני' האור שלהאיר את העולמות כו', דקודם ההבדלה הי' חיצוני' האור כלול בפנימי' האור והוא התכללות אור בחשך כו' וההבדלה הוא שנבדל בפ\"ע כו' וכמשנת\"ל סד\"ה ויהי הענן והחשך ויאר כו', או שההתכללות היא שהחשך הי' כלול בהאור והיינו דאור וחשך הוא בחי' משפיע ומקבל וכמו דכר ונוק' שזהו ג\"כ בחי' אור וחשך כו' (וכמו שמש ולבנה כו'), דקודם הנסירה הי' המקבל כלול בהמשפיע כו', ועמ\"ש בזהר\"ק על מאה\"ז בריש הורמנותא כו' דבוצינא דקרדוניתא שזהו בחי' הרשימו כו' ה\"ז נק' נר שהיא בחי'\nמקבל כו' וחוט הא\"ס שהוא בחי' הקו יורד ומתלבש תוך כלי הנ\"ל, וי\"ל בזה ענין ההתכללות דכוונת הצמצום נמצא כלול בהאור כו' וכמשית\"ל), ואח\"כ נבדלו ואמר זה יהי תחומך ביום וזה יהי תחומך בלילה שזהו מ\"ש ויקרא אלקי' לאור יום כו' והוא בחי' מדת יום ומדת לילה כו', מ\"מ יום שלם הוא דוקא כאשר כלול מיום ולילה כו'. דהנה תכלית השלמות הוא דוקא כשיש ב' קוין דחו\"ג (וכן הכוונה האמיתי' נשלם דוקא כשיהי' ב' קוין כו') ואם יהי' רק קו א' א\"ז שלמות כו', וכמו עד\"מ אדם שהוא רק בקו א' דחסד לבד או גבו' לבד אינו נק' שלם במדותיו ובדעתו, וכמו כאשר ישנא לכל אדם גם לאוהבו האמיתי שהוא בחי' הגבורות לבד א\"ז שלמות כו', וכן להיפך כאשר יאהב לכל"],[3601331223,"אדם אפי' לשונאו ויתנהג עמו בחסד שהוא בחי' החסדים לבד ה\"ז ג\"כ בלתי שלמות בנפש (ויהי' עי\"ז היפך הכוונה וכדאי' בזהר דאלמלא דינא כו' חטאין סגיאין כו'), רק צ\"ל ב' הקוין חו\"ג ויהיו במדה ומשקל באופן שיהי' כלולים זמ\"ז, וכמו גם לשונאו שהוא שנא אותו לא ימנע מאתו מ\"מ את הטוב מצד חלק הטוב שבו (וגם השנאה תהי' בשביל שיהי' עי\"ז תיקון נפשו כו', שכ\"ה אמיתי' הענין דהשנאה צ\"ל לא מפני שנוגע אליו כ\"א בכדי לתקן את נפש השונא כו'), וכן לא יחפה על אוהבו בדבר רע שיעשה וישנא אותו קצת משו\"ז, ובזה גופא יהי' תערובות חסד ורחמים והוא שירחם עליו ויוכיחו ע\"ז עד שיתתקן כו', וזהו השלמות דוקא כשיש ב' הקוין והן כלולין זע\"ז כו' (וכמו אברהם שהי' בתכלית מדת החסד ומ\"מ הי' כלול ג\"כ מבחי' הגבו' וכמ\"ש עתה ידעתי כי ירא אלקי' אתה כו', וגם החסד וההשפעה הי' בכוונה שעי\"ז הודיע אלקותו בעולם וא' ברכו למי שאכלתם משלו כו', ומי שלא רצה לברך הכביד עליו והתנהג אתו בגבורות כו' וכדאי' במד\"ר וירא פמ\"ט, וכמו\"כ חושך שבטו שונא בנו ואוהבו שוחרו מוסר כו'), וכ\"ה השלמות בכל המדרי' כשהן בב' קוין דוקא כו'.\n<b>וז\"ע</b> אוא\"ס למע' מע' עד אין קץ ולמטה מטה עד אין תכלית שזהו ב' קוין דחו\"ג דלמע' מע' עד אין קץ הוא בחי' ההעלם בעצמו בעילוי אחר עילוי כו', ולמטה מטה עד אין תכלית הוא בחי' הירידה והגילוי עד למטה מטה כו', וזהו משלימות העצמות להיות ב' קוין דוקא כו' (ובעצמות זהו מה שביכולתו להאיר וביכולתו שלא להאיר כו' כמ\"ש במ\"א), וכן כל ההמשכות והגילוים מרוכ\"ד עד סוכ\"ד הוא בב' קוין דחו\"ג כו', ובד\"כ זהו בחי' האורות והכלים דהאור הוא בחי' חסד והכלי היא בחי' גבו' והו\"ע הוי' ואלקי' כו', ובפרטי' באור גופא הוא בחי' האור שלמע' מהכלים והאור המתלבש בכלים והיינו שהאור שלמע' מהכלים הוא בחי' חסד שאינו מוגבל עדיין והאור המתלבש בכלים שבא בהגבלה ה\"ז בחי' גבו' כו', גם י\"ל להיפך שהאור שלמע' מהכלים הוא בחי' גבו' מפני שיש בו טבע ההעלאה והאור המתלבש בכלים מפני שהוא בבחי' ירידה והמשכה ה\"ה בבחי' חסד כו'. וכמו\"כ הוא במצות מ\"ע ומל\"ת שהן חו\"ג כו', וכנודע שהן העלאה והמשכה מל\"ת הן בבחי' העלאה ומ\"ע בבחי' המשכה וכמ\"ש שמאלו תחת\nלראשי וימינו תחבקני כו' (ובענין אור וכלי לכאו' במ\"ע ומל\"ת הוא להיפך דמ\"ע הן בחי' כלים דרמ\"ח פקודין רמ\"ח אברים דמלכא כו' ורמ\"ח ותרין דרועין אהוי\"ר בגימט' נר כו', ושס\"ה ל\"ת שס\"ה גידין שהן האור והחיות כו', ובאמת מ\"ע הן ג\"כ בבחי' אור וכלי וכמא' מעלה אני עליכם כאלו עשוני שע\"י עשיית הכלי נמשך האור כו' וכמ\"ש במ\"א וכמשנת\"ל ד\"ה צו את אהרן, רק שזהו בחי' האור שבערך הכלים כו', ומל\"ת הוא בחי' אור שלמע' מכלים ונמשך דוקא ע\"י העדר הכלי כו' וכמ\"ש במ\"א). וכן בתו' מימינו אש דת למו ג\"כ בבחי' חו\"ג כו', וכ\"ה בכל ההמשכות שאינם בקו א' כ\"א בב' הקוין דחו\"ג כו', וכמו גם בהנהגה העליונה עם האדם (שהוא בחיר הנבראים ותכלית הכוונה כו') שבא בכמה שינוים דחו\"ג הן ברוחני' והן בגשמי' כו', וכמו שאנ\"ר שאין האדם עומד במעמד ומצב א' תמיד כ\"א מתחלף מזמן לזמן כו', וכמו בגשמי' שהוא בעליות וירידות בכל ימי חייו שלפעמים הוא בעושר וכבוד ומצליח בכל עניניו ולפעמים להיפך ח\"ו או שבדבר א' הוא מצליח ובדבר א' אינו מצליח ח\"ו כו', וכמ\"ש בזהר מקץ דר\"ד ע\"א דיש עתין וזמנין ידיען לטב ויש להיפך"],[3601331224,"כו', וכ\"ה ברוחניות שאינו שוה בכל הזמנים וכמו שבע יפול צדיק וקם שבין כל עלי' ועלי' יש ירידה ונפילה כו' וכמ\"ש בסש\"ב בחינוך קטן, ויש חילופים ושינוים בעבודה דלפעמים הוא בקטנות המוחין והמדות ולפעמים בגדלות. וכמו שאנ\"ר גם בכ\"י שלפעמים יקום בשמחה ובטוב לבב בגדלות המוחין ודעתו זכה ומיושבת עליו להשכיל בטוב בהשכלה אלקי', ויהי' אופן עבודתו בתפלה ג\"כ בשמחה ובטוב לבב בהתפעלות ההתלהבות ובהתבוננות טובה בגדלות הבורא דיחו\"ע ויחו\"ת בעומק ההשגה ועומק הלב, וגם בבחי' ראי' מקרוב בעין השכל דחכ' שבמוח ולב כו' ובבחי' ביטול והזזה ממקומו לגמרי מכל וכל כו', ולפעמים יקום בבקר בלב נשבר ושפלות ועוצב והכנעה בלי שום טעם כלל, ויהי' אופן עבודתו בתפלה בקטנות המוחין ורק במרירות ולב נשבר על ריחוקו מה' כו', ולא יוכל להעמיק דעתו ולבו בהתבוננות אלקי ולבא להתפעלות אה' בחדוה ועונג כלל רק במרירות ושפלות לבד בזאת יומשך כל עיקר עבודתו בתפלה כו', וזהו כענין יום ולילה דלילה הוא זמן השינה שהכחות פנימי' דשכל ומדות מסתלקים ואינו נראה\nונגלה אור וחיות פנימי בגילוי מנפשו רק קיסטא דחיותא לבד כו', וביום הוא גילוי הנפש בהתגלות המוחין והמדות כו', וכ\"ה בעבודה לפעמים בגדלות ולפעמים בקטנות כו' (וע\"כ לא יפול לב האדם בעצמו כשהוא בבחי' קטנות המוחין דכ\"ה ס' ההמשכה מלמעלה בבחי' חו\"ג שמזה הוא בחי' הקטנות וגדלות כו', וכשהוא בבחי' קטנות צריך לידע נאמנה שבאם רק יעבוד עבודתו יבא לבחי' גדלות כו', ואדרבא מבחי' הקטנות יבא לבחי' גדלות עליונה יותר כו' וכמשי\"ת). וזהו מה שנצטוינו במצות ק\"ש ודברת בם בשבתך בביתך ובלכתך בדרך ובשכבך ובקומך, דב' ענינים אלו דבשבתך ובלכתך וענין בשכבך ובקומך הן ענין א' שהן ב' קצוות הרחוקים זמ\"ז בתכלית כמו ההבדל הרחוק בין אור לחשך ויום ולילה כו', וכמו בשינוי העתים באדם שיש עתים שהוא בעילוי בנפשו בגדלות המוחין והמדות כנ\"ל (ואז הוא נוח לבריות ומדבר עם כל אדם באהבה ומטיב חסדו כו' והוא עניו וסבלן באותה שעה ומעביר על מדותיו כו'), ולפעמים הוא להיפך בקטנות המוחין (ואז הוא ברוע לבב ולא יסבול לשום אדם כו'), וזהו כמו הריחוק\nוההבדל בין בשבתו בביתו בשלוה ומנוחה בדירה נאה המרחבת דעתו של אדם כו' ויכול לקבל במוחו השגה דתו' או השגה אלקי' בגדולת ה' כו', ולהיפך כאשר נוסע בדרך שמטולטל ממקומו וטרוד בעסקיו ומוחו ולבו בל עמו שאינו כלי כלל לאיזה השגה וידיעה כו', ועכ\"ז מצווה ועומד במצות ה' בקריאת התורה וק\"ש גם בלכתו בדרך כמו בשבתו בביתו, כי מצות ק\"ש וד\"ת שבבחי' קטנות המוחין יעלו לה' כאשר רק מכוון לש\"ש לעשות רצונו ית' ולקבל עליו עומ\"ש באמונה פשוטה אף בלא מוח ולב כלל כו', וכמו בק\"ש שעהמ\"ט דידוע שזהו עבודה, שהרי התחלת עבודת היום הוא מן ק\"ש שעהמ\"ט כו' כידוע ומבו' במ\"א, ומ\"מ כשקורא ק\"ש שעהמ\"ט אף שהוא מנמנם עיף ויגע כו' ג\"ז יעלה לרצון לה' כאשר הוא במח' טובה לש\"ש גם בלא השגה ועומק הלב כלל כו', וכמ\"ש דוד אם זכרתיך על יצועי בבחי' קטנות המוח והלב כו' ובאשמורות אהגה בך בבחי' הגדלות כו' (שזהו\"ע בשכבך ובקומך בזמן שכיבה בחי' מדת לילה ובזמן קימה מדת יום כו') הכל שוין לפניו ית', וכ\"ז הוא מפני שכ\"ה המדה בב' המדרי' דיום ולילה שזהו משלימות העצמות להיות ב' קוין אלו כו', וע\"כ שניהם שוין לפניו ית'."],[3601331225,"<b>ועפ\"ז</b> יובן מ\"ש וידבר אלקי' גבי מ\"ת דלהיות שמשלימות העצמות הוא שיהי' ב' קוין דוקא, ובתורה גופא הרי ג\"כ יש הב' קוין שהו\"ע מימינו אש דת כו', ע\"כ במ\"ת שהי' גילוי אוא\"ס נא' ש' אלקים שהוא בחי' הגבו' כו'. וזהו וידבר אלקים כו' אנכי ה' אלקיך בחי' חו\"ג כו' (ועמ\"ש באוה\"ח), ובפרט שהגילוי הוא דוקא ע\"י ש' אלקי' ומש' אלקים עצמו הגילוי הוא ביותר כו' וכמשי\"ת, ע\"כ נא' במ\"ת וידבר אלקים את כל הדברים האלה כו'."],[3601331226,"<h3>בס\"ד. ליל ב' דחה\"ש, העת\"ר</h3>\n<b>וכל</b> העם רואים את הקולות כו' וירא העם וינועו ויעמדו מרחוק, ופרש\"י אין נוע אלא ל' זיע, והיינו שנזדעזעו ונרתעו מהקולות וברקים וכמ\"ש לפני זה ויהי קולות וברקים כו' ויחרד כל העם אשר במחנה, וצ\"ל מה\"ע הפחד והחרדה שהי' במ\"ת, הלא ענין מ\"ת הי' להיות גילוי אוא\"ס בנש\"י הן בעצם הנתינה דתו' והן בהגילוי אוא\"ס שהי' במ\"ת כו', ועל מה היו הקולות וברקים בכדי להחרידם כו', והמשמעות הוא שזה הי' מעיקרי הענינים במ\"ת שהרי ארז\"ל מה להלן באימה וביראה ורתת וזיע אף כאן כו', וצ\"ל מה\"ע החרדה שהי' צ\"ל במ\"ת כו'. ולהבין זה ילה\"ק משנת\"ל בענין ויהי ערב ויהי בקר דיום שלם הוא דוקא מערב ובקר כי תכלית השלמות הוא דוקא בשני קוין דשלמות העצמות הוא בשני קוין דחו\"ג, שז\"ע דאוא\"ס למע' מע' עד אין קץ ולמטה מטה עד אין תכלית כו', וכ\"ה במצות ותו' וכן בכל ההמשכות והגילוים ובעבודת האדם הכל הוא בב' המדרי' דחו\"ג שהן יום ולילה כו'.\n<b>והנה</b> סדר ההמשכה דבחי' יום ולילה הנה הגם דבחי' יום יש לו קדימת המע' על בחי' לילה דלילה הוא בחי' חשך ויום הוא אור וגילוי וכמ\"ש חסד אל כל היום כו', מ\"מ הלילה קדמה ליום וכדאי' במשנה בפ\"ה דחולין דבמע\"ב היום הולך אחר הלילה דמתחלה ויהי ערב והדר ויהי בקר כו', וכידוע הכלל דלאו קודם להן שהגבו' קודם לחסדים כו', וכמו שהצמצום הראשון קדום לגילוי הקו כו', הגם דסבת ברה\"ע הוא מצד החסד וכמ\"ש בע\"ח כשעלה ברצונו ית' לברוא את העולם בכדי להטיב לברואיו כו', והכוונה הוא שיהי' גילוי אור בעולם וכמ\"ש בזהר בגין דישתמודעון בי' כו', ובע\"ח כ' בכדי שיתגלו שלימות כחותיו ופעולותיו כו', ובפרט הכוונה הפנימי' דנתאווה הקב\"ה להיות לו דב\"ת כו', הרי תכלית הכוונה הוא הגילוי כו', מ\"מ קדם תחלה הצמצום שהוא בחי' העלם האור לגמרי ואח\"כ הי' המשכת הקו כו', וכמא' כברייתו ש\"ע ברישא חשוכא והדר נהורא כו', וכמא' בתחלה עבמ\"ח לברוא את העולם במדה\"ד ואח\"כ שיתוף עמו מדה\"ר כו', הרי שהצמצום קדום אל הגילוי שהרי מתחלה עבמ\"ח כו' (ומובן מזה שהצמצום יש לו קדימה מעלית על הגילוי לא רק קדימה זמני' כו', דלכאו' א\"מ מ\"ש בתחלה"],[3601331227,"עבמ\"ח לברוא כו' הרי הי' בפועל כן דבראשית ברא אלקי' כו', אך באמת בבחי' המשכה מן העצמות הי' תחלה גילוי ואח\"כ העלם והוא מה שהי' אוא\"ס ממלא כל מקום החלל ואח\"כ העלם הצמצום כו', וא\"כ זהו סוף מעשה שהוא תכלית הכוונה כו', וא\"כ מה שהגבו' קודם לחסדי' הוא שקדמו בשרשם ומקורם כו', וכן יהי' לעתיד מעלת הגבו' על החסדים כו' וכמשי\"ת), ולכאו' זהו היפך הכוונה שהוא בחי' הגילוי דוקא. אך הענין הוא דהצמצום גופא הוא בשביל הגילוי שהרי אין הכוונה בהצמצום להיות בחי' חשך והעלם רק להיות בחי' הגילוי דוקא, וכמו עד\"מ במשפיע ומקבל הרי המשפיע כשהוא משכיל ההשכלה לעצמו א\"צ שום צמצום כלל ומאיר אצלו אור השכל בגילוי ממש כו', אך כשרוצה להשפיע לזולתו ה\"ה מצמצם אור שכלו כו' הרי הצמצום הוא דוקא כשצריך להשפיע כו', הרי שהצמצום הוא בשביל הגילוי שאם א\"צ להשפיע א\"צ לצמצם רק כשצריך להשפיע אז דוקא מצמצם עצמו כו', והכוונה בהצמצום הוא שיהי' עי\"ז הגילוי כו', וע\"כ בהצמצום הגם שהוא בחי' התעלמות האור נמצא עי\"ז דוקא האור השייך אל המקבל, שהרי\nבהמשפיע קודם שמצמצם עצמו אינו ניכר כלל האור שכל השייך אל המקבל כ\"א ע\"י הצמצום דוקא (והצמצום צ\"ל בבחי' התעלמות לגמרי) עי\"ז נמצא האור שכל השייך אל המקבל, וגם נמשך בזה עצמות אורו העצמי כו', וכידוע שע\"י שהמשפיע מצמצם אור שכלו העצמי הנה הגם שבהתגלות מה שנמצא בזה הוא רק האור שכל השייך אל המקבל, מ\"מ הרי ניתן בזה גם האור העצמי של המשפיע כו', ובלתי הצמצום הרי האור העצמי בודאי לא הי' נמשך בזה כ\"א זהו ע\"י הצמצום דוקא כו', והאור העצמי בא בדקדוק האותי' והתי' שבהם משפיע את השכל, דלכאו' אין בהם נ\"מ לגוף ההשפעה ובאמת בזה דוקא מתעלם פנימי' הכוונה כו', ואם הי' הצמצום בכוונה להעלים לא הי' בזה התגלות אפי' חיצוני' השכל ומכ\"ש שלא הי' בזה הפנימי' כו', אלא שכוונת הצמצום הוא לגלות דוקא רק שא\"א להיות הגילוי אל המקבל כ\"א ע\"י הצמצום (והיינו שאא\"ל השפעה וגילוי חוץ לעצמו רק ע\"י הצמצום כו', דלעצמו הגילוי הוא בלי צמצום ולכן הוא בבחי' בל\"ג שזהו בלי צמצום כו', וגם מה שהוא בבחי' או\"פ וכמו גילוי השכל לעצמו כו' אינו בבחי'\nגבול כ\"כ ואינו בבחי' התלבשות כו', ומ\"מ בבחי' או\"פ גם לעצמו יש איזה צמצום והוא מה שהשכיל את השכל, דע\"ה שנראה בחוש דהצמצום הוא רק כשצריך להשפיע לזולתו אבל לעצמו בא השכל בלא צמצום, אבל מ\"מ מה שמשכיל את השכל ה\"ז כעין הצמצום שהרי אינו בא מעצמו כמו הרצון שבא מאיליו, אבל השכל הרי צריך להשכיל וה\"ז בא ע\"י איזה צמצום המגלה ומגביל כו', רק מה שבל\"ג הוא בלי צמצום, והיינו בגילוים מהנפש הבאים מאיליו וממילא וכמו הרצון וכה\"ג (וזהו המבו' בכ\"מ דהאור הבל\"ג הוא אור הכלול בעצמותו כו'), ומ\"מ גם האו\"פ כמו שהוא לעצמו אינו ע\"י צמצום ובכדי לגלות חוץ לעצמותו צ\"ל ע\"י הצמצום כו', וכן המקבל ביכולתו לקבל רק ע\"י צמצום כו'). אבל הכוונה בהצמצום הוא לגלות וע\"כ ע\"י הצמצום נמשך גילוי האור גם האור העצמי כו'.\n<b>וכמו\"כ</b> הוא למע' דהצמצום הוא בשביל הגילוי וכמ\"ש בע\"ח טרם שנאצלו הנאצלי' הי' אור עליון פשוט ממלא כל המציאות כו', והוא הגילוי דאוא\"ס בלי שום צמצום והעלם כלל כו' והוא בחי' אור המאיר לעצמו כו', וכשעלה ברצונו לברוא העולמות ולהאציל הנאצלים בכדי להוציא פעולתו"],[3601331228,"כו' צמצם עצמו כו', שהצמצום הוא בשביל ההשפעה והגילוי דוקא שיתגלו שלימות כחותיו ופעולותיו כו' (ורק בזמן המבול הי' צמצום והעלם לבד וכמ\"ש ה' למבול ישב ישב בלחודוהי כו' שהי' רק ש' אלקי' לבד כו', דבאמת צמצום כזה אינו מע' כלל כו', והצמצום הראשון וכן כל הצמצומים דס' השתל' הכל הוא בשביל הגילוי כו'), ולכן הי' הצמצום באופן כזה שיהי' ע\"י הגילוי כו', וכמו במשל הנ\"ל שאם יהי' הצמצום בכדי להעלים לא יהי' עי\"ז הגילוי שלא ימצא עי\"ז האור שכל השייך אל המקבל, ורק כשהוא בשביל הגילוי אז דוקא נמצא השכל השייך אל המקבל וגם יש בזה הפנימי' כו'. וי\"ל שההפרש בזה הוא אם הצמצום הוא בהכרח או ברצון, דהנה מה שאנו אומרים שהצמצום הוא בשביל להעלים אין הכוונה שעוצר ומעכב ההשפעה בעצמו דפשוט הוא שזהו העדר הגילוי כו', וכמו שהצמצום שהוא בשביל הגילוי א\"ז שאינו מעלים האור לגמרי שהרי ידוע שבאם לא יעלים האור לגמרי לא ימצא כלל האור שכל השייך אל המקבל, כ\"א דוקא ע\"י שמעלים האור לגמרי עי\"ז דוקא נמצא האור השייך אל המקבל, הרי שהצמצום\nשבשביל הגילוי א\"ז שאינו מעלים את האור, כמו\"כ הצמצום שהוא להעלים א\"ז שעוצר ומעכב ההשפעה והגילוי כ\"א זהו דבר הבא בדרך ממילא כו', והיינו דכאשר הצמצום הוא בהכרח שאינו רוצה בהמקבל ואינו רוצה להשפיע אז ממילא הוא בבחי' העלם, אבל כשהוא ברצון היינו שרוצה בהמקבל ורוצה להשפיע לו אז הצמצום הוא בעין טובה והוא בשביל הגילוי כו'. והדוגמא מצמצום בהכרח י\"ל למע' כמו ההשפעה לע\"ש שזהו בדרך הכרח כבי' וכמאן דשדי כו' וה\"ז בבחי' העלם ממש כו', ומה שנשפע הוא רק השפעות גשמי' כו', ובמדרי' עליונה י\"ל שז\"ע דין לא הניין לי' כו' שנעשו עי\"ז מסכים המבדילים כו' וכמשנת\"ל (ד\"ה וידבר כו' במד\"ס), אבל בקדושה הצמצום הוא ברצון ועין טובה בכדי להשפיע כו', ולכן ע\"י הצמצום הוא גילוי אור כו', וכידוע שע\"י הצמצום נמצא האור השייך אל העולמות ונכלל בנקודת הרשימו כו', וידוע דנקודה זו לבד מה שכוללת בעצמו כל האור הנמשך אח\"כ בהשתל' הרי כוללת גם בחי' עצמות האור כו', רק שהוא בהעלם אבל נמצא בה כל העצמות כו' (וכמו בתושב\"כ הרי בהאותי' והתי' נמצא\nעומק החכ' בהעלם יותר ממה שבא בנגלה כו', שהרי כל תושבע\"פ הוא מדרשת האותי' והתי' הנראי' לכאו' מיותר ובזה דוקא הוא עומק החכ' והכוונה האמיתי' כו', וכן כל הסודות ורזין דאורייתא הן בהאותי' וקוצין ותגין כו'), וכ\"ז הוא מפני שהצמצום הוא בשביל הגילוי כו'. ונמצא דע\"ה שהצמצום הו\"ע הפכי מהגילוי מ\"מ יש בזה דוקא כוונת ורצון של הגילוי והוא באופן כזה דוקא שיהי' בו וע\"י הגילוי כו', והיינו שהצמצום גופא הוא ברצון ועין טובה באופן שיהי' ע\"י הגילוי דוקא כו'.\n<b>וכשם</b> שבהצמצום נמצא כלול כוונת הגילוי כמו\"כ בהגילוי נמצא כלול כוונת הצמצום כו'. והענין הוא דהנה בחי' הגילוי והצמצום כמו שמושרש בעצמות הוא מה שביכולתו להאיר וביכולתו שלא להאיר כו', והנה מה שביכולתו להאיר הכוונה בזה ג\"כ האור להאיר את העולמות כו', והיינו לא רק לגלות את העצמות כ\"א להאיר העולמות כו' והאור והגילוי הזה הוא ע\"י הצמצום דוקא, וא\"כ הרי באור זה נכלל ג\"כ כוונת הצמצום שהרי בלתי הצמצום לא יושלם כוונת הגילוי כו' (וכבר נת\"ל בכ\"ד שהאור הזה הוא ג\"כ מאוא\"ס הבל\"ג רק שזהו מה שעלה ברצונו להאיר"],[3601331229,"במדה וגבול כו'), א\"כ הרי בהגילוי כלול כוונת הצמצום כו', והן משלימים זא\"ז דכשם שכוונת הצמצום נשלם ע\"י הגילוי שהרי הצמצום הוא בשביל הגילוי ואם לא יהי' הגילוי הרי אין זה כוונת הצמצום כלל כו' (ואדרבה הוא היפך הכוונה לגמרי וכמו כשנאחז בהצמצום ובהעלמות והסתרים ואינו חפץ בהגילוי כו', או שמחשב הצמצום לעיקר ה\"ז היפך הכוונה לגמרי כו'), כמו\"כ כוונת הגילוי נשלם ע\"י הצמצום דוקא כו', וגם בהאור שלגלות העצמות והוא בחי' אוא\"ס הבל\"ג הרי גם בזה הכוונה שיהי' הגילוי מזה והמציאות לא יתבטל מ\"מ שזהו ע\"י הצמצום כו'. דהנה יש לפעמים גילוי כזה שהכוונה היא שיתבטל ענין הצמצום, וכמו ויצא מלאך ה' ויך במחנה אשור כו' וכמו הושיט הקב\"ה אצבעו הקטנה כו', אבל בסט' דקדושה הרי צ\"ל גילוי זה ג\"כ וכמו ואתה משמרה בקרבי שזהו מבחי' האו\"מ כו', וגם יש גילוי האו\"מ וכמו בקיום המצות שע\"י עשיית המצוה נמשך או\"מ על האדם וכמ\"ש בסש\"ב, ויש בזה כמה אופנים וכאשר עשיית המצוה היא בבחי' ערש\"מ נמשך גילוי האו\"מ ממש כו', וכן בעבודה דרעו\"ד כו', והכוונה\nבזה דמ\"מ יהי' ענין המציאות כו' (שהרי בני אהרן שהי' הקירוב שלהם באופן כזה שנתבטלו לגמרי הי' נחשב זה לחטא כו' וכמו בן עזאי הציץ כו' וכמ\"ש במ\"א) שזהו ע\"י הצמצום דוקא כו', וכמו במ\"ת שהי' גילוי אוא\"ס ממש למטה ומ\"מ הי' המטה במקומו כו' שזהו ע\"י ש' אד' כו' וכמשנת\"ל (ד\"ה מצה זו). ונודע דהתהוות היש הוא מאוא\"ס הסוכ\"ע דוקא וכמ\"ש כל אשר חפץ ה' עשה כו', וע\"ה שזהו מצד כח הא\"ס הכל יכול ובכח הכל יכול הוא שגם כשיהי' גילוי אוא\"ס יהי' התהוות היש, ומ\"מ ההתהוות הוא ע\"י הצמצום כו' והיינו ע\"י התעלמות האור כו', וכידוע ההפרש באופן ההתהוות דבחי' ממכ\"ע לההתהוות דבחי' סוכ\"ע, דמבחי' ממכ\"ע אופן ההתהוות הוא ע\"י ההתלבשות דבחי' כח הפועל בהנפעל כו' והיינו בבחי' קירוב כו', והתלבשות זו הוא ע\"י הכלים והפרסאות בבחי' העלם והסתר הבורא מהנברא כו', ומ\"מ הוא בבחי' קירוב ויש בזה ג\"כ קצת גילוי כו', ומשו\"ז יש חילוקים בנבראים וכמו במעלת הדצח\"מ שהן למע' זמ\"ז ובפרט המדבר שלמע' מכולם, שזהו מצד החילוקים בהכח האלקי המהווה באופן הקירוב\nוהגילוי כו', וכשם שנבראי' שלמע' הם גבוהים במעלתם על הנבראים התחתונים עם היותם ג\"כ נבראים רק שהן נבראים רוחני' כו', ובהם יש ג\"כ חילוקי מדרי' שיש נבראי' שהן בבחי' נבראו בדרך ממילא ויש שבבחי' ברא שהן יותר בדרך מאין ליש כו' וכמ\"ש במ\"א, וכמו נבראי' דעדאת\"כ ונבראים דעדאת\"ג כו' ובכללות הן נבראים רוחני' כו', וזהו מפני שהאין האלקי הוא בבחי' גילוי יותר והיינו שנרגש שם עכ\"פ בחי' המציאות דאלקות כו', וכידוע דזהו ההפרש בין אצי' לבי\"ע דאצי' הוא בחי' המהות דאלקות (וכמשנת\"ל ד\"ה אדם כי יהי') ומבחי' המהות דאלקות אא\"ל מציאות יש, ובבי\"ע הוא בחי' המציאות לבד וע\"כ נתהוו בבחי' יש כו', ומ\"מ מפני שנרגש שם בחי' המציאות דאלקות ה\"ה נבראי' רוחני' והתחתונים הן נבראים גשמי' כו'. וכמו\"כ יש חילוק בתחתונים ג\"כ בפרטי מדרי' דצח\"מ, וכן בהאדם בפרט יש כמה חילוקים שיש מי שהוא בטבעו רך ודק יותר והוא יותר כלי לאור אלקי כו' שזהו מצד כח האלקי המהווה כו', והוא בבחי' התהוות דמבחי' ממכ\"ע, דהרי מצד אור הסובב הכל בשוה וכמו השוה ומשוה קטן וגדול כו', וכ\"ז הוא מפני שאופן ההתהוות הוא בבחי' קירוב כו'."],[3601331230,"<b>אבל</b> ההתהוות שמאוא\"ס הסובב הוא ע\"י ההתעלמות דוקא היינו לא בבחי' התלבשות בבחי' קירוב כ\"א שסובב ומקיף עליו מלמע' כו', ופי' סובב הרי א\"ז שסובב ומקיף מלמע' כ\"א שנמצא בתוך תוכו ופנימיותו רק שמתעלם ממנו להיות בבחי' ריחוק ממנו כו', וכמ\"ש בסש\"ב פמ\"ח שנק' סובב רק לענין גילוי ההשפעה דכאשר ההשפעה היא בגילוי ה\"ז התלבשות וכאשר היא בהעלם ה\"ז בבחי' מקיף כו' ובהתעלמו' זאת הוא שנעשה התהוות היש כו'. וכמו בענין המלוכה שזהו בבחי' רוממות והתנשאות וע\"י הרוממות דוקא נעשי' בבחי' עם להיות הוא מלך עליהם כו', שאם המלך הי' בקירוב אל העם ומעורב עמהם לא הי' בבחי' עם ולא הי' ענין המלוכה כלל כו', כ\"א דוקא ע\"י שמרומם ומתנשא עליהם עי\"ז הן בבחי' עם והוא מלך עליהם כו'. וכמו\"כ הוא בענין ההתהוות דמאוא\"ס הסוכ\"ע שע\"י הרוממות וההסתלקות עי\"ז דוקא נעשי' בבחי' יש כו', שז\"ע והים עומד עליהם מלמע' כו' וכמ\"ש בלק\"ת בהבי' דמי מנה וכמ\"ש במ\"א בענין עה\"ע וסה\"ס כו'. והרי התעלמות זאת היא ג\"כ ע\"י הצמצום כו' וכמשנת\"ל (ד\"ה ויהי הענן\nוהחשך), וגם אמיתי' הכוונה בהאוא\"ס הבל\"ג הוא שיהי' גם אור זה בבחי' גילוי בפנימי' כו' (רק שזהו בבחי' הפנימי' דאוא\"ס הבל\"ג כו' וכמשי\"ת), והיינו שיהי' ג\"כ בגילוי בכלים כו', והרי כ\"ז הוא ע\"י הצמצום כו'. ונמצא שבהגילוי דאוא\"ס יש כוונת הצמצום שעי\"ז דוקא נשלם כוונת הגילוי כו', וגם אופן הגילוי הוא באופן כזה הוא שיהי' הצמצום ושיפעול בו הצמצום להשלים הכוונה כו'. שהרי האור שלהאיר העולמות ודאי אופן המשכתו וגילויו מן העצמות הוא באופן כזה שיהי' הצמצום ושהצמצום יפעול בו כו', שהרי הוא בההשערה להיות בבחי' מדה וגבול כו', וכמשנת\"ל שגם בשרש האורות לפה\"צ יש בו ע\"ס כו', וזהו הסבה מה שהצמצום מגביל ומעלים את האור מפני ההשערה באוא\"ס להאיר בבחי' מדה וגבול כו'. אמנם גם האוא\"ס הבל\"ג המשכתו מן העצמות הוא באופן כזה שיהי' בחי' הצמצום כו' שהרי הצמצום הוא בבחי' ההתפשטות דאוא\"ס כו', והיינו שאוא\"ס בא בבחי' התפשטות בכדי שיוכל להיות ענין הצמצום כו'. וגם י\"ל עפמ\"ש במ\"א שמהאור אין אנו יודעים את העצמות דע\"ה שהאור מעין המאור\nמ\"מ אין אנו יודעים את העצמות מן האור כו', והיינו שגם מהאור הבל\"ג שהוא לגלות עצמותו אין אנו יודעים את העצמות כו', כי לא זהו כל עצמותו מה שהאור נמשך ממנו והעצמות נושא בעצמו כמה ענינים שלא נתגלו ואין אנו יודעים ממנו רק מה שנתגלה הוא בחי' האור כו', ולפ\"ז י\"ל דמה שנתגלה בחי' האור הוא מפני שהכוונה בתחלה הוא שיתעלם ע\"י הצמצום כו' ע\"כ נתגלה רק בחי' האור שזה אפשר שיתעלם ע\"י הצמצום כו', ולא נתגלה כל מה שבעצמות שלא יתעלם ע\"י הצמצום כו', והגם שבאמת אין שום מניעה ועיכוב לגבי העצמות, אך בס' והדרגה הוא שהאור מתעלם. וכמו שאנ\"ר גם במה שנתהווה בעולמות שיש מה שמתעלם ויש מה שאינו מתעלם כ\"כ, וכמו האור מתעלם ע\"י המסך והאויר אינו מתעלם, ובכדי לעכב ולעצור את האויר צריכים אמצעים גדולים וחזקים כו', וידוע דלמע' אויר למע' מאור כו', וכמו\"כ בכחות הרי כח השכל בנקל לעכב ולהעלים משא\"כ כח הרצון אינו בנקל להעלים, ובפרט גילוי עצמי צריכים כח חזק לעכב ולהעלים כו', וכמו אאע\"ה שכבש רחמיו מעל בנו יחידו ה\"ז נסיון גדול שזה לו לזכות גדול לו ולבניו אחריו כו', והכח לעכב גילוי עצמי הוא רק בדרך כח עליון והיינו רק"],[3601331231,"מצד הציווי והוא בדרך הפקרות שמפקיר א\"ע (ובאברהם אפשר הי' זה ברצון ועונג כו'), וגם זה במי שיכול להתגבר על עצמו ולהפקיר א\"ע כו', הרי שיש מה שיכול להתעלם ומה שא\"י להתעלם כו', ועם שכ\"ז אינו שייך בעצמות, מ\"מ כמו שהוא בהדרגה הוא באופן כזה, וע\"כ שזה שנתגלה בחי' האור מפני שזה אפשר להתעלם כו' (ולעתיד שנא' יקימנו ונחי' לפניו ממש יהי' גילוי בחי' העצמות כו'), וזהו שאופן הגילוי וההמשכה מן העצמות הוא שיהי' הצמצום כו', והיינו שהצמצום נמצא כלול בהגילוי והצמצום הוא בכוונה שיהי' הגילוי דוקא כו'. ונמצא הגם דעיקר הכוונה הוא הגילוי מ\"מ קדם הצמצום שהוא העדר האור והגילוי (וגם בתחלת ההמשכה והגילוי מן העצמות שהי' הגילוי קודם להצמצום דתחלה הי' אוא\"ס ממלא מקום החלל ואח\"כ צמצם עצמו כו', וכידוע דמלמע' תחלה מטי ואח\"כ לא מטי כו', הנה גם בזה הי' כלול כוונת הצמצום כו' כנ\"ל), משום שע\"י הצמצום והעדר הגילוי עי\"ז הוא דוקא הגילוי שהצמצום הוא סבת הגילוי (הן מצד המשפיע והן מצד המקבל כו' כנ\"ל), וזהו הכוונה בהצמצום להיות בו\nוע\"י הגילוי כו', והצמצום הוא טפל אל הגילוי כי הגילוי הוא העיקר ומ\"מ קדם אליו הצמצום כו', כי העדר הוא קודם להוי' וכל הוי' צ\"ל תחלה העדר כי ההעדר הוא סבת ההוי' וממילא ההעדר הוא התחלת ההוי' כו'. וכמו עד\"מ בזריעת הגרעין בארץ הרי דוקא ע\"י שנרקב הגרעין עי\"ז הוא הצמיחה שבאם לא ירקב לא יהי' שום צמיחה כ\"א כאשר נרקב דוקא אז הוא הצמיחה והצמיחה היא מכח הצומח, דהארה מכח הצומח מתלבש בהגרעין ועי\"ז הוא הצמיחה כו', ודוקא כאשר נרקב הגרעין ונפסד צורתו לגמרי עי\"ז הוא הצמיחה וכל שנרקב ונפסד ביותר הצמיחה היא בריבוי ביותר כו', הרי שההעדר הוא דוקא סבת ההוי' והצמיחה, והוא התחלת הצמיחה כי כאשר נרקב הגרעין תהי' הצמיחה כו', וכ\"ה בכל הדברים שההעדר הוא קודם והוא דוקא סבת ההוי' כו', וכמו הזורעים בדמעה ברנה יקצורו דבעת הזריעה אינו יודע איך תהי' הצמיחה ובפרט בארץ הנגב שהיא חרבה ויבשה ה\"ה כמיואש וזורע רק בבטחון בהשי\"ת וכמא' מאמין בחיי עולם וזורע כו', והם דוקא ברנה יקצורו כו'.\n<b>ובמד\"ר</b> פ' וישלח פע\"ט אי' הזורעי' בדמעה זה יעקב אבינו שזרע את הברכות בדמעה שנא' אולי ימושני אבי והי' כמיואש בנפשו שפחד בלבו אולי עוד יבוא עליו כו', וכמ\"ש במד\"ר תולדות פס\"ה וילך ויקח ויבא לאמו אנוס וכפוף ובוכה ועשה רק משום מורא ובהבטחון בהבטחת אמו רבקה, וכדאי' במד\"ר שם גדיי עזים טובים טובים לך שע\"י אתה נוטל את הברכות כו', ברנה יקצורו ויתן לך האלקי' מטל השמים כו', וכ\"ה בגשמי' כמו במו\"מ דפרנסה שא\"א לאדם להרויח בעסקיו כ\"א אחר היגיעה ופיזור הנפש, וכמה פעמים בצער ויסורים ר\"ל מכמה מניעות ועיכובים עד שיאמר נואש לנפשו ויהי' לבו נשבר ונכנע ושפל לכל כו', ואזי יצליח לו ה' ויראה ברכה במעשיו, שזהו אור החסד דפרנסה שבא דוקא אחה\"צ וההעדר כו' שההעדר שזהו הצער וההכנעה הוא סבת הברכה וההשפעה כו'. וכ\"ה ברוחני' כמו בעסק התו' שזהו ע\"י יגיעה דוקא וכמא' אם יגעת ומצאת תאמין כו', ואין התו' מתקיימת אלא במי שממית עצמו עלי' וכמ\"ש אדם כי ימות באהל כו', הרוצה לחיות ימית עצמו כו', והצלחת הלימוד הוא דוקא ע\"י\nיגיעה גדולה ביותר וע\"י הנתינה והמסירה שמוסר עצמו לעסק התו' כו', ולפעמים יהי' בצער ויסורים גדולים ר\"ל מהעדר הידיעה ומאד לא טוב"],[3601331232,"לו מזה עד שמואס בחייו ממש ונשבר לבו ורוחו בקרבו כו', ואז דוקא יאיר לו אור ה' ויבא על הענין ואדרבה בריבוי גילוי אור ביותר כו'. וכ\"ה בעבודה בתפלה שאא\"ל השגה והתבוננות טובה להשיג הענין האלקי בטוב ובפרט שיונח אצלו הענין ויוקלט במוחו ולבו ולהתפעל באהוי\"ר כ\"א בהקדם תחלה השפלות ומרירות הנק' כובד ראש כו', וכמא' אין עומדין להתפלל אלא מתוך כובד ראש כו', וכידוע דהתחלת עבודת היום הוא מתיקון חצות שהוא המרירות העצומה על הריחוק ועל גלות השכינה וגלות נפשו בריבוי ההעלמות והסתרים כו' ועי\"ז דוקא עבודת היום עבודה אמיתי' כו', דהעבודה בתפלה צ\"ל בשמחה דוקא כמ\"ש עבדו את ה' בשמחה כו', והשמחה היא מן הגילוי בההתבוננות האלקי שהאור האלקי מאיר נפשו כו', וגם שמחה גורם גילוי להיות שהשמחה היא פתיחת הנפש ע\"כ היא גורם את הגילוי כו', וכ\"ז הוא דוקא כאשר בתחלה הוא המרירות והשפלות אז היא העבודה בשמחה אמיתי' שמחו צדיקים בה' כו', והא בהא תלי' לפ\"ע דוקא דכל מה שלבו נשבר ונדכה בשפלות וכובד ראש בהכנעת הלב ובושה גדולה מאשר נתרחק\nמאור פני מלך בח\"נ וכה\"ג, כך לפ\"ע יאיר האור האלקי באור וחיות בנשמתו בהשגה האלקי' ובהתפעלות האה' כו', והוא ג\"כ ענין יום ולילה וכמו בלילה שמסתלק אור השמש כך ישים אשם נפשו שאינו מאיר בו בחי' שמש ה' כו', ובפרט כאשר מוצא א\"ע בבחי' חשך והעלם כו' שעי\"ז נעשה השפלות וההכנעה ביותר כו', ועי\"ז הוא הגילוים דאלקות בנפשו בעבודתו כל היום כו'. והנה יש עבודה שבבחי' קירוב וכמו האה' דכמים הפנים אל הפנים המבו' בסש\"ב פמ\"ו שע\"י ההתבוננות בהקירוב דאלקות מתעורר האה' בנפש כו', והיא אה' גדולה כמ\"ש בסש\"ב שם, ומ\"מ ע\"י הריחוק האה' היא ביתר שאת שמתעלה עי\"ז למע' ומדרי' גבוה יותר כו', וכמ\"ש שמאלו תחת לראשי וימינו תחבקני שע\"י בחי' שמאל דוחה בא למדרי' גבוה יותר מע\"י ימין מקרבת כו', ועי\"ז דוקא נעשה האדם בבחינת מהלך כו', שהרי העבודה דנשמה למע' הוא בבחי' הקירוב וכמ\"ש חי ה' אשר עמדתי לפניו שהיא העמידה באהוי\"ר כו', והוא ע\"י הגילוי שמאיר להנשמה למע' כו', שהרי בהנשמה למע' אינו שייך ענין הריחוק כלל שהאלקות מאיר בה בקירוב ובגילוי\nוכן הנשמה היא בתכלית הקירוב לאלקות כו', ומ\"מ היא בבחי' עומדים כו', ודוקא ע\"י ירידתה למטה נעשה בבחי' מהלכים כו', וידוע ההפרש בין עומדים ומהלכים דעומדים הוא הגילוי שבבחי' מדה וגבול בס' והדרגה כו', ומהלכים הוא גילוי בחי' עצמות אוא\"ס שלמע' מבחי' מדה וגבול כו', וזה נעשה ע\"י שמאל דוחה דוקא שע\"י שמדחה א\"ע בבחי' לב נשבר ונדכה עי\"ז מתגלה פנימי' נפשו ועי\"ז דוקא גילוי בחי' פנימי' ועצמות אוא\"ס ב\"ה כו'. וכ\"ז הוא בחי' הצמצום וההעדר שקדום אל ההוי' והגילוי שע\"י ההעדר עי\"ז הוא דוקא הגילוי כו', ולהיות שזהו מלמטלמ\"ע הנה ההעדר הוא בבחי' העלאת מ\"ן, דמלמעלמ\"ט ההעדר הו\"ע הצמצום כו', אבל מלמטלמ\"ע הו\"ע הזיכוך והעלאת מ\"ן, וכמו הרקבת הגרעין וכמו הזורעים בדמעה כו', וכמו\"כ בעבודה הו\"ע ההכנעה והשפלות ולב נשבר כו' כנ\"ל, ועי\"ז נעשה זיכוך הצמצום והסרת ההעלמות וההסתרים כו', ועי\"ז הוא הגילוי יותר כו' וכמשי\"ת. וזהו ג\"כ ענין שיתוף עמו מדה\"ר, דהנה מה שבתחלה עבמ\"ח לברוא במדה\"ד אין הכוונה בבחי' הצמצום לבד שהרי מהצמצום לבד אא\"ל התהוות שהרי כל פעולה היא ע\"י"],[3601331233,"התגלות הפועל לפעול כו' (רק בחי' נקודת הרשימו הוא שנתגלה ע\"י הצמצום והוא בחי' כח הגבול שבא\"ס כו'), אלא הכוונה ג\"כ על בחי' אור המצומצם הנמשך ע\"י הצמצום כו', ומש\"א שיתף עמו מדה\"ר היינו להיות גילוי אור יותר ע\"י העבודה בזיכוך הצמצום כו', והו\"ע ביום עשות הוי' אלקי' שיאיר גילוי ש' הוי' בש' אלקי' כו'.\n<b>ועפ\"ז</b> יובן מ\"ש וכל העם רואים את הקולות כו' וירא העם וינועו שזהו כענין ההעדר קודם להוי', דהנה הכוונה במ\"ת הוא שיהי' גילוי אלקות בנש\"י גילוי אור עצמי כו', ועיקר ענין שתוף עמו מדה\"ר היא במ\"ת וכמא' אוריין תליתאי בירחא תליתאה לעם תליתאה כו', והוא בחי' קו אמצעי דמעלת קו אמצעי הוא שמראשית המשכתו עד סוף סיומו הוא בשוה כו' כנודע, ולכן הי' שעבוד מצרים קודם מ\"ת דבכדי שיהי' גילוי דמ\"ת דאז נעשו נש\"י כמו הוי' חדשה, וכידוע ההפרש בין ההמשכה דמע\"ב וההמשכה דמ\"ת כו', הי' צ\"ל תחלה שעבוד מצרים שהוא ההעדר שקודם להוי' כו', וכן גלות האחרון הוא הקדמה גילוי טעמי תו' שיתגלה לעתיד כו'. וזהו ג\"כ ענין החרדה ע\"י הקולות וברקים כמ\"ש בתו\"א בהבי' דזכור ושמור שהוא לעשות בהם ביטול היש כו', שכ\"ז הו\"ע ההעדר קודם לההוי' כו'. וזהו וכל העם רואים את הקולות כו' וירא העם וינועו שהי' בכוונה להחרידם בבחי' ביטול היש בכדי להיות גילוי אור העצמי במ\"ת כו'."],[3601331234,"<h3>בס\"ד. יום ב' דחה\"ש, בסעודה, העת\"ר</h3>\n<b>על</b> שלשה דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח, דכתי' ואשים דברי בפיך זהו עמוד התו', ובצל ידי כסיתיך עמוד גמ\"ח, לנטוע שמים וליסוד ארץ עמוד העבודה, שזהו הקרבנות שעז\"נ סולם מוצב ארצה וראשו מגיע השמימה כו' כדאי' במד\"ר, וצ\"ל מה\"ע הג' דברים שעליהם קיום העולם כו'. ולהבין זה ילה\"ק משנת\"ל דיום ולילה זה\"ע הצמצום שהי' באוא\"ס וגילוי הקו, שהצמצום קדום אל הגילוי, וע\"ה דעיקר הכוונה הוא הגילוי, מ\"מ קדום הצמצום כי הכוונה בהצמצום הוא הגילוי דוקא, והצמצום הוא באופן כזה שיהי' ע\"י גילוי, והצמצום הוא טפל אל הגילוי רק שקדם אל הגילוי כי אא\"ל גילוי כ\"א ע\"י הצמצום דוקא כו'.\n<b>והנה</b> מה שנתהווה ע\"י הצמצום הוא התהוות הכלים כו', וכידוע דשרש האור הוא מן הקו ושרש הכלים הוא מהצמצום ורשימו כו', שעז\"א ג\"כ כברייתו ש\"ע ברישא חשוכא והדר נהורא ברישא חשוכא היינו בחי' הכלים שמבחי' ש' אלקי', והדר נהורא בחי' האורות שמבחי' ש' הוי' כו', וצ\"ל למה ברישא חשוכא הרי מבו' בע\"ח שער העקודים פ\"א דהתחלת גילוי הויות הכלי הוא בעקודים, ומבו' שם פ\"ב שזהו ע\"י בחי' מטולמ\"ט דהאור, והוא דלהיות דמהתעבות האור"],[3601331235,"נעשה הכלי, וכאשר נמשך ונתגלה האור ואח\"כ עלה ונסתלק למע' הנה העביות שבהאור לא עלה למע' וזה נעשה בבחי' כלי כו', הרי שהי' תחלה התגלות האור ואח\"כ נתהווה הכלי, ואיך אמרו ברישא חשוכא והדר נהורא כו'. אך הענין הוא דהנה ידוע דהרשימו היא דוגמת בחי' כלי, וכידוע דהרשימו היא בחי' כח הגבול שבא\"ס והו\"ע האותי' דגליף גליפו שבאוא\"ס שלפה\"צ כו', ועמ\"ש בזוהר\"ק על מאה\"ז בראשית דט\"ו פי' גליפו מסר לנו כלל בידינו הרב ז\"ל שפי' כלי קבול לקבל בתוכה כל אור שישפיע א\"ס ב\"ה מאז והלאה עכ\"ל, ומפרש מ\"ש גליף גליפו אחה\"צ, ובכתבים מבו' בכ\"מ שזה לפה\"צ, אמנם למדנו מזה דאותי' הרשימו הן בחי' כלים כו', דקוה\"צ הי' האוא\"ס מאיר בגילוי בהאותי' והאותי' לא היו בבחי' מציאות כלל כו', ואחה\"צ שנתעלם האוא\"ס ונשארו האותי' שנעשו בבחי' מציאות כו', וזהו בחי' מקום שנעשה ע\"י הצמצום שהוא בדוגמת כלי כו' כמ\"ש בע\"ח בתחלתו בהג\"ה ונת\"ל (ד\"ה ויהי ביום השמיני), וע\"י שנשארו נקודת הרשימו שהיא כדוגמת כלי עי\"ז נמשך האור כי אא\"ל המשכת אור בלי כלי כו', וכמ\"ש\nאין עוד כלי ויעמוד השמן כו', הרי שבתחלה הי' הוויית הכלי בשרשה דהיינו בחי' הרשימו ועי\"ז הי' גילוי הקו כו'. וגם כללות הענין מה שע\"י הצמצום נמצא האור השייך אל העולמות הוא ע\"י בחי' כח הגבול (שהן אותי' הרשימו) שהי' כלול באוא\"ס שלפה\"צ כו', דהרי ידוע ונת\"ל בכ\"ד דלפה\"צ הי' מאיר בגילוי בחי' פנימי' האור שלמעלה מהעולמות וחיצוני' האור השייך אל העולמות הי' כלול ומעורב בפנימי' האור כו', וע\"י הצמצום שנתעלם האור לגמרי נמצא בחי' חיצוני' האור השייך אל העולמות כו', וכמו אצל המשפיע שמאיר אצלו בגילוי האור שכל כמו שהוא לעצמו ואינו ניכר כלל האור השכל השייך אל המקבל, וע\"י שמעלים אור שכלו בעצמו נעשה ניכר ונבדל חיצוני' אור השכל השייך אל המקבל שבא בבחי' נקודה א' כו', אך זהו דוקא ע\"י כח ההגבלה שנמצא בו גם באור שכלו כמו שהוא לעצמו כו', וכמו שאנ\"ר דמי שאינו מסודר בעצמו בשכלותיו לא ימצא לעולם חיצוני' אור השכל השייך אל המקבל, גם כשיעלים אור שכלו בעצמו לא ימצא השכל השייך להמקבל כו', וגם ההעלם אינו שמתעלם לגמרי, וכנודע\nדבכדי שיהי' הבדלת חיצוני' האור הוא דוקא ע\"י שמעלים אור שכלו בעצמו כאלו לא השכיל כלל, וזה שאינו מוגבל בעצמו אינו יכול להעלים אור שכלו שיתעלם לגמרי כו', והסבה לזה מפני שלעצמו אינו מסודר וא\"ז תפיסת האור בכלי שאין בו כח ההגבלה, ע\"כ לא ימצא חיצוני' האור כו' (וגם לא יוכל להעלים כו'), ובא בהשפעה האור כמו שהוא לעצמו למע' מהמקבל ובא בלתי מסודר כו', ודוקא כאשר הוא מסודר ומוגבל בעצמו אז דוקא ימצא חיצוני' האור השייך אל המקבל כו'. ונמצא דגם בהעלם אצל המשפיע מה שנמצא האור השייך אל המקבל זהו דוקא ע\"י כח ההגבלה שיש באור שכלו גם כמו שהוא לעצמו כו', ולא שהוא בבחי' הגבלה ממש שהרי לעצמו אינו מוגבל בשכלו כמשנת\"ל (ד\"ה וכל העם רואים) רק כעין הגבלה והיינו שהוא מסודר בעצמו, ועי\"ז דוקא נמצא חיצוני' האור השייך אל המקבל, ונמצא בבחי' נקודה מוגבלת כו'. וכמו\"כ יובן מזה הדוגמא למע' דזה שע\"י הצמצום נמצא בחי' חיצוני' האור השייך אל העולמות הוא דוקא ע\"י בחי' כח הגבול הכלול באוא\"ס ב\"ה, ונמצא בבחי' נקודה כללית שזהו בחי' הכלי כו', ונמצא קודם כל גילוי אור הי' תחלה בחי' שרש הכלי ועי\"ז דוקא הי' גילוי האור כו'."],[3601331236,"<b>והנה</b> בס' ההשתל' הרי התגלות האורות הי' תחלה ואח\"כ התהוות הכלים וכמ\"ש בע\"ח בהתהוות הכלים בעקודים כו' כנ\"ל, מ\"מ במח' הכלים קדמו אל האורות וכל עיקר המשכת האור הוא בשביל הכלים, ואם לא הי' בדעת המאציל התהוות הכלים לא הי' ממשיך האור כלל, וע\"כ אע\"פ שבפועל ההתהוות האור קדום אבל במקור ההעלם הכלים קדמו כו'. ועד\"מ במשפיע ומקבל הרי כשעולה ברצון הרב להשפיע שכל לתלמידו הרי בהכרח שיצייר הרב תחלה במחשבתו אופן שכל התלמיד שהוא כלי קבלתו ואופן השגתו שישיג את השכל אחר השפעתו בגילוי, דהיינו איכות אופן ההגשמה שיגשם התלמיד בקבלתו את אור שפע שכל הרב, ואופן הגשמת התלמיד הוא תלוי ברצון הרב באופן ההשפעה שישפיע לו שבאם יהי' בזה אור השכל בגילוי יותר תהי' ההגשמה במיעוט שלא יוכל לגשמו כ\"כ ואם ישפיע לו בבחי' מיעוט האור תהי' ההגשמה יותר כו', וע\"פ אותו האופן שהוא רוצה הגשמת המקבל כן יומשך אח\"כ אור שפע ההשגה בגילוי כדי שיהי' בפו\"מ הגשמת כלי המקבל כו'. ועד\"ז יובן בענין אורות וכלים דענין הכלי הוא הגשמת האור\nוישותו שבזה נתפס ומתלבש האור, ה\"ז קדום במח' כו', ולפי אופן הכוונה בהתהוות הכלי היינו באופן קבלת האור וגילויו בהמקבל דהיינו הכלי באופן כזה הוא השפעת האור והגילוי מאוא\"ס המאציל כו'. ונמצא דבמקור ושרש ההתהוות האור והכלי הכלי קדום, ובפועל והגילוי האור קדום כו', וזהו ע\"ד שמצינו בברי' שו\"א דכתי' אלה תולדות השוה\"א כו' ואח\"כ כתי' ביום עשות ה' אלקים ארץ ושמים, ויש בזה ב' דעות במד\"ר ב\"ש וב\"ה אם שמים קדמו או ארץ קדמה ושניהם אמת, דבס' ההשתל' שמים קדמו לארץ והשמים משפיעים לארץ וכמ\"ש אני אענה את השמים והם יענו את הארץ כו', אבל במח' ארץ קדמה דסוף מעשה עלה במח' תחלה כו', וכמ\"ש אנכי עשיתי ארץ דעיקר הכוונה היא הארץ דוקא כו', והיינו דבבחי' אנכי בחי' הכתר ארץ קדמה כו', וכתי' ה' בחכ' יסד ארץ כונן שמים בתבונה כו' (וכן הי' במים וארץ דמתחלה היו המים מקיפים את הארץ ואח\"כ גזר אומר יקוו המים כו' ותראה היבשה כו'), והיינו שזהו תכלית הכוונה והיא קדמה במח' כו'. ולכן כח ההתהוות הוא בארץ דוקא וכמו הצמיחה שהיא בארץ דוקא\nכו', דבשמים לא יש כח הצמיחה כ\"א בארץ דוקא כו', וע\"ה שזהו ע\"י השפעת השמים וכמו כאשר ירד הגשם והשלג מן השמים כו' והולידה והצמיחה כו', וכן משארז\"ל אין לך עשב מלמטה שאין לו מזל מלמע' המכה בו ואומר לו גדל שזהו המזלות שברקיע שע\"י הוא הצמיחה וכמו ממגד תבואות שמש וממגד כו', וכמ\"ש וכל שיח השדה טרם יהי' כו' כי לא המטיר כו', מ\"מ ההתהוות הוא מן הארץ דוקא היינו מכח הצומח שבארץ שמזה הוא התהוות גוף העשב והתבואה וכה\"ג, והמזל המכה בו ואומר לו גדל זהו לאחר שכבר צמח העשב ועושה בו רק ההגדלה מקטנות לגדלות וכמ\"ש באגה\"ק סי' כ', ועל מ\"ש כי לא המטיר פרש\"י שעמדו על פתח הקרקע וע\"י המטר צמחו ונתגלו כו', והוא רק ההתפשטות הנעשה ע\"י החיות כו', אבל עצם העשב מתהווה מכח הצומח כו' (וע' משנת\"ל ד\"ה אנכי הא'). והנה במשל דצמיחה מובן דהתהוות עצם הדבר הוא קודם אל החיות כו', שהרי העשב מתהווה תחלה ואח\"כ הוא השפעת החיות שהוא מהמזל כו', והיינו שההתהוות שמהארץ עצמה הוא קדום לההשפעה שמהשמים כו' (ומבו' במ\"א"],[3601331237,"דהארץ נשלמה ביום ראשון ושמים נגמרו ביום שני), וידוע שיש דעה שבנין החומר קדום לבנין הצורה וכמו בצמיחה כנ\"ל. והנה בהתהוות הולד ממשארז\"ל סנהדרין דצ\"א ע\"ב דהנשמה באה משעת פקידה שנא' ופקודתך שמרה רוחי הרי שהנפש והגוף שהן החומר והצורה באים כא' כו', אך ממ\"ש בע\"ח שי\"ח פ\"ב נר' שזהו רק מניצוצי האור שנשארו בשברי הכלים, והוא בכלל בנין החומר עדיין כו', גם לפמ\"ש הטבעים דהתחלת יצירת הולד הוא מהלב שהוא יסוד הגוף ואח\"כ הוא יצירת המוח כו', ה\"ז ג\"כ שקדום בנין החומר כו', דהלב הוא שבו הדם שזהו חומר הגוף ומשכן הנשמה היא במוח כו' (וכמו בבריאת האדם שבתחלה צבר עפרו ועשאו גולם ואח\"כ נתן בו נשמה ולא כמו כל הבע\"ח שבקומתן נבראו גוף ונפש כא' כו', וכתי' ויפח באפיו נ\"ח שהנשמה באה תחלה במוח (דרך החוטם שהוא שער המוחין כו') ואח\"כ ללב כו') (ובע\"ח שי\"ט פ\"ו נ' שהתחלת ההתהוות הוא מהכבד כו', והרי הכבד הוא החומר כו'). ובענין האורות וכלים למע' הנה בעקודים יצאו האורות תחלה ואח\"כ נעשו הכלים, ובנקודים יצאו תחלה הכלים ואח\"כ יצאו\nהאורות כו', וכמ\"ש בע\"ח שער הנקודים פ\"ד ואח\"כ בתקון האורות והכלים כ' בע\"ח שי\"ח הנ\"ל שתיקון האורות הוא בז' חדשים ותיקון הניצוצות בט\"ח ותיקון הכלים ביב\"ח, ונר' שם דתיקון הכלים הוא קודם לתיקון האורות, ובמב\"ש ש\"ה ח\"א פ\"י כ' מפורש שתיקון הכלים התחיל תחלה שצריך זמן יותר כו'. והנר' לו' בזה דכפי ס' ההשתל' מלמעלמ\"ט התהוות האורות קודם להתהוות הכלים, והוא כהדיעה שבנין הצורה קדום לבנין החומר כו' (וכן יש דעה שהתחלת היצירה הוא מן המוח כו'), וע\"כ בעקודים שזהו כפי ס' ההשתל' נתגלו האורות קודם ואח\"כ נתהוו הכלים כו', ובתהו שיצאו הכלים תחלה זהו שלא בהדרגה כו', והיינו מפני שהיו כלים קטנים ולא הי' להם קישור וחבור עם האור כו', ע\"כ יצאו הכלים תחלה כו' (דהקדמת יציאת האור ושמהאור יהי' התהוות הכלי זהו בכדי שתהי' הכלי לפי אופן האור שתקבל את האור כו', ובתהו לא הי' באופן כזה ע\"כ יצאו הכלים תחלה ולפי אופן הכלים הי' האור, וכמ\"ש במ\"א דזה שהאור הי' אור כללי הוא מפני שהכלים היו כלים קטנים בבחי' עיגולים כו'), ובתיקון הי'\nתיקון הכלים תחלה לפי שזהו בדרך מלמטלמ\"ע שצ\"ל תחלה בירור ותיקון הכלים והיינו להיות בבחי' כלי לאור כו' (כי הכלים דתהו לא היו בבחי' כלים כלל והתיקון הוא שיהיו בבחי' כלים כו'), וענין תיקון הכלים הוא הביטול שלהם להיות מיש אין שעי\"ז יהיו בבחי' כלים כו', ותיקון האורות הוא ג\"כ בחי' הביטול אבל הוא להיות מאין ליש כו' וכמשנת\"ל באורך, וי\"ל שזהו בחי' תיקון הכלים והאורות שנעשה בבחי' העיבור להיות בהם בחי' הביטול שעי\"ז יהי' קישור וחבור האורות והכלים כו' (ועמ\"ש בע\"ח שם דענין העיבור הוא קישור וחבור כו').\n<b>והנה</b> ידוע דעיקר בנין הולד (והיינו עיקר מציאותו) הוא מטפת האם, וטפת האב הוא המברר את טפת האם להיות נקפה ונעשה ממנו ולד כו' (וכמו כח ההתהוות שבארץ דוקא כנ\"ל כמו\"כ כח התהוות הולד הוא בהנוק' דוקא, וע\"ה שהמוליד הוא הדכד וכמ\"ש כאשר כו' והולידה כו' שבו הוא כח ההולדה (ולכן הוא חטא גדול בהשחתת הזרע ר\"ל וכמו הורג נפש ר\"ל), זהו כח עליון שיש בו למע' מעצם מהותו כו', והוא משרש ומקור הנוק' דוקא והו\"ע בעטרה שעטרה לו כו' וכמ\"ש במ\"א)"],[3601331238,"(ובפרטי' האם מזריע אודם שממנו עור ובשר כו', והאב מזריע לובן שממנו עצמות ומוח כו', ובד\"כ מטיפת האם הוא התהוות המציאות ומטפת האב הוא הרוחני וכמו האב זוכה לבן בנוי ובכח כו' ובחכ' כו'), וידוע דטפת המ\"ן הוא שבא מהבירורי' דוקא דהיינו בחי' הביטול כו' וכמ\"ש בלק\"ת בהבי' דאז ישיר. וזהו שבעיבור בנין החומר קדום והוא בנין הכלים שהו\"ע ביטול היש שזהו מטפת מ\"ן מצ\"ע והוא קדום כו', ובעבודה הו\"ע מצות מעשי' בבחי' ביטול כו', וכמ\"ש בתו\"א ד\"ה ויחפרו עבדי יצחק ענין הביטול שבמצות להתבונן בתחלה איך שהוא מאד רחוק כו', וישבור לבו בהתבוננות זו כו' יעו\"ש (ומש\"ש כשהי' לו בתחלה כו' בחי' ונהר יוצא כו' י\"ל שזהו טפת מ\"ד המברר כו'), והו\"ע כלי ריקן המבו' בד\"ה לא תהי' משכלה להיות לב נשבר ונדכה כו' דכלי ריקן מחזיק שעי\"ז נעשה כלי לאלקו' כו'. אמנם בלידה והתגלות בא התגלות האור קודם ומהתעבות האור נעשה הכלי ונעשית לפי אופן האור כו', ועיקר תיקון הכלים הוא בהתגלות שלהם, כי התיקון דבחי' עיבור הוא רק שתהי' בבחי' כלי אל האור, והיינו\nשיהי' קישור וחבור הכלי עם האור כו', אבל עיקר התיקון של הכלים הוא שיהי' בהם התכללות דבחי' החסד יהי' כלול גם מגבו' כו', והיינו שלא יהי' חסד פשוט בבחי' נקודה בלבד כ\"א יהי' בזה בחי' הגבו' ג\"כ וכן שארי המדות כו', והוא בחי' רוחב הכלי כו' שעי\"ז יהי' התכללות המדות כו', דתיקון זה הוא ע\"י האור כו', והן בחי' המוחין שעושין ההתכללות, וכמו באשר משפטו פעלו כו' שזהו ע\"י מוחין דגדלות כו' (ועיקר התיקון הוא ע\"י ש' מ\"ה דחכ' כו' וכמשנת\"ל באורך). ובעבודה הוא להיות אהוי\"ר בהתגלות שזהו ע\"י השגה והתבוננות אלקי כו' ולהיות התכללות אהוי\"ר כי אה' לבד אינה עבודה תמה וצ\"ל ג\"כ יראה וכמו וגילו ברעדה במקום גילה שם תהא רעדה כו', וכן יראה תהי' כלולה באה' וכמו וכל הלבבות ייראוך וכל קרב וכליות יזמרו כו' וכמ\"ש בלק\"ת ד\"ה וידעת דרוה\"ב, וכן במצות בבחי' תיקון ועשיית הכלים להמשיך בהם וע\"י גילוי האור, וכמו רמ\"ח פקודין רמ\"ח אברין דמלכא שהן אברין וכלים שע\"י נמשך גילוי אלקו' שזהו ע\"י קיום המצות באהוי\"ר כו'. ובמדרי' זו בנין האורות\nקדום לבנין הכלים שע\"י האור עי\"ז נבנה הכלי כו', אך גילוי האור הוא ע\"י הכלי דוקא כי בלא כלי אא\"ל גילוי אור כו', והאור בשביל הכלי כי הכוונה הוא בהכלי דוקא דבמח' הכלי קדמה אל האור כו', והיינו שיהי' הגילוי בכלים דוקא כו', והאור הוא בשביל הכלי כו', ולכן כלים ממשיכים אור, וכידוע במשל האברים שממשיכים חיות דכשמתקנים האבר שראוי לקבל חיות הנפש א\"צ להמשיך החיות רק נמשך ממילא כי האבר ממשיך חיות כו', וכן הכלים למעלה ממשיכים את האור כו', ולכאו' מאחר שהכלי למטה מן האור איך הוא ממשיך את האור, אך זהו מפני שבמח' הכלי קדמה והיא תכלית הכוונה ע\"כ היא ממשיך את האור כו'.\n<b>אמנם</b> הכוונה בהכלי הוא שתהי' בבחי' ביטול דזה שהכלים מקבלים את האור וממשיכים אותו זהו דוקא ע\"י ביטול הכלים כו', שהרי תכלית הכוונה הוא שיהי' גילוי האור רק שיהי' הגילוי בכלים כו', ואם הכלי היא בבחי' יש ומציאות הרי אינה כלי לאור ואדרבה מעלמת על האור וה\"ז היפך הכוונה לגמרי כו' (או כמו שהי' בתהו שלא היו כלים אל האור והאור נסתלק מהם כמו האש הקופץ מהפתילה כו' וכמשנת\"ל), רק צ\"ל ביטול הכלי כו', וזהו מה שהכלי קדום שעלה במח' תחלה הוא"],[3601331239,"דוקא שתהי' כלי לקבל והיינו שתהי' בבחי' ביטול, ושיהי' עוד הביטול באופן כזה שיומשך אור שלמע' מבחי' התלבשות בכלים כו', ועי\"ז הוא עיקר התיקון שע\"י האור. כי הנה בהתגלות האורות והכלים ג\"כ תיקון הכלים קדום לתיקון האורות (והיינו שקודם הוא תיקון הכלים ע\"י האורות המתלבשים בתוכם ואח\"כ הוא תיקון הכלים ע\"י האור בעצם כמו שהוא למע' מהתלבשות כו'), דתיקון הכלים הו\"ע ההתכללות הנ\"ל דחו\"ג כו', ותיקון האורות הוא להיות ההתכללות מבלי אשר ימצא ראש וסוף כו', דהתכללות הא' הוא שסובלים זא\"ז, והתכללות הב' הוא שמקבלים זמ\"ז ומשלימים זא\"ז כו' וכמשנת\"ל באורך, וזהו תיקון האורות היינו התיקון מבחי' האור שלמע' מהכלים כו', וכמ\"ש בהבי' דוהניף שזהו מבחי' עקודים והוא בחי' אנת הוא שלימותא דכולהו כו', וזהו ע\"י ההתכללות תחלה בהכלים בהתכללות הא' שזהו מבחי' האור המתלבש בכלים כו', ועי\"ז הוא ההתכללות מעצמות האור שלמע' מהכלים כו' וכמ\"ש בהבי' דהחלצו. וזהו שכל העבודה למטה הוא בבירור ותיקון הישות דוקא שהו\"ע תיקון הכלים, וכמ\"ש כי לי בנ\"י\nעבדים דענין העבודה הוא בבירור וזיכוך הישות דוקא, והוא הבירור דנה\"ב כו', והבירור הוא ע\"י כחות דנה\"א שבבחי' התלבשות בנה\"ב וכמשנת\"ל בכ\"ד, ועי\"ז נמשך אור שלמע' מבחי' התלבשות כו', וכמו בעבודה דשבת שהיא עבודת הנשמה מצ\"ע להתענג על ה' כו', והוא שכר עבודתה בששת ימי החול כו', והעבודה דשבת הוא שגם הכחות הטבעי' מתעלים באור וגילוי זה כו', וכמו באכילה דשבת שהתענוג הגשמי הוא תענוג אלקי כו', דהתענוג דתפלה הוא עונג הנשמה עצמה ותענוג דסעודת שבת הוא עונג הנשמה והגוף כו', והכל הוא עונג אלקי כו', וכ\"ה למעלה דבשבת הכלים דברי' עולים באצי' ומאיר בהם אור האצי' שז\"ע ביום השביעי נתעלה וישב על כסא קדשו כו' וכמ\"ש במ\"א כו', והרי נת\"ל (ד\"ה אדם כי יהי') ריחוק הערך דאצי' מבי\"ע כו', ובשבת מאיר אור האצי' בכלים דבי\"ע כו', והוא ע\"י העבודה דימי החול בבירור וזיכוך הכלים שעי\"ז מאיר בהם אור עצמי שלמע' הרבה מערך האור המתלבש כו'. וזהו ויהי ערב ויהי בקר דברישא חשוכא והדר נהורא בחי' אור וכלי שהכלי קדמה במח' כו', והכוונה הוא שיהי'\nגילוי האור רק שיהי' בבחי' כלי כו' (וזהו ג\"כ מה שהשלמות הוא דוקא בהתחברות האור והכלים שהרי כלי בלא אור ודאי היא חסרה מאור וגילוי כו', אך גם האור בלי כלי ה\"ה ג\"כ חסר השלמות דמאחר שהכלי קדמה במח' ובשבילה הוא הגילוי הרי כוונת הכלי כלול הוא בהגילוי וא\"כ בלא כלי לא נשלמה הכוונה כו', ובפרט שבלא כלי אינו נמשך האור א\"כ ה\"ה חסר את האור המתפשט בהכלי כו', וע\"ה שזהו חיצוני' האור כו' מ\"מ ה\"ה חסר אור וזיו הזה כו', רק בקישור וחבור דאורות וכלים יחד בזה הוא דוקא השלמות כו', דבזה שהאור מחדש תמיד את הגילוי בהכלים שהוא אור וחיות הכלים זהו דוקא שלימות האור כו', ושלמות הכלי הוא האור כו', וע\"כ בהתחברם יחד עי\"ז הוא דוקא השלמות כו'), ופנימי' הכוונה הוא שיהי' גילוי אור שלמע' מהכלי וג\"ז יאיר בהכלי כו', והיינו ע\"י זיכוך הכלי שמאיר בחי' האור שלמע' בעצם מהכלי' שיאיר ג\"ז בכלים כו'.\n<b>וזהו</b> שארז\"ל על שלשה דברים העולם עומד על התו' ועל עבודה כו', דעבודה הוא עבודת הקרבנות שהוא הקרבת הבהמה ע\"ג המזבח שנכללת באש"],[3601331240,"שלמע' כו', ובעבודה הו\"ע התפלה שהוא הקרבת הנה\"ב כו', וכתי' ולעבדו בכל לבבכם איזה היא עבודה שבלב זו תפלה ונת\"ל דלב הוא עצם מהות החומר כו' ותפלה היא עבודה שבלב בירור וזיכוך החומר כו' ועי\"ז הוא ההמשכה ע\"י התו', דתו' אור הוא בחי' אור שלמע' מכלים כו' וכמשנת\"ל (ד\"ה נ\"ח מצוה להניחה) וכמשי\"ת בעזה\"י, והוא ע\"י עבודה בתפלה בזיכוך החומר, ולמע' נעשה עי\"ז תיקון הכלים כו', ועי\"ז נמשך גילוי אור שלמע' מבחי' הכלים כו', וע\"י הכלים מאיר גילוי האור כמו שהוא בעצם כו'."],[3601331241,"<h3>בס\"ד. ש\"פ נשא, העת\"ר</h3>\n<b>נשא</b> את ראש בני גרשון גם הם כו', וצ\"ל למה נא' בבני גרשון גם הם דמשמע מזה דעיקר ענין נשיאת ראש הוא בבני קהת ובני גרשון נשא גם הם, וצ\"ל מה\"ע נשיאת ראש שהעיקר זהו בבני קהת ובבני גרשון נא' ג\"כ נשיאת ראש כו'. גם מ\"ש גבי בני גרשון ע\"פ אהרן ובניו תהי' כל עבודת בני הגרשוני ולא נא' כן גבי בני קהת ומררי. ובמד\"ר אי' לא שהיו פחותים מבני קהת אלא משום כבוד התו' הקדים בני קהת כו', וצ\"ל מה\"ע כבוד התו' דמשו\"ז עיקר נשיאת ראש הוא בבני קהת דוקא כו'. ולהבין זה ילה\"ק משנת\"ל דיום ולילה בשרשן הו\"ע הצמצום הראשון וגילוי הקו, דהצמצום הוא בשביל והיינו שבהצמצום כלול כוונת הגילוי, וכמו\"כ בהגילוי כלול כוונת הצמצום, דעיקר הכוונה הוא הגילוי ואא\"ל הגילוי כ\"א ע\"י הצמצום דוקא כו', ובהשתל' הו\"ע האורות והכלים שהכלים עלו במח' תחלה ואינו נמשך האור רק כשיש כלים, כי הכוונה היא להיות גילוי בהכלים דוקא, אך בהכלי הכוונה שתהי' בבחי' ביטול שעי\"ז היא כלי אל האור ועי\"ז מאיר בה האור עצמי ושיהי' בבחי' גילוי ע\"י הכלים כו'.\n<b>והנה</b> יום ולילה בעבודה הוא בחי' רצו\"ש הסתלקות והתפשטות שהוא ג\"כ ענין חשך ואור העלם וגילוי כו', וזהו בין בהכלים ובין בהאורות שהן בבחי' רצו\"ש, אך עיקר רצו\"ש הוא בהאור וע\"י האור הוא הרצו\"ש בהכלי כו', וכמו הילוך הדם באדם שהוא בבחי' הסתלקו' והתפשטות שז\"ע דפיקו דלבא שדופק תמיד בב' דפיקות שהוא כיווץ והתפשטות כו', דלבא פליג לכל שייפין וכיווץ הלב הוא הסתלקות הדם מן הלב וההתפשטות הוא שהדם חוזר ונכנס ללב כו' (והוא בדוגמא למע' בחי' מטולמ\"ט מלמעלמ\"ט כו', כמו\"כ סילוק הדם מן הלב הוא המשכת הדם אל האברים וכשנכנס אל הלב הלב מתפשט כו'), וגם יש להיפך שכשהדם נכנס ללב נסגר הלב וזהו הכיווץ מה שנסגר כו', ואח\"כ נפתח ונתפשט הדם ממנו בהאברים כו' (שזהו שבתחלה ההעלם ואח\"כ הגילוי כו'), וע\"י הסגירה מה שהדם נסגר בלב עי\"ז הוא דוקא ההתפשטות כו', דהילוך הדם שהולך במרוצה ובכח ובחיות גדול להחיות כל האברים זהו דוקא ע\"י ההעלם והכיווץ כו', שאם"],[3601331242,"הי' רק בבחי' התפשטות לבד לא הי' בו כח ועוז כ\"כ בהתפשטות שלו, כ\"א דוקא ע\"י הסגירה וההעלם מתחדש כחו ומתפשט בכח ועוז בכל האברים להחיותם כו'. וסבת ההסתלקות וההתפשטות שבדם הוא מהרוח חיים שבלב, וכידוע שבלב מתחבר החיות עם הדם (שזהו כללו' התחברות הנפש עם הגוף שהוא בלב דוקא כו', דמשכן הנשמה הוא במוח שבראש, ושם הוא בבחי' חיות פשוט עדיין למע' מבחי' חיות להחיות כו', והראי' שהרי הריח כמו ריח הבושם שמגיע אל המוח (דמשו\"ז הוא דרך החוטם שהוא שער המוח כו' והפה הוא שער הלב כו' וכמ\"ש במ\"א), הרי אמרו ע\"ז דבר שהנשמה נהנה ממנו ולא הגוף (ברכות דמ\"ח ע\"ב), והיינו שזהו בהנשמה שבמוח שלמע' עדיין מלהחיות הגוף כו', והכבד הוא הדם שזהו כמו הגוף מצ\"ע בלי חיות הנפש כו', וחבור הנפש עם הגוף הוא בלב כו', ולמע' הוא בחי' בינה ליבא שבבינה הוא התחברות האורות והכלים כו', ולכן הש' דבינה הוא הוי' בניקוד אלקי', דבחכ' הוא ש' הוי' שזהו בחי' האור כמו שהוא למע' מכלים, ובז\"א הן שארי השמות ש' אל בחסד אלקי' בגבו' כו', שהן בהכלים, ובבינה\nהוא ג\"כ ש' הוי' רק בניקוד אלקים דהיינו התחברות האור והכלי כו' כנודע, וכמו\"כ בחי' המל' נק' לב כמו צור לבבי כו', וכמו לבבתיני אחותי כלה כו', דמל' היא שרש ומקור בי\"ע שבאצי', והאור והחיות הוא מבחי' ז\"א דאצי' דז\"א רובו חסדים שהוא בחי' חיות ואור כו', דהרי מל' עיקרה גבורות שזהו כמו הדם שאין לו חיות מצ\"ע כו', ועיקר החיות הוא מבחי' חסדים דז\"א דאצי' כו', ובבחי' מל' הוא שמתחבר האור והחיות דאצי' עם שרש ומקור דבי\"ע כו', ונמשך החיות מבחי' מל' בעולמות בי\"ע כו'), דחלל הימני שבלב הוא מלא רוח חיים (שנמשך מן הנשמה שבמוח להיות בבחי' חיות להחיות כו'), וחלל השמאלי הוא מלא דם (והוא הדם שכבר נתברר ונזדכך בכבד וראוי לקבל בתוכו חיות הנפש כו', שזהו עליית הנבראים דבי\"ע בבחי' רצוא שלהם בבחי' מל' ועי\"ז נמשך להם חיות חדש כו' כמשי\"ת), ובלב הוא שמתחברים שמתלבש החיות בהדם להחיות ע\"י כל הגוף כו'. ולהיות שהחיות הוא בבחי' רצו\"ש שאינו נמשך בבחי' התפשטות לבד כ\"א בבחי' הסתלקות והתפשטות שעולה ויורד תמיד (וכמשי\"ת סבת הדבר),\nוכמו אור הנר שאינו בהפתילה בבחי' התפשטות לבד רק עולה ויורד כו', וכמו\"כ הוא בנר ה' נשמת אדם שהוא תמיד בבחי' עלי' וירידה בחי' הסתלקות והתפשטות (שהוא העלם וגילוי כו'), ועש\"ז נק' נשמה שהוא ל' אשום ואשאף יחד שההבל נכנס ויוצא, ולהיות שהנשמה הוא מקור כל הנשימות עש\"ז נק' נשמה שהיא בבחי' רצו\"ש כו', ועי\"ז הוא ג\"כ הרצו\"ש שבהדם כו', וכמו שבהדם הרי ההתפשטות הוא דוקא ע\"י ההסתלקות הקודמת (וכנ\"ל שעי\"ז הוא דוקא כח ועוז ההתפשטות כו'), כמו\"כ ברוח חיים דנשמה שהשוב הוא דוקא ע\"י הרצוא כו', דעיקר הרצו\"ש הוא בהחיות ועי\"ז הוא ההסתלקות וההתפשטות בהדם כו'. אך מן ההסתלקות וההתפשטות שבהדם אנו יודעים בהחיות דכשם שסבת התפשטות הדם בכח ועוז הוא ע\"י ההסתלקו' דוקא שעי\"ז מתחדש מהרוח חיים שבלב כו', כמו\"כ סבת השוב בהחיות הוא ע\"י הרצוא דוקא וכמשי\"ת, ונמצא דאופן החיות הוא בבחי' רצו\"ש דוקא, וע\"י הרצוא הוא השוב כו'. וכמו\"כ הוא בחיות אלקי דנשמה מאור האלקי שהוא ג\"כ ברצו\"ש וכמ\"ש כל הנשמה תהלל י\"ה תהלל הוא מל' בהילו נרו שהוא בחי' גילוי אור האלקי שזהו ע\"י בחי' נשמה שהוא ענין רצו\"ש"],[3601331243,"והוא בחי' חו\"ג שבנשמה, שהגבו' הוא בבחי' עלי' והסתלקות והשוב הוא בחי' חסד שהוא הגילוי כו'.\n<b>וענין</b> הרצוא הוא כמא' אם רץ לבך שזהו מה שהלב רץ במרוצה שהוא מגודל עוצם התשוקה הגדולה ונפלאה שבלב בבחי' כליון כו', וכמו בגשמי' בדבר שהלב משתוקק הרי תכלה לבו לזה בבחי' כליון כו', וזה בא מיסוד האש שבלב שהוא חום הטבעי שבדם שנבער כרשפי אש שלהבת ממש, והוא הצמאון שבלב בתשוקה מורגשת ביותר כו', וכ\"ה ממש ביסוד האש האלקי שבלב (שהוא בדם הרוחני שאהי' בריבוע בגימט' דם והוא בחי' בינה שמזה בא הרצוא וכמשי\"ת בסמוך, וכידוע דחכ' הוא בחי' שוב ובינה רצוא כו'), והוא הצמאון והתשוקה ברשפי אש התלהבות אלקי ליכלל ולידבק באלקי' חיים כו', וכמ\"ש צמאה לך נפשי כו' נפשי אויתיך כו', ונק' שלהבת י\"ה וכמו רשפי' רשפי אש שלהבת י\"ה כו', והגם שמלובש בחום ואש הטבעי שביסוד האש הטבעי שבלב כו', וכאומרו צמאה לך נפשי כמה לך בשרי כו' וכמו לבי ובשרי ירננו כו' (להיות שזהו בהתפעלות והתלהבות מורגשת כו', שכ\"ה ברשפי אש שבא מבחי' הבינה שהו\"ע השגה והתבוננות שההתלהבות הוא במורגש כו' (ועמשנת\"ל בענין רוח רעש ואש כו'), ומפני שהיא\nבמורגש בנפש ה\"ה במורגש גם בחום הטבעי שבלב, שהחום הטבעי מתפעל ומתלהב ע\"י ההתבוננות כו'), מ\"מ זה בא מהנשמה האלקי' שמתלהבת ומתלהטת באש האלקי לחשוק ולכסוף בכליון לה' אחד כו', וכמ\"ש נכספה וגם כלתה נפשי דוקא וכן צמאה לך נפשי כו' (והוא התחברות הנשמה האלקי' עם הנפש הטבעי כו' (וכמו שע\"י הבינה הוא התחברות האור והכלי כו' כנ\"ל), והוא שגם הנה\"ט עולה בהתפעלות ובהתלהבות זאת כו', ולכן בירור ותיקון הנה\"ב הוא ע\"י העבודה באהוי\"ר שבאה ע\"י ההתבוננות דוקא כו'). והרצוא והצמאון בא ע\"י ההשגה דכח הבינה דנה\"א וכמא' בינה ליבא ובה הלב מבין כו', דכשמתבונן איך שכל חיות העולמות הוא מבחי' מל' לבד דמלך שמו נק' עליהם דבחי' מל' הוא בחי' ש' והארה לבד שאינו בערך העצמות כו', וכתי' כי נשגב שמו לבדו שגם בחי' השם הוא נשגב ומרומם מן העולמות ורק בחי' מקיף מלמע' כו'. וכמו עד\"מ במלכותא דארעא הרי רק ש' המלך הוא על המדינה לא עצמו' המלך כו' (דעצמותו הוא מרומם בעצם לא בבחי' התנשאות על עם רק שמו לבד הוא שמתנשא כו'), וג\"ז הוא בבחי'\nרוממות והתנשאות כו'. וכמו\"כ הוא למע' דבחי' שמו לבד הוא שבבחי' רוממו' והתנשאו' על עולמות בי\"ע כו', ומה שנמשך בהם בפנימיותם להחיותם הוא רק הארה לבד שעז\"א הודו על ארץ ושמים בחי' הוד וזיו לבד כו', וכמו\"כ הוא גם בעולמות עליוני' כמו בעולם אצי' ולמע' מאצי' שהכל הוא רק הארה לבד וכולא קכל\"ח כו', וגם עז\"א כי נשגב שמו כו', להיות דכללות ההשתל' הוא רק מבחי' מל' דא\"ס והוא בחי' מח' ורצון דאנא אמלוך כו' (והוא מה שנעשה ע\"י ההעלאת מ\"ן מיני' ובי' כו', וכמשנת\"ל ד\"ה אחרי דאוא\"ס מצ\"ע אינו בגדר רצון כלל כו'), ובחי' מל' דא\"ס כמו שהוא בעצם ה\"ז למע' עדיין גם מבחי' התנשאו' על העולמות רק הארה לבד כו', וזהו כי נשגב שמו לבדו דמה שהוא נשגב זהו רק שמו לבד כו', והודו על או\"ש כו' והוא בחי' גילוי הקו שנמשך בעולמות בפנימיותם הוא רק הוד וזיו בלבד כו', או יתפרש כי נשגב שמו על בחי' מל' דא\"ס כמו שהוא למע' מהצמצום בחי' שמו הגדול כו', ומ\"ש הודו על או\"ש הוא בחי' המל' כמו שהיא בבחי' התנשאו' על"],[3601331244,"העולמות שזהו על או\"ש בבחי' מקיף עליהם כו', וכמ\"ש מלכותך מכ\"ע דמלכותך הוא בחי' מל' דא\"ס כמו שהוא למע' מבחי' צמצום ולמע' מבחי' התפשטות והתנשאות על עם כו', ומכ\"ע הוא התפשטות המלוכה שזהו ע\"י הצמצום שמתצמצם בעצמו להיות בבחי' מלך כו', וכמ\"ש ה' מלך גאות לבש שנתלבש בצמצום גדול בבחי' גיאות דמלוכה זו להיות בבחי' מלך לעולמות המסתעפים מבחי' הקו אחה\"צ כו'. וכללות ההתבוננות הזאת הוא איך שכללות שרש ומקור העולמות הוא בחי' מל' לבד, שגם בשרשו ומקורו הוא בחי' שם לבד וכ\"ש כמו שהוא בבחי' התנשאות על העולמות כו' (ובאמת משנת\"ל בחי' מל' דא\"ס שהוא הרצון דאנא אמלוך א\"ז עדיין בחי' התנשאו' עצמי כו'), וכל הגילוים בעולמות שיש ריבוי מדרי' עד אין שיעור מרוכ\"ד עד סוכ\"ד ה\"ז רק הארה לבד מבחי' מל' וכמא' משובח ומפואר עדי עד בבחי' א\"ס והכל הוא רק שמו הגדול כו'. וע\"י אריכות ההתבוננות בזה יתלהב לבו ברשפי אש התשוקה והצמאון ליכלל בעצמות אוא\"ס ב\"ה, והיינו שלא ימצא שום רצון וחפץ ואינו מוצא שום חיות לנפשו בכל הגילוים כו', ולא מבעי\nשאין לו שום חיות ועונג למטה בחיות הגשמי כו', אלא שגם בהגילוים שבעולם בהאור והחיות האלקי וגם בהאור שבעולמות העליונים כו' אין לו בזה שום חיות ועונג כלל כו', כ\"א חפצו ורצונו להכלל בעצמות אוא\"ס כו', וכמ\"ש מי לי בשמים ועמך לא חפצתי דכל מה שעמך לא חפצתי כו', רק צמאה לך נפשי לך דוקא כו'.\n<b>ואחר</b> הרצוא הוא בבחי' שוב וכמא' אם רץ לבך שוב לאחד או שוב למקום כו', והוא שע\"י הרצוא מאיר גילוי אור בנפשו ועי\"ז נשקט מבחי' הרשפי אש והצמאון כו', וז\"ע והיו הדברים האלה שאחר המס\"נ דה' אחד דמס\"נ הוא מסירת הרצון, כי נפש הוא רצון כמו אין נפשי כו', והיינו תגבורת הרצון והתשוקה לה' אחד עד שיתפשט רצונו מכל דבר כו' כנ\"ל, ואו' אח\"כ והיו הדברים האלה בד\"ת הכתוב מדבר שע\"י התו' נמשך האור האלקי בנפשו כו', ובפרטי' בתפלה גופא הוא ההמשכה בשמו\"ע שאו' ברוך אתה הוי' שהיא ההמשכה והגילוי כו', ועי\"ז נשקט ונתקרר מהרצוא מפני הגילוי שמאיר כו', והעיקר הוא מפני שהגילוי אור עליון עושה ביטול בנפשו להיות בחי' היראה והשפלות היפוך בחי' האה' והרצוא כו', ואומר לנפשו מי אנכי לגשת אל הקדש פנימה לעלות במעלות ומדרי' רוממו' הא\"ס כו' רק להיות למטה לקיים רצונו ית' בתומ\"צ כו'. אך מה שמכבה את האה' זהו רק לפי שעה כי מיד חוזר ומתעורר באה' בבחי' רצוא כו', ואדרבה עי\"ז דוקא הוא עולה בעילוי המדרי' יותר בקרבת אלקים כו', כי ע\"י\nהגילוי אלקו' בהשוב שנעשה עי\"ז בקירוב יותר ה\"ז גופא גורם בחי' הרצוא יותר כו', ובפרט שעי\"ז מתעלה בהשגתו יותר ובהרגש האלקי ויבין יותר בבחי' רוממו' הא\"ס ואיך שכולא קמי' כלא כו', ועי\"ז יתגבר הרצוא ביותר כו', וכ\"ה תמיד ברצו\"ש כו'. וכמו שהוא בנשמות למטה שהן בבחי' רצו\"ש כמו\"כ הוא בחיות המרכבה שהן תמיד ברצו\"ש וכמ\"ש והחיות רצו\"ש כמראה הבזק, ופרש\"י כלהבת הכבשן שיוצא תמיד וממהר לחזור וליכנס כך כשמוציאות ראשן מתחת הרקיע כו' נרתעות מן השכינה שלמע' מהרקיע וממהרות להשיב את ראשן כו', ובס' מג\"ד אות נו\"ן כ' כי החיות אשר למטה מן הכסא משתוקקות וצמאות ורצות להשיג הכבוד העליון אשר למע' מהם כו', וע\"י תשוקתם ועלייתם זו מתמלאות אור ושפע עליון, ושבות בבחי' שוב מרוב מורא ופחד כו' ומיד"],[3601331245,"חוזרות ומשתוקקות צמאות ורצות להשיג, וכה משפטן כל הימים כו', והיינו ע\"י השגתם איך שהאוא\"ס קדוש ומובדל מהעולמות והחיות שנמשך בהם להחיותם הוא בחי' הארה לבד כו', עי\"ז הוא הרצוא להכלל באוא\"ס ב\"ה כו'. והאופנים והחיות הרצוא שלהם הוא ברעש גדול עוד יותר מהשרפים כו', והגם שאו' ברוך שהוא בחי' המשכה כנודע, י\"ל שזהו ג\"כ בחי' רצוא רק שהרצוא של השרפים הוא שרוצים להכלל, והרצוא של אופנים וחיוה\"ק הוא שרוצים ההמשכה והגילוי כו'. וידוע שגם בכלים דאצי' יש בחי' רצו\"ש וכמו שאמרו החכ' יראה לעלות אל הכתר שזהו בחי' שוב כו', וכמו\"כ יש בחי' רצוא וכמ\"ש בזהר בלק דקצ\"א א' ע\"פ שחורה אני ונאוה בשעתא דאיהי ברחימו סגי כו', מגו דחיקו דרחימו דלא יכלה למסבל אזעירת גרמה כו', והוא בעליית המל' מבי\"ע לאצי' שנסתר כל פרצופה שבבי\"ע ונעשית נקודה א' והיא נקודת הכתר שהו\"ע הביטול שלמע' מטו\"ד כו'. וכמו האה' דרעו\"ד שבפנימי' נקודת הלב שבא מצד עצמות אוא\"ס שהאה' והרצוא הוא בבחי' כלוה\"נ ממש כו', והוא התעוררו' האה' עצמי' שבנפש כו', דגם כשבאה\nע\"י ההתבוננות בעצמות אוא\"ס והיינו ההתבוננות ברוממות הא\"ס, לא רק איך שהגילוים הם רק הארה לבד וכולא קמי' כלא כו', כ\"א ההתבוננות ברוממות והפלאת אוא\"ס ב\"ה כו', מתעורר עי\"ז האה' עצמי' שבנפש כו', ובפרט בהרגש אוא\"ס ב\"ה שלא ע\"י התבוננות רק מה שעצם הנפש מרגיש את הא\"ס כו', שהאה' והרצוא הוא בבחי' התקשרות עצמי דנשמה כו', וה\"ה בבחי' כלוה\"נ ממש כו', וא\"ז כמו האה' הבאה ע\"י השגה והתבוננות דגם בתוקף האה' יש לה מ\"מ אחיזה כו', והוא האה' דבכל לבבך ובכל נפשך, דבכל לבבך הוא מה שהלב מכיל כו', ובכל נפשך הוא שהאה' בתוקף יותר עד שהיא בכל כחות הנפש כו' (וכמ\"ש במ\"א כמשל אמת המים המתפשט על כל גדותיו מפני ריבוי המים בימות הגשמים או בהפשרת שלגים כו'), דמ\"מ הוא לפ\"ע כחות הנפש כו', אבל האה' דבכל מאדך היא בל\"ג שאין לה אחיזה כלל בהכחות והוא בבחי' כליון לגמרי כו'. וכמו\"כ הוא בבחי' מל' דמגו דחיקו דרחימו שזהו תוקף האה' ורצוא ביותר דלא יכלא למסבל שאין הלב יכולה לסבול אזעירת גרמא שנעשי' נקודה תחת היסוד והוא בחי' כלי הכתר שבה\nשלמע' מבחי' הכלים דבחי' פנימי' כו', והוא בחי' הרצוא בבחי' כליון כו', ועי\"ז נעשה השוב שהוא בחי' תוס' אור וגילוי בבחי' מל' כו', וכמ\"ש בלק\"ת בהבי' דבמד\"ס פ\"ד על המד\"ר בא במדבר חרבה וקבלו אותו כו' אמר בה אני בונה כנסי' כו'.\n<b>ונמצא</b> דבכל המדרי' הן בנשמות למטה ובמלאכים למע' ובכלים בכולם יש בחי' רצו\"ש שהרצוא הוא בבחי' עלי' והסתלקו' והשוב הוא בבחי' המשכה וגילוי כו'. אמנם עיקר הרצו\"ש הוא בהאור והחיות האלקי כו', וכמו בהאדם הרי ההסתלקו' והתפשטות הוא בהחיות שז\"ע הנשימה, שעש\"ז נק' נשמה כנ\"ל שאין ההמשכה בבחי' התפשטות לבד כ\"א בבחי' הסתלקות והתפשטות רצו\"ש, ועי\"ז נעשה ההסתלקות והתפשטות בהדם כו', כמו\"כ הוא למע' דהחיות האלקי הוא בבחי' רצו\"ש וכמ\"ש והחיות רצו\"ש וקאי על האור והחיות האלקי שהוא בבחי' רצו\"ש, ועי\"ז הוא הרצו\"ש בחיות המרכבה וכמ\"ש היא מתהלכת בין החיות וקאי על בחי' מל' שהיא מתהלכת בב' בחי' הילוך ברצו\"ש כו', וכמו\"כ הוא בהאור המאיר בכלים דאצי' כו' וכמ\"ש הלא כה דברי כאש וכמו האש שאינו נח בהפתילה אלא עולה ויורד כו', כמו\"כ"],[3601331246,"האור המאיר בהכלים אינו רק בבחי' התפשטות לבד, וגם לא בבחי' התיישבות ממש בהכלים אלא הוא בבחי' רצו\"ש כו'. וכמ\"ש בס\"י ע\"ס בלי מה כו' ודברו בהם ברצו\"ש, ופי' ודברו של א\"ס המאיר בע\"ס דאצי' הוא בבחי' רצו\"ש כו', ופי' ודברו הוא בחי' מל' דא\"ק וכמשנת\"ל (ד\"ה אדם כי יהי') דכללו' ההשתל' הוא מבחי' מל' דא\"ק כו', ובשרשו הוא בחי' מל' דא\"ס דכללות גילוי הקו הוא מבחי' מל' דא\"ס כו' (גם י\"ל עפמ\"ש במ\"א שהקו נק' שכינה להיות דכללות גילוי הקו הוא רק להאיר את חשך הצמצום ולהיות שוכן ומתלבש בעולמות שזהו בדוגמת בחי' המל' השוכנת בתחתונים להחיותם כו', וכמשנת\"ל כללות ההפרש בין האור הא\"ס והאור שבמדה וגבול, דהאור שבבחי' א\"ס הוא לגלות עצמותו והאור שבבחי' מדה וגבול הוא רק להאיר העולמות כו', וגם מה שהקו נק' שכינה הוא ע\"ש שמקבל מאוא\"ס ומשפיע בנאצלים כו', דלהיות המשכתו הוא דרך דילוג הצמצום ה\"ז כמו שנתרחק ונבדל מאוא\"ס (עם היותו נוגע ודבוק כו') והוא בבחי' מקבל כו', ולפ\"ז י\"ל דמ\"ש ודברו בהם קאי על גילוי הקו כו'). ועז\"א ודברו בהם\nברצו\"ש דאופן המשכת האור בהע\"ס הוא בבחי' רצו\"ש דוקא בבחי' מטולמ\"ט כו', והיינו מפני שאין ערוך הכלים לגבי האור ואם הי' הכל בבחי' מטי הי' ביטול במציאות ולא הי' יכול להיות התהוות הכלים כלל, וכמ\"ש בע\"ח בענין התהוות הכלי בעקודים וז\"ל ואז ע\"י התרחקו ממנו אור עליון אז נעשה באותו אור הנשאר ונתהווה בחי' כלי כו' עכ\"ל. ודוגמא לזה מ\"ש במ\"א בענין מה שהקשה המק\"מ מדוע בדרום אין ישוב ועיקר הישוב בצפון והלא דרום הוא חסד וצפון גבו', והי' צ\"ל לכאו' עיקר הישוב בדרום בחי' חסד כו', וכמו חסד אמר יברא כו', וכידוע דעיקר ענין ההתהוות הוא מפני שעלה ברצונו להטיב כו', וההתהוות היא באמת מבחי' החסד וכמא' הגדולה זו מע\"ב כו'. אך הענין הוא כי דרום הוא ימין וצפון שמאל וימין המקבל הוא בקירוב יותר אל המשפיע בחי' ימין מקרבת כו', לכן הוא בבחי' ביטול יותר לגבי המשפיע ע\"ד איידי דטריד למבלע לא פליט כו', וכמו פני ארי' לימין שבבחי' קירוב יותר מפני שור כו', ולכן אא\"ל שם ישוב שהוא בבחי' יש ודבר, אלא דוקא בצפון שהוא שמאל המקבל ורחוק\nמהמשפיע ע\"כ יוכל להיות יש ודבר שז\"ע ישוב העולם כו' (ולכן רוח צפונית אינה מסובבת כי מפני הריחוק יכול להיות שם אחיזה יתירה כו', וכידוע דמקו הימין אינו משתלשל רק ק\"נ ומקו השמאל בא בג\"ק וכמו סוספיתא דדהבא כו', וע\"כ אינה מסובבת שלא תהי' יניקה ביותר כו'), והגם דההתהוות היא מ\"מ מבחי' החסד זהו דוקא ע\"י הגבו' שמעלים ומסתיר ומעלים את האור ומגביל אותו כו', וכמ\"ש בסש\"ב ח\"ב בענין הגדול הגבור כו', כי בכדי שיהי' מציאות יש זהו ע\"י הריחוק דוקא כו', וכמו עד\"מ השר כשהוא עדיין אצל המלך הוא בטל במציאו' ואינו נראה ליש ודבר אבל כשבא אל המדינה שהוא מושל בה ואינו אצל המלך אז נראה ליש ודבר גדול כו', וכ\"ה למע' בבחי' ז\"א ומל' דז\"א הוא בעל ט\"ס ואין בו בחי' המל' שהוא בחי' הגילוי למטה לפי שזהו בחי' יש, והיינו להיותו מבחי' ימין וזכר חסדו וכידוע דז\"א רובו חסדים כו', ה\"ה בבחי' קירוב לאוא\"ס ה\"ה בבחי' ביטול בבחי' דבקות למע' כו', ומל' שבנינה מהגבו' דוגמת צפון משם יוכל להיות התפשטות החיות בעולמות ומשם יפרד כו'. ועד\"ז יובן שא\"א שיתהווה כלי מאוא\"ס אם הי' הכל בבחי' מטי וגילוי האור, אלא דוקא ע\"י"],[3601331247,"מטולמ\"ט כו', וגם אחר שנתהווה הכלי אא\"ל התאחדות האור עם הכלי כ\"א בדרך רו\"ש, כי א\"א להכלי לקבל את האור בבחי' התיישבות ממש רק בבחי' רו\"ש כו', דע\"ה שבהתפשטות האור בהכלי הוא בבחי' התלבשות בהכלי מ\"מ מאחר שתיכף הוא בבחי' הסתלקות א\"ז בבחי' התגלות ממש כ\"א כמו נוגע ואינו נוגע כו', ובאופן כזה דוקא אפשר להכלי לקבל את האור כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש נשא את ראש בני גרשון גם הם, דהנה בני גרשון נשאו את היריעות שהן בחי' או\"מ ובעבודה הו\"ע הרצוא דרעו\"ד שנת\"ל, ועי\"ז הוא השוב שהוא המשכת האור ע\"י התו' וז\"ע הארון שבו היו הלוחות כו', והנה גבי תו' כתי' יקרה היא מפנינים כי פנינים הם אב\"ט שקובעים בכתר המלך, ובעבודה הו\"ע מצות מעשיות שנעשים בדברים הגשמי' שתחת ממשלת ק\"נ ומתבררים ונעשים אב\"ט ומאירים כו', שזהו המשכה מבחי' הכתר תר\"ך עמודי אור כו', אך המצות הן בחי' מקיף לבד, ותו' היא בחי' פנימי' והיינו המשכה מבחי' פנימי' הכתר כו', וע\"כ היא יקרה מפנינים כו'. וזהו דעיקר נשיאת ראש הוא בבני קהת נושאי הארון כו', דענין נשיאת ראש הוא גילוי בחי' פנימי' הכתר שזהו בהארון דוקא בבחי' הגילוי דתו' כו', ומ\"מ גם בבני גרשון נא' נשיאת ראש להיות שזהו ג\"כ בבחי' כתר כו', וזהו או' במד' לא שהן פחותים כו', דהסברה היא שהן פחותים מבני קהת מפני שהן בבחי' חיצוני' הכתר כו', ומ\"מ אינם פחותים להיות שזהו עכ\"פ בבחי' הכתר, רק מפני כבוד התו' כו', כבוד התו'\nהיינו גילוי בחי' פנימי' הכתר שבתו' כו', ע\"כ הקדים בני קהת שבהם עיקר הנשיאת ראש כו', ובבני גרשון נא' גם הם כו'. וזהו ג\"כ מ\"ש בהם ע\"פ אהרן ובניו, דאהרן המשיך בחי' אה\"ר הנ\"ל, דאהרן הוא א' הר נו\"ן, הר הוא בחי' אה\"ר וא' אותי' פלא והיינו האה' הבאה מהתבוננות ההפלאה דאוא\"ס ב\"ה, ונו\"ן הוא בחי' המשכת האה\"ר בנש\"י, ולכן בבני גרשון שזהו בחי' אה' הנ\"ל נא' בהם ע\"פ אהרן כו', וגם גרשון הוא שמגרש את הרע ויגרשהו וילך לו כו', וזהו מבחי' אה\"ר שזהו בשנותו את טעמו לפני אבימלך ועי\"ז ויגרשהו כו' וכמ\"ש במ\"א, וזהו נשא את ראש בני גרשון גם הם דעיקר נשיאת ראש הוא בבני קהת מפני כבוד התורה ובני גרשון גם הם בבחי' נשיאת ראש באה' דרעו\"ד ועי\"ז הוא ההמשכה ע\"י התו' כו'."],[3601331248,"<h3>בס\"ד. ש\"פ בהעלותך, העת\"ר</h3>\n<b>בהעלותך</b> את הנרות אל מול פני המנורה יאירו שבעת הנרות, וצ\"ל מה\"ע או' יאירו שבעת הנרות דהול\"ל יהיו שבעת הנרות, דכשאו' יאירו משמע שיהיו מאירים את פני המנורה וצ\"ל מה\"ע שיאירו כו'. והנה רש\"י הביא בש' המדרש למה נסמכה פ' הנרות לפ' נשיאים דכשראה אהרן חנוכת הנשיאים חלשה"],[3601331249,"דעתו שלא הי' הוא ולא שבטו עמהם בחנוכה א\"ל הקב\"ה חייך שלך גדול משלהם שאתה מדליק ומטיב את הנרות. ולכאו' א\"מ והלא כמה קרבנות הקריב אהרן משלו בשבעת ימי המלואים ולמה חלשה דעתו מזה שלא הי' עמהם בחנוכה כו', גם מה שא\"ל שלך גדול משלהם א\"מ והלא קרבנות הם ענין גדול ונעלה מאד ובפרט בחנוכת המזבח שהי' ריבוי קרבנות ומפני מה הדלקת הנרות גדול מהקרבנות כו'. ולהבין זה ילה\"ק משנת\"ל דיום ולילה בעבודה הו\"ע רצו\"ש כו', דענין רו\"ש הוא בנשמות וכן במלאכים למע' בחיות המרכבה וגם בבחי' הכלים דע\"ס כו', ועיקר הרו\"ש הוא בהאור שז\"ע והחיות רצו\"ש כו'. ונת' הטעם מפני שהתהוות הכלי מן האור הוא דוקא ע\"י הרו\"ש של האור בחי' מטולמ\"ט כו', וגם לאחר שנתהוו הכלים התחברות האור והכלי אינו יכול להיות בבחי' התיישבות ממש כ\"א בדרך רו\"ש דוקא כו'.\n<b>והנה</b> לפי הנ\"ל הרצו\"ש של האור אינו כמו הרצו\"ש שבהכלים, דהרי בהכלים וכן בנשמות ובנבראים הרי הרצוא הוא בבחי' עלי' והסתלקות והשוב הוא בבחי' התפשטות כו', ובהאור הוא להיפך שהרצוא הוא בחי' מטי דהיינו התפשטות האור, והשוב הוא בחי' ולא מטי שהוא בחי' הסתלקות האור מן הכלי כו'. ומצינו ל' רצוא בבחי' המשכה כמ\"ש מגדול עוז שם הוי' בו ירוץ צדיק כו', ופי' בזהר בראשית דל\"ז ע\"ב דמגדול עוז היינו בחי' מל' שהיא ש' ה' שמו של ה' כו', ובפרד\"ס ערך מגדל פי' הטעם שהמל' נק' מגדל כי היא ראשית לכל אשר ממנה ולמטה שהיא סוף האצי' וראש לכל הנבראים כו', וי\"ל שזהו כענין אימתי הוא גדול כשהוא בעיר אלקינו, דמלכא בלא מטרוניתא לאו מלך ולאו גדול אקרי כו', וידוע דעיר אלקינו הוא בחי' מל' שנעשית מקור לבי\"ע, ועי\"ז דוקא ניכר גדולת ה', וכדאי' במדרש ע\"פ השמים מספרים כבוד אל משל למלך כו' מאבנא דהוא מתגושש בהון אתון ידעין גבורתו כך השמים מספרים כו', וזהו מגדול עוז ש' הוי' שעי\"ז הוא גדול ה' כו'. וגם י\"ל מגדול שממשיך בחי' הגדולה\nבז\"א כו', ע\"ד שאין נותנים לאדם פרנסה אלא בשביל אשתו כו', דכל גדולה היא בא\"א (וכידוע בענין חג\"ת וגג\"ת כו'), וע\"י המל' נמשך הגדולה מא\"א בז\"א כו'. בו ירוץ צדיק בחי' יסוד והוא התקשרות בחי' סוכ\"ע בממכ\"ע והו\"ע יחיד חי העולמים מלך, חי העולמים בחי' יסוד מקשר ומחבר בחי' יחיד בחי' אוא\"ס יחיד ומיוחד עם בחי' מל' כו', ופי' ירוץ כמ\"ש לרוץ אורח דהיינו שתהי' ההמשכה גם בבחי' ה\"ס אחרונות דמל', וכידוע דה\"ס הראשונות דמל' תמיד מאירות מבחי' ז\"א וענין מלא וחסר הוא בה\"ס האחרונות כו', ואומרו ירוץ צדיק שיהי' הגילוי גם בה\"ס האחרונות כו', וגם דהמשכת האורות הוא במהירות בלי שום מניעה ועיכוב כו', דבס' השתל' הרי יכול להיות עכבה, אבל כאשר הגילוי מלמע' מהשתל' אז אין שום עכבה וההמשכה היא במהירות כו'. ונמצא שייך ל' רצוא גם בבחי' המשכה מלמע' והו\"ע הריצה והגילוי כו'. גם י\"ל בזה רצוא ל' רצון, שהרי המשכת האור בהכלי הוא בבחי' רצון בהאור כו', וכידוע דכל השפעה אא\"ל בדדך הכרח וכמשנת\"ל (ד\"ה וכל העם רואים) דכאשר ההשפעה היא בדרך\nהכרח אז הצמצום הוא שמעלים כו', כ\"א שבהאור יש בו רצון להאיר בהכלי, והיינו מפני ששרש הכלי קדום אל האור ויש בה כח עליון יותר כו', וע\"כ ע\"י שנרגש"],[3601331250,"בהאור שרש ומקור הכלי ה\"ה רוצה להשפיע בהכלי כו' וכמ\"ש במ\"א, ולפ\"ז הרצוא שהוא המשכת האור הוא ל' רצון שרוצה להיות נמשך ולהאיר כו'. ונמצא דהרו\"ש של האור הוא שהרצוא הוא בבחי' המשכה והשוב הוא בבחי' עלי' והסתלקו' כו', וה\"ז להיפך מהרו\"ש שבכלים כו'. אמנם זהו בהאור לגבי הכלים ובד\"כ כמו שהוא בבחי' חיות להחיות כו', אבל לגבי למע' דהיינו לגבי שרשו ומקורו הוא ג\"כ בבחי' רו\"ש כמו בהכלים שהרצוא הוא בבחי' עלי' והסתלקות והשוב הוא בבחי' המשכה כו', וכידוע בענין למען יזמרך כבוד ולא ידום דנהו\"ת קארי תדיר לנהו\"ע ולא שכיך דבחי' מל' שיורדת בבי\"ע להוות ולהחיות עולמות בי\"ע היא תמיד בבחי' רצוא לעלות למע' כו' (ועי\"ז נעשה ג\"כ הרצוא בחיות המרכבה עי\"ז שהיא מתהלכת בהם בבחי' רצוא כו', כמ\"ש בזח\"א דרכ\"ט ע\"ב ע\"פ משכני אחריך נרוצה דכד סלקא דא כולהו סלקין אבתרה כו', כענין בתולות אחרי' רעותי' מובאות לך שהם היכלות דברי' (שהן ז' נערות הראויות לתת לה כו'), והנשמות כולם בבחי' רצוא ע\"י הרצוא דבחי' מל' כו').\n<b>ועש\"ז</b> נק' בחי' המל' צמאה וכמ\"ש למען ספות הרוה את הצמאה ופרש\"י בסנהדרין דע\"ו ע\"ב הצמאה זו כנס\"י שהיא צמאה ליוצרה כו', ולמע' היא בחי' מל' שהיא בבחי' צמאון לעלות למע' כו', ופי' הצמאה ה' צמאה דאות ה' הוא בחי' בהבראם בה' בראם כו', וכמא' בה' נברא העוה\"ז כו', והוא כללות בחי' דבור העליון כו'. ומבשרי אחזה אלק' שאצל האדם יש שכל ומח' ודבור ובשכל אין שום אות ניכר עדיין, וכמו בהברקת השכל שאינו נרגש שם כלל מציאות אותי', וגם במחשבת שכל לעצמו אין האותי' נרגשים עדיין כו' וכמשנת\"ל (ד\"ה זה יתנו), וכן בעצם המדות כמו בעצם חמדת הלב אינם ניכרים אותי' כו', רק במח' שהיא חיצוני' השכל שם נראה ונתהווה בחי' אותי' במורגש לעצמו כו', ואח\"כ בדבור נעשו בחי' אותי' בגשם היינו שמתלבשים בהבל הגשמי המתחלק בה' מוצאות כו', ומבטה ההבל הוא אות ה' וכמ\"ש בלק\"ת בד\"ה וספרתם לכם דחה\"ש, דכללות ההבל דאותי' הדבור הוא אות ה', דאחה\"ע מן הגרון שהוא ההבל וכללות ההבל הוא אות ה'. וכמו\"כ הוא למע' דבחי' שכל ומדות שלמע' שהן בחי' חו\"ב\nוז\"א וגם בחי' המח' שהוא חיצוני' בינה ה\"ז למע' עדיין מבחי' מקור לעולמות כו', רק בהבראם בה' בראם שזהו בחי' המל' בחי' דבור העליון זהו שנעשה בבחי' מקור לעולמות כו', ולכן בהג' קוין דה' מרומז ג' עולמות בי\"ע בחי' בראתיו יצרתיו אף עשיתיו כו' כמ\"ש בת\"א ד\"ה חייב אינש לבסומי בפורי' הא', לפי שזהו המקור המהווה ג' עולמות בי\"ע כו', ועז\"א הצמאה דאות ה' הנ\"ל רוצה ומשתוקק תמיד לחזור לאין להכלל באחדות פשוטה כו'. וכמו\"כ הוא בכללות האור הנמשך מא\"ס ב\"ה הוא בבחי' רצוא לעלות למע' כו', גם באוא\"ס שלפה\"צ שהי' בזה הצמצום שהאור נכלל בהמאור מבו' במ\"א שזהו עליית האור שלא יהי' בפ\"ע. והענין הוא דהנה מה שהי' אוא\"ס ממלא כל מקום החלל זהו בחי' התפשטות האור כו' וכמא' הפדר\"א עד שלא נבה\"ע הי' הוא ושמו בלבד, הוא היינו בחי' עצם האור שלמע' מבחי' גילוי והוא בחי' ההעלם כו' (והיינו בחי' העלם שלמע' ממקור לגילוי כ\"א בבחי' העלם בעצם כו' והוא בחי' עצם האור כו'), ושמו הוא בחי' גילוי האור בעצמותו כו', ובזה גופא יש ב' מדרי' בחי' הגילוי לעצמו והגילוי השייך אל העולמות כו', וכמשנת\"ל (ד\"ה וידבר אלקים) דשמו הוא ש' הוי' (והוא בחי' אצי'"],[3601331251,"דכללות שזהו בהאוא\"ס שלפה\"צ כו' וכמ\"ש בלק\"ת בהבי' דלמוצאיהם), וידוע דבש' הוי' יש ב' מדרי' בחי' י\"ה ובחי' ו\"ה והו\"ע הנסתרות לה' אלקינו והנגלות לנו ולבנינו, די\"ה הוא בחי' נסתרות שלמע' מבחי' העולמות וכמו אלפים שנה קדמה תו' לעולם כו', וו\"ה הוא בחי' והנגלות השייך לעולמות כו', וכמו\"כ הוא בבחי' שמו הגדול שלפה\"צ דבחי' י\"ה הוא בחי' אור המאיר לעצמו עדיין וכמא' הבדילו לעצמו כו', ובחי' ו\"ה הוא בחי' התפשטות האור שבעצמותו גופא כבי' הוא בחי' אור השייך אל העולמות כו' (והנה לפה\"צ לא הי' ניכר עדיין בפ\"ע האור השייך אל העולמות והי' כלול בפנימי' האור כו', ונת\"ל ד\"ה ויהי הענן דלפה\"צ הי' מאיר בחי' פנימי' האור כו', ומ\"מ צ\"ל שא\"ז שהאיר בחי' פנימי' האור כמו שהוא לעצמו, רק שבבחי' התפשטות האור השייך אל העולמות הי' בזה גילוי בחי' פנימי' האור, וזהו מעלת חיצוני' האור כמו שהוא לפה\"צ, דהרי בחי' חיצוני' האור כשהי' כלול בהפנימי' הי' במעלה ומדרי' גבוה יותר כו', וזהו שהי' גילוי בחי' הפנימי' היינו בחי' חיצוני' כמו שהוא במע'\nהעליונה כו'). ומבו' בלק\"ת ד\"ה להבין מ\"ש באוצ\"ח ספ\"ג שזהו בחי' מח' ודבור כמו שהוא לפה\"צ דהיינו בחי' הדבור לעצמו וכמו אמרה ד\"פ בינו לבין עצמו כו', ומבו' שם שזהו בחי' השפלה וירידה לגבי האור כמו שהוא במח' לעצמו כבי' כו', ובחי' התעלמות האור הוא שנסתלק מלהאיר באותי' הדבור ונכלל באותי' המח' כו', ה\"ז עליית האור שלא להיות בפ\"ע כ\"א בבחי' התכללות במקורו כו', דבחי' הדבור הוא שנעשה דבר בפ\"ע שהרי מתגלה אל הזולת כו', ומובן דבמדרי' שלפה\"צ אינו שייך לו' שנעשה דבר בפ\"ע שהרי הכל כלול בעצמותו כו', רק שמ\"מ ה\"ז בדוגמא כמו בבחי' התגלות הדבור כו', וע\"כ בחי' הסתלקות והתכללות האור במח' זהו כמו עליית האור שלא להיות בפ\"ע כו', וזהו כדוגמת בחי' רצוא בהאוא\"ס שלפה\"צ, וכ\"ש שהאור כמו שהוא לאחה\"צ הוא בבחי' עלי' והסתלקות במקורו כו', שז\"ע והחיות רו\"ש שהאור וחיות שבעולמות הוא בבחי' רו\"ש תמיד כו'.\n<b>והנה</b> סבת הדבר מה שהאור הוא בבחי' רו\"ש, הענין הוא דהנה ידוע בפי' אור שהוא רק התגלות העצם לבד ואינו מתייחס כלל בערך אל העצם כו', וכמו אור השמש המאיר לארץ ולדרים עלי' ה\"ז רק אור וזיו השמש לא עצם השמש דעצם השמש קבוע בגלגלו ואינו מתפשט בעולם רק אור וזיו ממנו הוא המתפשט בעולם להאיר, ועצם השמש נק' מאור ואינו בגדר להאיר, ואפי' האור כמו שהוא כלול בהעצם ג\"כ אינו בגדר להאיר רק אור וזיו היוצא ממנו ע\"י המגן ונרתק הוא המאיר כו'. ויובן זה עד\"מ מאור הראי' שזהו רק אור המתפשט ויוצא מכח הראי' והוא הרואה כו', שהרי הסומא נק' בל' רז\"ל סגי נהור או מאור עינים, ולכאו' א\"מ איך נק' בשם ההפכי לכאו' שהרי אינו רואה כלל ואיך נק' סגי נהור שזהו ריבוי אור, או מאור עינים שהוא מקור האור וה\"ז לכאו' כמו לועג לרש. אך הענין דא\"ז לועג לרש כי באמת הוא בריבוי אור וזהו סבת העדר הראי' כו', וכידוע דחומר העין יש עליו כמה קליפות שהן כגלדי בצלים זע\"ז והן המכסים ומעלימים על אור הראי' שעי\"ז אור הראי' יוצא מעצם כח הראי'\nומתעלם עד שיהי' בבחי' אור להאיר ולראות ע\"י, דחומר העין יש בו עצם כח הראי' שהרי גם הסומא יש בו כח הראי' בחומר העין שלו כו', והוא להיות שחומר הוא כלי מוכן"],[3601331252,"לקבל אור הראי' ע\"כ יש בו מעצם כח הראי' (וכמו עצם כח התנועה שביד קודם שמנענע וגם באיזה קלקול שא\"י לנענע ומ\"מ יש בו כח התנועה כו' כידוע), והאור הכלול בו הוא עדיין אור הכלול בהעצם כו', אך המסכים המכסים על חומר העין שאינם כלים אל אור הראי' ה\"ה מוציאים את אור הראי' חוץ לעצם כח הראי' והאור מתעלם בהם, ועי\"ז הוא הראי' בפועל כו', וכאשר נחסר מהקליפות ההן מחמת הזקנה וריבוי השמוש בהם מאיר אור הראי' ביותר, וזהו הסבה שאינו רואה מפני שמאיר האור כמו שכלול בעצם הכח שהוא בבחי' ריבוי אור שאינו בגדר להאיר וכ\"ש כשמאיר עצם הכח כו', וזהו שנק' סגי נהור או מאור עינים שהאמת הוא כן והוא סבת העדר הראי' כו' (ועמשנת\"ל ד\"ה ויקח קרח). ונמצא מובן דמה שהוא בבחי' אור להאיר ה\"ז רק האור והזיו וכמו שהוא יוצא מן העצם וכמו שמתעלם דוקא, אבל האור כמו שהוא כלול בהעצם ומכ\"ש העצמי אינו בגדר להאיר כו', וכמו\"כ הוא באור השמש המאיר למטה שזהו רק האור והזיו וכמו שבא דרך הנרתק כו'. וכמו\"כ יובן בדוגמא למעלה דאור א\"ז עצמי דא\"ז בגדר אור\nלהאיר וגם לא האור הכלול בהעצם כ\"א רק אור וזיו המתפשט ויוצא מן העצם וע\"י הצמצום שמתעלם האור כו', ולכן אין האור פועל שינוי כלל בהעצם וכמ\"ש אני ה' לא שניתי מפני שזהו רק הארה לבד שאינו עצמי ובאין ערוך לגבי העצם כו', וכמו באור השמש כשאינו מתפשט בבית מפני איזה מניעה ועיכוב וכמו מסך המבדיל א\"ז שינוי כלל בעצם השמש כו' (ויש להבין בזה דאור השמש אינו פועל שינוי בעצם השמש אם מאיר או שאינו מאיר כו', דהרי השמש ענינו הוא להאיר וכמ\"ש ויתן אותם כו' להאיר על הארץ כו', וכ\"ש האור הכלול בהשמש שהוא להיות ממנו אור וזיו המאיר כו', וא\"כ כשאינו מאיר הרי הי' צ\"ל מזה שינוי בהשמש ולכה\"פ בהאור הכלול בו כו', דכל כח שאינו פועל פעולתו הוא משתנה ומתעלם בעצם כו', והנה במשל השמש הרי האור תמיד נמשך מהשמש רק שאינו מאיר למטה מהעננים כו', אמנם ברוחני' הענין דכאשר אינו מאיר האור הוא שאינו נמשך כלל כו', וא\"כ ה\"ז צ\"ל לכאו' שינוי בעצם הכח כו'. וצ\"ל שיש בזה הפרש אם הוא פועל בדרך שפע או בדרך אור, דזה שכל כח מתעלם בעצמו ע\"י העדר\nהפעולה זהו כשהפעולה הוא בבחי' שפע כו', וכמו בהשפעת השכל הנה ע\"י השפעת השכל אל הזולת מתוסף שכל בהמשפיע, וכמו ומתלמידי יותר מכולם שזהו לא רק במה שהתלמיד מחכים את הרב ע\"י הקושיות וכה\"ג, כ\"א שע\"י ההשפעה לבד אל התלמיד מתוסף חכמה ושכל אצל הרב כידוע, ובהעדר השפעה מתעלם השכל בעצמו כו', וזהו דוקא בפעולה שבדרך שפע שמתפעל בהפעולה, וכמו\"כ מתפעל בהעדר הפעולה, אבל כאשר פועל בדרך אור שאינו מתפעל בהפעולה, כמו\"כ אינו מתפעל בהעדר הפעולה כו', ולכן אור השמש שבא מהשמש בדרך אור לא בדרך שפע כנודע, ע\"כ אינו פועל שינוי בהשמש כו'. וכמו\"כ הוא האור למע' שבא בבחי' אור, דגם אור הקו הגם שבא דרך הצמצום מ\"מ הוא בבחי' אור כו' (ולכן הגם שהוא כמו המשכת השערות שנק' מזל מ\"מ הוא בבחי' ריבוי אור כו' וכמ\"ש במ\"א), וכ\"ש האור שלפה\"צ שהוא בבחי' אור כו'. ומ\"מ א\"ז מובן עדיין שהרי איך שיהי' הרי הכוונה אינה נשלמת, וא\"כ העדר שלמות הכוונה שבהמקור ה\"ז גורם שינוי כו'. וצ\"ל שג\"ז אינו פועל שינוי מפני שהמניעה אינו מצד המקור שהרי השמש או האור הכלול"],[3601331253,"בתוכו בכחו להאיר בכל מקום והמניעה היא רק מצד המקבל שאינו כלי לקבל וכמו מפני מסך וכה\"ג, ע\"כ א\"ז עושה שינוי בהמקור כו'. וכ\"ה גם בבחי' שפע, דבשפע הרי העדר ההשפעה פועל שינוי בהמשפיע כו' וכמשנת\"ל מזה בד\"ה שופטים באורך, הנה זהו דוקא כאשר המניעה מצד המשפיע שמעלים אור שפעו ואינו חפץ להשפיע, אבל כאשר המניעה הוא רק מצד המקבלים היינו שאין לו מקבלים או שהמקבלים אינם כלים לאור ההשפעה שלו, א\"ז שום שינוי וגרעון בהמשפיע כו', דכאשר המניעה היא מצד המשפיע ה\"ז בדרך היסח הדעת שמסיח דעתו לגמרי מהשפעה, וע\"כ ה\"ז גורם התעלמות בעצם הכח כו', אבל כאשר המניעה היא רק מצד המקבלים א\"ז בדרך היסח הדעת ואינו עושה התעלמות כו'. ונמצא דגם בשפע א\"ז עושה שינוי כו', וא\"כ כ\"ש שהוא כן בענין האור כו', ולפ\"ז צ\"ל שגם בהאור אין שינוי ע\"י שאינו מאיר בהבית מפני שאין המניעה מצד האור שהרי ביכולתו להאיר רק המניעה הוא מהמקבל ע\"כ א\"ז עושה שינוי וגרעון בהאור ג\"כ כו'.\n<b>אך</b> עדיין א\"ז מספיק דמ\"מ יהי' איך שיהי' הרי הכוונה אינה נשלמת (ואם כי בודאי אינו דומה אם זהו מצד המשפיע או רק מצד המקבל כנ\"ל, מ\"מ הכוונה אינו נשלם כו'). וע\"כ צ\"ל דהעיקר בזה הוא מפני שהמקור הוא מובדל בערך מהגילוי, ומה שיש בכח המאור להאיר הוא בו כח עצמי והיולי, והיינו שהאור הכלול בהמאור הוא עצמי והיולי לא בבחי' מקור לאור המאיר, וע\"כ אין העדר הגילוי פועל בו שינוי מפני שאינו מקור עדיין לגילוי כו', וע\"כ גם כשאין האור והזיו מתפשט ממנו אין זה עושה בו שום שינוי כי הוא בעצם מהותו כמו שהוא כו', ולפ\"ז צ\"ל דבהאור ע\"י העדר הגילוי גם שהוא רק מצד המקבלים ה\"ז שינוי בהאור שהרי ענינו הוא להאיר כו', והיינו שהוא מתעלם בעצמו עי\"ז כו', אך ידוע דהעלם וגילוי א\"ז שינוי כ\"כ כו' וכמ\"ש במ\"א. והנה לפי הנ\"ל צ\"ל הדוגמא למע' דמה שאינו נוגע זהו בפנימי' האור להיות שזהו בחי' עצם האור שאינו בבחי' מקור אל הגילוי, ע\"כ אינו נוגע שם כלל אם האור מאיר כו', אבל בחיצוני' האור והיינו בעצמותו גופא האור השייך אל העולמות\nשם נוגע העדר הגילוי כו', והרי מבו' בכ\"ד דכחשיכה כאורה הוא בחיצוני' האור כו', משא\"כ בפנימי' האור נוגע וע\"ד להתם מטי כו' וכמשנת\"ל ד\"ה צו את אהרן. אך הענין הוא דלבד זאת דכללות האור שלפה\"צ הוא למע' מבחי' מקור עדיין כו', הנה גם לפמ\"ש בכ\"ד דחיצוני' האור הוא בחי' העלם של הגילוי לגבי הקו כו', והיינו שהוא בבחי' מקור אל הגילוי כו', הרי מה שאנו מדברים כאן זהו מצד הכוונה, דמצד ההשפעה והגילוי ה\"ז בדרך אור לא בדרך שפע כו' שא\"ז פועל שינוי כנ\"ל, כ\"א מה שהקשינו ע\"ז הוא מצד השלמת הכוונה, והרי הכוונה פנימי' א\"ז בחיצוני' האור כ\"א בפנימי' ועצמי' האור כו', ולכן בבחי' חיצוני' האור כחשיכה כאורה כו', ובפנימי' שם הוא הכוונה המושרשת כו', ובחי' פנימי' האור ה\"ה עצמי שלעולם הוא בבחי' עצמותו אם המקבלים המה כלים אל האור ומאיר בהם א\"ל ח\"ו, וכבר נת\"ל שם דבפנימי' הגם שאינו נוגע ומ\"מ הכוונה היא שיהי' דוקא גילוי אור ובאופן אחר אינו נשלם הכוונה כו', רק שהעדר שלמות הכוונה ח\"ו א\"ז עושה שינוי ח\"ו להיותו אור עצמי (וכמו היולי\nהעצמי כנ\"ל), והשינוי הוא רק בהמקבלים, וע\"י שמאיר האור בגילוי בכלים נשלם הכוונה הפנימי' ומאיר בזה האור הפנימי והעצמי כו'). והדוגמא מזה יובן למע' דאור הוא"],[3601331254,"בחי' הארה לבד שאינו העצם וגם לא אור הכלול בהעצם דכ\"ז אינו בגדר אור להאיר כו', רק הוא בחי' זיו המתפשט ויוצא כבי' מן העצם ע\"י הצמצום ונתעלם האור עד שהוא בגדר אור להאיר כו', והנה האור ע\"ה הארה לבד ה\"ה מ\"מ מעין המאור כו', שז\"ע אור שהוא בבחי' דבקות במקורו ומעין מקורו כו', וכמשנת\"ל ד\"ה שופטים, וע\"כ מ\"ש אני ה' לא שניתי קאי גם על האור שגם בו אין שינוי כו', וכמו באור השמש שאם יש עננים המסתירים שאין האור מאיר א\"ז שינוי גם בהאור כו', וכמו\"כ הוא בהאור הנמשך מאוא\"ס בעולמות אין בו שינוי, דהשינוי הוא רק מצד הכלים המקבלים (וכנ\"ל דהמניעה אינו מצד המשפיע כ\"א מצד המקבל כו') ובהם הוא השינוי אבל לא בהאור כו' (ומ\"מ אינו דומה ממש לאור השמש שמאיר רק בדרך מקיף אבל האור שבעולמות ה\"ה בבחי' או\"פ וכאשר הכלי אינו בבחי' כלי לקבל הרי האור מתעלם כו', וכמו כד אנת תסתלק מינייהו כו' שגורם סילוק והתעלמות האור כו', וכמ\"ש בד\"ה ארדה נא הב' שע\"י הכלים ידוע גם בהאור כו', וכמ\"ש מחטו לי כו' וכמ\"ש במ\"א, רק שהסילוק אינו בבחי' סילוק\nלגמרי ח\"ו כ\"א שמתעלם כו' וכמ\"ש במ\"א, והעלם וגילוי א\"ז שינוי כו' וכנ\"ל), וזהו לפי שהאור הוא מעין המאור כו', ומ\"מ הוא באין ערוך לגבי המאור וכמ\"ש כי עמך מקו\"ח רק עמך בטל וטפל לך מפני שאין ערוך כו', והיינו דלהיות בחי' אור שהוא בבחי' דבקות ה\"ה מעין המאור, ולהיותו בחי' הארה לבד וזיו המתפשט מן העצם הוא באין ערוך כו'. וזהו הטעם שנק' בש' א\"ס ולא אין לו תחלה, דהרי אין לו תחלה הוא מע' יתירה מאין לו סוף כו', אך זהו מפני שתחלה יש לו דמאחר שהוא הארה לבד הרי יש לו מקור דמשם הוא נמשך כו', וע\"כ אינו נק' אין לו תחלה רק שאין לו סוף מפני שהוא מעין מקורו כו' כנ\"ל. וזהו הטעם שיש בהאור טבע הרצוא שנמשך לגבי מקורו כטבע כל דבר להיות נמשך לגבי שרשו ומקורו כו', וטבע זאת הוא כמ\"ש בסש\"ב פי\"ט ושם טבע מושאל לכל דבר שלמע' מטו\"ד כו', וכמו האש שחוזר תמיד לעלות למקורו האש היסודי אע\"פ שיתבטל שם ממציאותו הראשון לגמרי ויהי' שם אין ואפס אעפ\"כ כך הוא טבעו כו', וכמו\"כ האור טבעו לחזור למקורו ושרשו כו'. ועוד זאת שהרי האור הי'\nכלול תחלה במקורו, ואז הי' במע' ומדרי' עליונה הרבה יותר וכמו זיו השמש כשהוא בעצם השמש כו', ומה שנמשך להיות בבחי' אור להאיר ולהחיות את העולמות ה\"ז ירידה גדולה לגבי האור כו', וכמשנת\"ל דגם מה שע\"י הצמצום נבדל החיצוני' מן הפנימי' ה\"ז ירידה לגבי האור כו', ובפרט כמו שנתעלם תוך העלם הצמצום כו', ובכללות הוא שהאור נעשה בבחי' יש ומציאות דבר כו', וע\"כ תמיד הוא בבחי' רצוא לעלות לשרשו ומקורו שזהו עלי' מירידתו ולחזור להיות בבחי' אין כו', וזהו והחיות רצו\"ש שתמיד הוא בבחי' רצו\"ש הסתלקות והתפשטות כו'.\n<b>והנה</b> זה מובן דהרצוא שבהאור הוא למע' במדרי' מהרצוא שבכלים כו', וי\"ל דהנה ידוע שיש ג' אהבות אהבת עולם ואה\"ר ואה' בתענוגים כו', אה\"ע היא האה' שבא מההתבוננות בהעולמות איך שהאור והחיות המתלבש בהעולמות הוא רק הארה לבד ובאין ערוך כלל לגבי העצם כו' וכמשנת\"ל (ד\"ה נשא), ועי\"ז הוא האה' והרצוא להיות בבחי' התכללות בעצמו' אוא\"ס כו', וזהו הרצוא דנשמות למטה שהיא בבחי' התפעלות מורגשת כו', ואה\"ר היא שבאה ע\"י ההתבוננות בעצמו' אוא\"ס דהיינו בהפלאת ורוממות אוא\"ס כו', שעי\"ז הוא הרצוא בבחי'"],[3601331255,"רעו\"ד שזהו הרצוא דבחי' הכלים כמשנת\"ל שם, אמנם אה' בתענוגים הוא להתענג על ה' עד כלותה ממש היינו בבחי' כליון ובבחי' ביטול ממש, וה\"ז למע' במדרי' מבחי' אה\"ר שזהו מ\"מ בבחי' התפעלות ובבחי' רשפי אש (רק שזהו מה שבאש ה' כו'), אבל אה' בתענוגים הוא בבחי' ביטול בתכלית בחשאי בלי שום התפעלות ומורגש כלל וכמו עבודת הכהנים שהיא בחשאי דוקא כו'. וזהו בחי' הרצוא שבהאור דלהיות שהאור הוא בבחי' דבקות במקורו ע\"כ הרצוא הוא כענין אה' בתענוגים כו', דהכלים עם היותם אלקות הרי מ\"מ אינם בבחי' דבקות ולכן הרצוא הוא כמו אה\"ר בבחי' התפעלות ורשפי אש כו', אבל האורות שהן בבחי' דבקות הרצוא הוא בבחי' ביטול בתכלית כו'. ועל ל' השמות ג' ענינים אלו הן ג' שמות ע\"ב מ\"ה ב\"ן וכמ\"ש בתו\"א בהבי' דחכלילי, דאה\"ע הוא בחי' שם ב\"ן, ועי\"ז נעשה ג\"כ בירור העולם בכלל ובירור הנה\"ב בפרט כו', וכמשנת\"ל ד\"ה הנ\"ל דבהתפעלות מורגשת דנה\"א נעשה ההתחברות דנה\"א עם הנה\"ב להיות הבירור דהנה\"ב כו', ואה\"ר היא בחי' ש' מ\"ה, וידוע דש' מ\"ה הוא המברר בבחי' בירור שני,\nדלאחר שמתברר ע\"י ש' ב\"ן שזהו בבחי' ביטול היש בלבד, הנה אח\"כ הוא הבירור ע\"י ש' מ\"ה בכדי שיוכלל באלקות כו', והיינו שלאחר בירור הנה\"ב ע\"י האה' דאה\"ע, כשבאים לבחי' אה\"ר נעשה הביטול במציאות בנה\"ב (הביטול במציאות היינו ע\"ד דוגמת הביטול דכלים כו') להיות נכלל באלקות כו', ובחי' אהב\"ת זהו בחי' ש' ע\"ב שלמע' מענין הבירורים, רק שלאחר שיש בחי' אה\"ע ואה\"ר נותנים מלמע' בחי' אהב\"ת שהו\"ע עבודת מתנה אתן את כהונתכם כו'.\n<b>וע\"פ</b> הנ\"ל יובן מש\"א במדרש דחלשה דעתו כו' וא\"ל חייך שלך גדול משלהם כו', דהנה ענין הקרבנות על המזבח הו\"ע עליית הבהמה בשרשה ומקורה ע\"י בחי' הגבו' שבמל', וכמ\"ש אש תמיד תוקד על המזבח שזהו בחי' ה\"ג שבמל' שע\"י הוא הבירור והעלי' כו', והו\"ע הבירור שע\"י ש' ב\"ן הנ\"ל, אמנם בכדי שתהי' העלי' ע\"י בחי' המל' הי' צ\"ל מתחלה המשכת אור עליון שז\"ע חינוך המזבח, דענין החינוך הוא שממשיכים גילוי אור מלמע' בכדי שיוכל להיות אח\"כ ההילוך בכח עצמו כו', וז\"ע הקרבת הנשיאים שהן מבחי' אימא והיינו שהמשיכו בחי' ה\"ג דאימא שזהו גילוי אור עליון הרבה לגבי בחי' המל', והוא הנותן כח ועוז בבחי' מל' להיות ההעלאה מלמטלמ\"ע כו', דכמו שהבירור שני הוא ע\"י ש' מ\"ה כנ\"ל כמו\"כ עי\"ז נמשך הכח בש' ב\"ן לברר כו'. והנה אהרן חשב שהמשכת האור במל' צ\"ל ע\"י דוקא, כי אהרן הוא בחי' אור אבא, וכידוע דמשה ואהרן שניהם בחי' ש' מ\"ה ומשה הוא בחי' מ\"ה דמ\"ה ואהרן ב\"ן דמ\"ה כו', ולהיות דאבא יסד ברתא ע\"כ חשב דחנוכת המזבח צ\"ל ע\"י דוקא להמשיך במל' בחי'\nאור אבא כו', וזהו שחלשה דעתו על שלא הי' עמהם בהחנוכה ולא על עצם הקרבנות שהקריבו שגם הוא הקריב כמה קרבנות משלו כו', רק החנוכה שזהו המשכת האור עליון בבחי' מל' חשב שצ\"ל ע\"י דוקא כו', וא\"ל הקב\"ה חייך שלך גדול משלהם שאתה מדליק כו'. דהנה ידוע ההפרש בין אש המזבח ואש המנורה דאש המזבח הוא בחי' מל' כנ\"ל ושרשו מבחי' ה\"ג דאימא, ולכן הוא בהתלהבות מורגש ברעש כו', והיינו בחי' הרצוא שע\"י ההתבוננות שהוא בבחי'"],[3601331256,"רעש כו', דגם בשרשו בבחי' בינה הוא בבחי' התלהבות ורשפי אש כו' כנ\"ל, אבל אש המנורה הוא בחי' אור כו' והעלי' אינה בבחי' התלהבות והתפעלות כלל והוא בחי' אהבה בתענוגים שזהו מבחי' אור אבא שהוא בבחי' ביטול ממש כו'. וזהו חייך שלך גדול משלהם דגם הקרבת הנשיאים שזהו מבחי' בינה ה\"ז בחי' אה\"ר כו' ובד\"כ הוא בחי' הרצוא דבחי' כלים כו', אבל אתה מדליק ומטיב את הנרות דבחי' אור המנורה הוא הרצוא בבחי' אור שזהו בחי' אה' בתענוגים כו'. אמנם אל מול פני המנורה יאירו שבעת הנרות, פני המנורה היא בחי' מל', והיינו להיות גם המשכת אור זה במל', דתכלית הכוונה הוא להיות הגילוי בבחי' מל', וזהו אל מול פני המנורה יאירו כו'. וזהו בהעלותך את הנרות בחי' אור אבא שזהו הרצוא בבחי' אור ובעבודה הו\"ע אה' בתענוגים כו', אל מול פני המנורה יאירו שבעת הנרות להמשיך האור והגילוי בבחי' מל' כו'."],[3601331257,"<h3>בס\"ד. ש\"פ שלח, העת\"ר</h3>\n<b>שלח</b> לך אנשים ויתורו את ארץ כנען כו', וצ\"ל מהו\"ע שלח לך דלכאו' תי' לך מיותר, גם מהו הל' ויתורו כו'. ובמד\"ר שה\"ש אי' ע\"פ ונתתי אל לבי לדרוש ולתור בחכמה מהו לתור בחכ' לעשות תייר בחכ' הה\"ד ויתורו את ארץ כנען, ד\"א לדרוש ולתור ולהותיר, וא\"כ צ\"ל דמ\"ש ויתורו ג\"כ הוא לעשות תייר ולהותיר, וצ\"ל מה\"ע לעשות תייר בחכ' ולהותיר בחכ', ומה שייכים ענינים אלו כאן במ\"ש ויתורו את ארץ כנען כו'. ולהבין זה ילה\"ק משנת\"ל בענין והחיות רצו\"ש דקאי על האור והחיות אלקי שהוא בבחי' רצו\"ש, ונת' דהרצו\"ש בהאור הוא שהרצוא הוא בבחי' עלי' והתכללות במקורו והשוב הוא בבחי' המשכה כו', וסבת הרצוא הוא מפני שהאור הוא רק הארה לבד שאינו לא עצם ולא אור הכלול בהעצם כ\"א אור היוצא מן העצם ע\"י הנרתק שהוא הצמצום כו', וע\"כ הוא באין ערוך לגבי העצם כו', ומ\"מ הוא בבחי' דבקות בהעצם ומעין העצם כו', ולכן נק' א\"ס ולא אין לו תחלה כי תחלה יש לו להיותו רק הארה לבד רק שהוא בבחי' א\"ס להיותו מעין מקורו כו', וזהו הטעם שיש בו טבע הרצוא כטבע כל דבר\nלהיות נמשך לשרשו ומקורו, וגם להיותו תחלה כלול בהעצם וההתגלות הוא בחי' ירידה לגבי האור והיינו שנעשה בבחי' מציאות כו', על כן הוא בבחי' רצוא לחזור לאין ולהכלל במקורו כו'.\n<b>והנה</b> עוד יש סבה להרצו\"ש של האור והוא בשביל התחדשות האור שיתחדש ממקורו שזהו ע\"י הרו\"ש של האור כו', דהנה נת\"ל (ד\"ה נשא) בענין ההסתלקות וההתפשטות של הדם שזהו בכדי שיתחדש ויתחזק כחו, שאם הי' בבחי' התפשטות לבד הי' הולך בחלישות וע\"י שמסתלק ונסגר בלב עי\"ז מתחדש ומתחזק כחו, וחיזוק זה הוא חיזוק החיות שהולך בכח ועוז יותר כו', וכמו\"כ הוא"],[3601331258,"באור וחיות האלקי שבעולמות שצריך להתחדש תמיד, והוא דלהיות דכללות האור שבעולמות דהיינו אור הקו ה\"ה בא מאוא\"ס ב\"ה דרך הצמצום שזהו שבא בבחי' ריחוק מאוא\"ס כו' (והגם שהקו נוגע ודבוק באוא\"ס מ\"מ זהו דרך דילוג הצמצום כו', וכמ\"ש במ\"א המשל בזה כמו במשפיע ומקבל שאחר שמעלים המשפיע אור שכלו העצמי הרי חוזר ומאיר כו' באופן שהשפעת השכל אל המקבל הוא מ\"מ מאותו השכל שהשכיל לעצמו כו', דעם היותו באין ערוך כו' מ\"מ הוא מאותו השכל עכ\"פ כו' וכמ\"ש במ\"א, ועכ\"ז הוא שבא בדרך הפסק אצל המשפיע כו' והוא שאור שכלו הגם שחוזר ומאיר הוא מ\"מ מתעלם בעצמו ואינו מאיר בגילוי כמו שהי' קודם (ולכן אין אור ההשפעה מתבטל) כ\"א שהוא עומד בדרך מקיף לבד כו', והאור הנשפע נמשך ממנו בדרך דילוג ההפסק כו'), ובפרט בהמשכת האור וירידתו ממדרי' למדרי' שהמדרי' התחתונות מתרחקים מאוא\"ס ב\"ה, וכדאי' בס' הבהיר הובא בפרד\"ס שט\"ו פ\"ד שכינה למטה כשם ששכינה למע' כו', מלה\"ד למלך שהי' לו ז' בנים ושם לכל א' מקומו ואמר להם שבו זה ע\"ג זה, וא' התחתון אני למטה לא\nאתרחק ממך, אמר להם הריני מסבב ורואה אתכם כו', והיינו דמצד הקו שייך מעומ\"ט כמשנת\"ל באורך, וראשית גילוי הקו הוא בחכ' ששם מאיר גילוי אור הקו, אבל בחי' מל' היא בחינה אחרונה שהיא בבחי' ריחוק מאוא\"ס כו' (ומ\"ש ושם לכ\"א מקומו שכן הוא בתחלה בעליית הרצון בבחי' השערה בכח להיות בחי' מעלה ומטה כו'), ואמר התחתון אני לא אתרחק ממך שהרי מצד אור הקו ה\"ה רחוקה יותר כו', והי' התשובה הריני מסבב אתכם כו', והו\"ע מתחת זרועות עולם דהעיגול הגדול שלפני הקו סובב ומקיף כולם (ובפרטי' הוא בחי' עיגול אריך שמקיף הע\"ס כו') דבזה הרי בחי' המל' היא בקירוב יותר כו', ומשו\"ז יש במל' דוקא כח ההתהוות מאין ליש כו' וכמ\"ש באגה\"ק סי' כ'. אמנם מה שיש במל' מבחי' אור הסובב זהו בבחי' העלם במל' ובהאור שבבחי' גילוי בע\"ס הרי המל' היא בבחי' ריחוק ובבחי' מיעוט האור כו', וזהו בחי' החלישות שבהאור בכללותו שהוא בבחי' ריחוק מאוא\"ס ב\"ה וביותר במדרי' התחתונות כו', וה\"ז כמו שפרש\"י ע\"פ ויהי קול השופר הולך וחזק מאד, מנהג הדיוט כל זמן שמאריך לתקוע\nקולו מחליש וכוהה אבל כאן הולך וחזק מאד כו', והוא מהמכילתא, וי\"ל דכמו\"כ בע\"מ שנק' מילין דהדיוטא דבד\"כ הוא בחי' כללות האור שנמשך בעולמות כו' שהאור הולך ומחליש כו', וע\"ה שהחלישות הוא בסוף המדריגות כו' כנ\"ל, מ\"מ זהו הוראה על החלישות גם בתחלת ההמשכה כו', דאם הי' תחלת המשכת האור בחי' אור חזק בעצם (היינו בחי' אור עצמי) הי' בכל מקום בשוה כו', ומה שהוא מתחלש בסוף ההמשכה הוא מפני שגם בתחלת ההמשכה הוא בחי' אור מוגבל שבא בבחי' ריחוק כו'. וכמ\"ש בהבי' דכי ההרים ימושו ההפרש בין בחי' יסוד שבהשתל' לבחי' יסוד שבעצמות דבד\"כ בחי' יסוד הוא שמקשר ומחבר וכמ\"ש כי כל בשו\"א דאחיד בשמיא ובארעא כו', אך בס' השתל' יש כמה יסודות שהן בבחי' התחלקות (וכמשי\"ת בסמוך), אבל וברית שלומי הוא בחי' יסוד דעתיק המקשר ומחבר א\"ס ב\"ה בנאצלים לא תמוט היינו שיומשך גילוי זה מא\"ס ב\"ה גם למטה בעשי' כו', והיינו לפי שזהו אור עצמי ע\"כ נמשך בכ\"מ גם למטה בעשי' כו', וכמשנת\"ל בכ\"ד דאור האצי' רק באצי' הוא בבחי' א\"ס משא\"כ בבי\"ע כו', אבל אוא\"ס\nשלמע' מאצי' בכ\"מ שנמשך הוא בבחי' א\"ס כו' (גם כמשנת\"ל ההפרש בין ב' הקוין לקו האמצעי דב' הקוין יש בהם חילוקי מדרי' משא\"כ קו האמצעי מתחלת המשכתו עד סוף סיומו הוא בכל"],[3601331259,"מקום בשוה כו', והוא לפי שהמשכתו הוא מבחי' פנימי' ועצמו' א\"ס כו'). וכמו\"כ יובן כאן דהחלישות בסוף המדרי' הוא מפני שכללות האור הוא שבא בבחי' ריחוק ובבחי' מיעוט כו' וע\"כ צריכים לחדש את האור כו'. וזהו ובטובו מחדש בכ\"י ופי' הרד\"א שזהו מ\"ש האור כי טוב, וידוע שזהו האור שנברא ביום ראשון שעז\"א במד\"ר בראשית פי\"א ובגמ' חגיגה י\"ב א' אור שברא הקב\"ה ביום ראשון הי' אדם מביט בו מסוף העולם ועד סופו כו', וידוע שזהו שהביטול בכללות העולמות בבחי' עדאת\"כ ועדאת\"ג (שבזה נכלל כללות ההשתל') בשניהם בשוה כו', מפני שזהו האור שלמע' מהשתל' שלא יש בו התחלקות מדרי' כו', כיון שנסתכל כו' עמד וגנזו כו', ואי' בזהר אמור דפ\"ח ולא מנע לי' בכל יומא כו', דאע\"פ שגנזו מ\"מ נמשך ממנו בכל יום דבי' מתקיים עלמא כו', וכ' הרמ\"ז שם שז\"ע ובטובו מחדש בכי\"ת כו', דהאור הגנוז הוא המחדש את האור וע\"י הוא הקיום כו', והיינו כנ\"ל דהאור שבא בהתלבשות בעולמות צריך להתחדש תמיד ועז\"א ובטובו מחדש דבחי' האור הגנוז שזהו האור שלמע' מהשתל' הוא המחדש ומקיים\nכו'. והנה בס' השתל' גופא יש כמה מדרי' שעז\"א ג\"כ ובטובו מחדש כו' כי יש כמה מדרי' טוב כו', דהנה ידוע שיסוד נק' טוב וכמו אמרו צדיק כי טוב כו', והטעם שנק' יסוד טוב כי יסוד הוא בחי' משפיע וכל ענין ההשפעה היא מצד הטוב דוקא דהיינו שטבע הטוב להיטיב לזולתו כו', וההשפעה שמצד הטוב אין לה הפסק כו', ואינו דומה להשפעת החסד שמצד האה' שיש בזה מדה ושיעור דלפי אופן האה' לפי אופן כזה הוא ההשפעה כו', וגם יכול להיות בזה הפסק שהרי האה' היא מצד הטעם וכאשר מתבטל הטעם מתבטל האה' וממילא נפסק ההשפעה כו', אבל השפעת החסד שמצד מדת הטוב אין בזה הפסק כי להיותו טוב בעצם ה\"ה משפיע טוב לכל כו' (ושרש ההפרש בזה דאה' הוא מצד המקבל וע\"כ יש בזה מדה ושיעור והפסק, וטוב הוא מצד המשפיע שאין בזה הגבלה והפסק כו'), ולכן נק' היסוד טוב דלהיות היסוד הו\"ע השפעה שזהו מצד הטוב כו'.\n<b>ובאד\"ר</b> דק\"ל ע\"א דיוסף נק' טוב עין שנא' טוב עין הוא יבורך משום כי מלחמו נתן לדל שהשפיע לכל, וכמ\"ש ויוסף הוא המשביר כו' ויכלכל יוסף כו', ומבו' שם דטוב עין הוא בחי' עין דעתיק עינא פקיחא דלא נאים כו', דמאשגחותא דהאי עינא מתזנן כולהו כו', דכללות ההשתל' מתזנן מהאי עינא בחי' טוב עין שמשם מקור ההשפעה כו', וזהו בכללות דטוב, ובפרטיות יש בזה כמה מדרי' וכמ\"ש מרב כל דכל הוא בחי' יסוד ונק' כל מפני שכל המדרי' מתכללים ביסוד ונשפעים ע\"י היסוד כו', ויש ריבוי מדרי' כל כו', וכמו\"כ יש ריבוי מדרי' טוב וכמו זכר רב טובך יביעו ריבוי בחי' טוב כו' והן ט\"ו יסודות שבחמשה פרצופי' שבכל עולם כו', והן ט\"ו ווי\"ן דאמת ויציב דבווי\"ן תתקטר דיסוד מקשר ומחבר וכמ\"ש כי כל בשוב\"א דאחיד בשמיא ובארעא כו', וההתקשרות היא המשכה וז\"ע בווי\"ן תתקטר כו', והט\"ו ווי\"ן הן הט\"ו יסודות שבהחמשה פרצופים שבכל עולם דבכל פרצוף יש ג' יסודות. וביאור ענין הג' יסודות שבכל פרצוף הנה כל הוא בחי' יסוד כנ\"ל, וכל עולה חמשים והן נ' שערי בינה\nדשערי בינה הן בבחי' המשכה מבינה, וכמו השער שמשמש כניסה ויציאה והיינו בחי' העלאה והמשכה, וכמו לך ה' הגדולה והגבו' כו' שזהו העלאת המדות בבחי' בינה, וכי כל בשו\"א הוא ההמשכה מבחי' בינה דהכל הוא דרך השערים כו', ויש השערים בשכל גופא וכמו שנמשכים"],[3601331260,"בלב וכמו הלב מבין דמה שבהלב נרגש מבחי' המוחין ה\"ז ע\"י השערים כו', ובד\"כ הן מדות שבשכל, ולהיות שהן ז\"מ וכ\"א כלול מז' ה\"ה מ\"ט שערים ושער הנו\"ן הוא הכולל כולם כו', והמשכה זו הוא במדות שבשכל וגם במדות שבלב כו', וז\"ש בזהר נודע בשערים בעלה כחו\"ח לפום שיעורא דילי' לפום מה דמשער בליבי', דהיינו לפי אופן השער וההמשכה מבינה והיינו לפי אופן השגתו והרגשתו בלב, לפי אופן כזה הוא העבודה וההתקשרות שלו כו' (והגם שהן רק נו\"ן שערים ולפמ\"ש בזהר כחו\"ח לפום מה דמשער כו' ה\"ה בריבוי התחלקות מאד, הענין הוא דמה שהן נו\"ן שערים זהו בההמשכה מבינה למדות ואח\"כ בהמדות מתחלק לריבוי מדרי' כו', וכידוע דהז\"מ כלולים מיו\"ד ויו\"ד מיו\"ד עד ס' רבוא שהן שרש ס\"ר נשמות דבכאו\"א הוא המשכה מיוחדת כו', וזהו דנודע בשערים בכחו\"ח לפום מה דמשער בליבי' כפי שרשו ומקורו בבחי' ז\"א דאצי' כו', וכללות כולם הן הנש\"ב כו'), וזהו עיני כל אליך ישברו דכחו\"ח לפום ש\"ד אליך ישברו כו'. והנה בזהר ואתחנן דרס\"ב א' בענין ד' בתים דתפילין אי' ביתא תנינא והי' כי\nיביאך אר\"י מוחא דתרעוהי נפקין לחמשין תרעין כו', וידוע דפ' והי' כי יביאך הוא בינה כו' וממ\"ש מוחא דתרעוהי נפקין משמע דמוח הבינה עצמו נבדל בערך משערי בינה רק דממוח הבינה יוצאים נו\"ן שערים כו', ועד\"מ שערי ההיכל שאינם ההיכל עצמו רק שע\"י נכנסים מן החוץ אל ההיכל וכן ע\"י יוצאים מבפנים לחוץ כו', והיינו למע' בחי' המשכת האור והגילוי שא\"ז העצמות ממש כו'. והענין דהנה בחי' בינה הוא עצם השכל כמו שהוא דהיינו השגת הדבר בעצם המושג שלו בלתי ימצא בו עדיין פתח והטי' לדון ממנו איזה מדה ושכל המטה כלפי חסד או כלפי דין כו', כי הוא למע' עדיין מבחי' המדות כו' (וכמו בהתבוננות אלקי בעצם ההשגה בגדולת ה' או ברוממות הא\"ס כשמעמיק שכלו בעצם הענין ה\"ה למע' מבחי' התפעלות אה' גם בהעלם בשכלו, רק הוא בבחי' דבקות בעצם הענין האלקי שנדבקה נפשו בכח השגתה שמשגת באלקות כו', וכ\"ה בכל ענין שכלי כשהוא עמוק בעצם הענין ה\"ה למע' מאיזה הטי' אל המדה הבאה מזה כו', הגם שבכל שכל יש מדה כנודע שזהו בהכרח שיש איזה מדה בכל השגה שכלי' (ולכן בכל\nהשגה צ\"ל איזה עבודה הבאה מהשגה זו וכמ\"ש במ\"א) ה\"ה שם לא בבחי' מציאות כלל כו', ובשעה שהוא בעצם השכל ה\"ה למע' מהמדות כו'), וגם בהסברות שבהשכל שיש סברות נוטות לכאן ולכאן, וכמו באיזה פלפול שיש כמה סברות שיכולים לומר כך ויכולים לו' כך, הרי הכל הוא בעצם השגת הדבר שיכולים להבינה באופן כך היינו ע\"פ טעם וסברא כזו ויכולים להבינו בטעם וסברא כזו, ה\"ז ג\"כ למע' מהמדות מפני שהכל הוא עדיין בהשגת הענין כו', וגם הרי לפי הסברות שונות משתנים המדות הבאים מזה וא\"כ כ\"ז שהוא בפלפול הסברות אינו יכול לבא עדיין אל המדה כו', וגם מצד ההשגה ה\"ה למע' מהמדות עדיין כו' (וזהו שהטיית השכל לחסד ולדין הוא ע\"י הדעת הנק' דעת נוטה כו', כי הדעת הוא הכרעת הענין באופן כך או כך ומזה בא אח\"כ לידי מדה כו', וגם שהדעת מטה את השכל להיות בבחי' שכל הנוטה כלפי חסד או כו', דהשכל וההשגה עצמה היא למע' עדיין מהטיית המדות כנ\"ל והדעת מטה את השכל לבא לידי מדה כו'), וכאשר נפתח מן השכל וההשגה פתח לדון עפ\"ז לזכות או לחוב נק' שכל המטה כלפי חסד או כו', ופתיחה זו נק' שער שזהו ירידה מעצם"],[3601331261,"השכל שבא לידי הטי' למדה כו' (וכנ\"ל דכשהוא בעצם ההשגה ה\"ה למע' ממדות כו'), ומ\"מ ההמשכה היא ההשגה עצמה שבאה בבחי' הטי' והמשכה כו', וכמו כאשר מהשכל והסברא בא לידי פסק דין (ע\"י דעת נוטה) באופן כך וכך ה\"ז הטיית והמשכת ההשגה שבשכל אל המדה כו', אבל אינו בבחי' התפעלות המדה היינו שמתפעל בהמדה עצמה בחסד או בדין כ\"א הוא הטיית השכל שמחייב החסד או הדין כו'. וע\"ה שזהו ירידה מעצם ההשגה כנ\"ל וה\"ז יציאת השכל דרך שער לחוץ מעצם ההשגה שבא לידי מדה כו', מ\"מ הרי א\"ז שנעשה מזה מדה והתפעלות שהוא מהות אחר מן ההשגה, כ\"א שזהו מה שההשגה באה בבחי' מדה כו', וה\"ז יציאה פנימי' עדיין שלא יצאה עדיין לחוץ להיות מזה מהות אחר דהיינו התפעלות מדה כו', וכמו בהשגת הנשמות בג\"ע שמשיגים אלקות ונהנין מזיו השכינה כל חד לפום שיעור מדריגתו אם הוא מבחי' החסד או מבחי' הגבו' כו', דכל נשמה יש לה שרש ומקור ומיוחד במדות עליונות וכידוע שהנשמות מושרשי' בז\"א דאצי' כו' (וי\"ב שבטים הן י\"ב גבולי האלכסונין כו' וכמ\"ש ששם עלו שבטים שבטי י\"ה כו'\nוכמ\"ש במ\"א), וג\"ע הוא בחי' בינה כנודע (ובפרטיו' הוא בחי' בינה שבמל' כו'), ונמשך ההשגה בכל נשמה לפי מדריגתה כו', וכמו בהשגת הנשמות למטה שמחולקים הם בהשגתם בבחי' חו\"ג, וכמו ב\"ש וב\"ה דהשגת ב\"ש הי' בהטי' לגבו' וב\"ה הי' הטיית השגתם לחסד, כמו\"כ הוא בהשגת הנשמות בג\"ע שכל נשמה השגתה הוא לפי אופן שרשה אם בבחי' חסד או בבחי' גבו' כו', והרי הכל הוא השגה לא מדה רק שההשגה היא כפי אופן שרשה בחו\"ג כו', וכמו המחלוקת דב\"ש וב\"ה בכללות ענין העלי' דנש\"י שנחלקו בענין הריקוד לפני הכלה, שזהו מה שנש\"י נק' כלה על שם כלתה נפשי כו', דבש\"א כלה כמות שהיא דהיינו בדרך מלמטלמ\"ע ובה\"א כלה נאה וחסודה ואפי' היא חיגרת כו' שזהו בדרך מלמעלמ\"ט כו' וכמ\"ש בלק\"ת בסופו על מא' זה, שכ\"ז הוא ההשגה באופן העבודה כללי' אם באופן כך או כך כו' (וכמו שהם וישפה דפליגי בזה תרין מלאכיא ברקיע ותרין אמוראי במערבא כו' וכמ\"ש בלק\"ת ד\"ה ושמתי כדכד כו').\n<b>אמנם</b> מה שנמשך מן השכל להתפעל באיזה מדה באה' או ביראה הרי המדה היא מהות אחר מן השכל וכמשנת\"ל (ד\"ה ושבתה הארץ) דמוחין ומדות הן מהותים נבדלים זמ\"ז, וא\"כ מה שמהשכל מתפעל בהמדה ה\"ז יציאה לחוץ מעצם השכל וההשגה כו', וא\"ז דומה לשכל המטה כלפי חסד שהעיקר הוא השכל ומאיר בזה גילוי אור השכל רק שמטה כלפי המדה כו', דמ\"מ הרי עיקר מעמדו בזה הוא בהשכל וההשגה לא בעצם המדה, שאינו עומד בהתפעלות המדה כ\"א עומד בהשכל המחייב את המדה כו', אבל בהתפעלות המדה הרי יצא מכלל שכל ובא לידי מדה ורק הארת השכל הוא בהמדה כו', ובזה יש ב' מדרי' הא' ההמשכה במדות שבשכל והיינו כמו שמהשגת המוח מתפעל בשכלו באה' או ביראה כפי אופן ההשגה כו', והב' ההמשכה במדות שבלב שמתפעל באהוי\"ר בהתגלו' הלב כו', שז\"ע שערי בינה שהן היציאה מהמוחין לחוץ מעצם מהותן להיות בחי' התפעלות המדות כו', ועיקר היציאה לחוץ מן המוחין הוא במדות שבהתגלות הלב, כי המדות שבשכל הרי אינן מדות מורגשות עדיין כו', וגם המדות שבשכל ה\"ז מה שמתפעל על עצם הטוב דאלקות\nומדות שבלב הוא שמתפעל על הטוב שלו היינו מה שקרבת אלקי' לי טוב כו' וכמשנת\"ל, וא\"כ מה שמהות המדות הוא הרגש"],[3601331262,"עצמו זהו במדות שבלב דוקא והן עיקר המהות הנבדל מן המוחין כו', וע\"כ בחי' השערים שהן בבחי' יציאה לחוץ העיקר הוא בההמשכה במדות שבלב כו'. וזהו ג' יסודות בפרצוף הבינה הא' המשכת ההשגה עצמה בבחי' הטי' כלפי חסד כו', הב' המשכת ההשגה להיות התפעלות המדות רק במדות כמו שהן כלולין בשכל עדיין, והג' ההמשכה במדות שבלב שהו\"ע בינה ליבא ובה הלב מבין כו', וכ\"ה בכל פרצוף שיש בו ג' יסודות והן הא' המשכת הכח עצמו (והוא ג\"כ רק הארת הכח ההוא לא עצם הכח ממש, וכמו שכל המטה כלפי חסד שאינו עצם ההשגה ממש מ\"מ הוא בכלל ההשגה עדיין כו'), והב' כמו שממנו מתעורר מהות כח אחר רק שעדיין כלול בו כו', והג' כמו שבא בכח מובדל ממנו כו', וכמו ברצון שרוצה להתחכם ועדיין לא יש התעוררות ההתחכמות כו', והב' כמו שמתעורר להתחכם בכח הרצון והוא עדיין בכח השכל הכלול בהרצון כו' והיינו שכח השכל עומד להתחכם טרם שמתחכם עדיין כו', והג' כמו שבא בהתחכמות בפועל כו'. וזהו ריבוי מדרי' טוב היינו ריבוי היסודות כו', וזהו ג\"כ ובטובו מחדש שהוא ההמשכה ממדרי'\nהעליונה, שהרי הפרש גדול בין המדרי' הראשונה שבהיסוד שבכל פרצוף שהוא רק המשכת אותה המדרי' עצמה, ובין שהיא לעורר המדרי' שהיא מהות אחר ממנה ובפרט בההמשכה להיות התגלות המהות האחר כו', וע\"כ ההעלאה וההמשכה בבחי' יסודות הנ\"ל ה\"ז ג\"כ התחדשות כו'. אמנם הרמ\"ז פ' פקודי דר\"ך ע\"ב כ' דיסוד אבא בחי' אצי' שבו גנוז ובי\"ע שבו מאירים בזו\"נ כו' ובחי' בי\"ע הן בחי' בינה וזו\"ן ואצי' הוא בחי' חכ' שבחכ' כו', וי\"ל דג' יסודות הנ\"ל שבכל פרצוף זהו בי\"ע שבו ואצי' הוא בחי' החכ' שבכל פרצוף והוא בחי' אור הגנוז כו'. והענין הוא דהנה בבינה הן בחי' שערים שערי בינה ובחכ' הן נתיבות ל\"ב נתי' פליאות חכ' כו', והנה שער עשוי לרבים דוקא שהוא פתוח פתח רחב שיצאו ויכנסו בו כל מי שירצה כקטן כגדול כו', כך בחי' שערים דבינה הכל נכנסים והכל יוצאים בהם כו', וכמו בהשגה אלקי' הכל יכולים להשיג כל חד לפו\"ש דילי' כו' שעז\"נ נודע בשערים בעלה שנודע בכחו\"ח לפום מאי דמשער בליבי' כו', כי כל השגה אפי' היותר קטנה ה\"ה השגה כו', וכמו שערי ג\"ע שהנשמות\nנכנסים שם גם הקטן שבקטנים יש לו כניסה שם לפ\"ע כלי השגתו המצומצם כו', והיינו לפי שהשערים דבינה הוא שהאור האלקי מתפשט ומתצמצם להשפיע השגת אלקות שכל מי שירצה להשיג יוכל להשיג כו', שהרי כללות ההשתל' הוא בגין דישתמודעון בי' וידוע דעיקר התחלת ההשתל' הוא מבינה כו' ומוחין דאבא הן למע' מהשתל' כו', וע\"כ שערי בינה הוא מה שהאור האלקי מתצמצם להיות בבחי' השגה לכל מי שרוצה להשיג לכל חו\"ח לפו\"ש דילי' כו'. וזהו שכל הנבראים אומרים שירה וכמבו' בפרק שירה שירת כל הנבראים בפרט לפ\"ע השגתם באור המצומצם כו', וכמו נשמו' דבי\"ע עד נפש דמל' דמל' דעשי' ומלאכים עליונים עד הגלגלים ומזלות רוחני' שהן רוחני' דהד\"י הגשמי' כו', והן מחיצוני' דחיצוני' הכלים דמל' דמל' דעשי' כו', כולם יש להם השגה באלקות כאו\"א לפי ערכו ואומרים שירה שמהללים ומשבחים כו'. אבל הנתיבות דחכ' בלתי מתפשטים בעולמות ולא יכנסו בהם רק הנשמות הגבוהות ביותר, וכמו נשמת הג' סבות ונשמות רשב\"י ורע\"ק ור\"א הגדול שהן ממדרי' משה שזכה לשער הנו\"ן שנק' שביל דקיק דבי' עייל אבא לאימא כו', שהוא בחי' האין דכח מ\"ה"],[3601331263,"דחכ' שאינו בא לכלל השגה דבינה כו', וה\"ז עד\"מ הנתיב שהוא קצר ומוצנע ולא נודע הילוכו רק למקצת יחידי סגולה בעיר ההולכים בסתרי העיר כו', והו\"ע נתיב לא ידעו כו' שגם המלאכים אומרים אי' מקום כבודו דאי' בת\"ז שהו\"ע נתיב לא ידעו עיט ולא שזפתו כו', שהנתיבות נעלמים מהם רק לנשמות הגבוהות הן נשמות דאצי' דידעין רזא דביתא כו'. וזהו בחי' אור הגנוז שנסתר ונעלם מכל הנבראים ונגנז לצדיקים הגדולים שהן בבחי' אצי' כו', ולעתיד יהי' גילוי אור זה לכל הנשמות המקיימים תומ\"צ (שזהו בד\"כ בחי' אצי' שבעולמות וכמו אורייתא מחכ' נפקת כו', ונק' תורת הוי' ומצות הוי' כו'), ומ\"מ הארה מזה יש גם עכשיו וכמ\"ש בזהר ולא מנע מיני' בכל יומא כו' כנ\"ל, וז\"ע ובטובו מחדש כו' דבחי' הטוב זהו בחי' אור הגנוז הנ\"ל וכמ\"ש הרמ\"ז שם, והוא המחדש את בחי' האור הנמשך בעולמות שמתחדש מבחי' האור הגנוז כו'. וענין ההתחדשות הנה עד\"מ כמו בהתחדשות החיות שבדם הוא שיתפשט בכח ועוז כו', כמו\"כ י\"ל ענין התחדשות האור שהרי האור המצומצם הוא שנמשך ע\"פ קו המדה שמתמעט\nומתעלם ממדרי' למדרי' כו', וכללות הגילוי הוא האור כמו שבא בהתלבשות הצמצום שהוא בבחי' יש כו', וההתחדשות הוא שנמשך האור כמו שהוא בבחי' אין והיינו כמו שהוא למע' מבחי' הצמצום כו' ואינו מתמעט ממדרי' למדרי' שנמשך כמו שהוא בעצם כו'. והענין הוא דכמו שנת\"ל דאור הגנוז הוא בחי' אצי' י\"ל דבשרשו זהו בחי' אצי' דכללות שהוא בחי' האוא\"ס שלפה\"צ כנודע, וא\"כ גילוי בחי' אור הגנוז הוא גילוי אור שלמע' מהצמצום וכמו שהאור הוא בחי' אין כו', והמשכת האור הזה הוא שנמשך בכ\"מ שלא ע\"פ מא' קו המדה כו', ובפרט לפי המבו' בכ\"מ דאור הגנוז הוא בחי' כתר וכמ\"ש אשר צפנת ליראך צפנת בגימ' כתר כו', ובשרשו י\"ל שזהו בחי' העלם עצם האור כו' והיינו בחי' הוא שלמע' משמו כו' וכמשנת\"ל (ד\"ה בהעלותך), דאור זה נמשך בכ\"מ בלי שום חילוקי מדרי' כו', וכמו בחי' יסוד שבעצמות דוברית שלומי לא תמוט שנמשך עד למטה מטה כו'. ולפ\"ז י\"ל דאור הגנוז הוא בחי' יומם יצוה ה' חסדו יומא דאזיל עם כולהו יומין והוא בחי' אור החסד דאריך שאינו מתעבה והוא שוה למטה כמו למע'\nכו', וז\"ע ההתחדשות שהאור המצומצם מתחדש מן האור הגנוז שיהי' הגילוי גם למטה בעשי' כו', וזהו ההתפשטות בכח שיהי' הגילוי גם למטה כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש שלח לך אנשים ויתורו, דהנה כתי' וראיתי אני שיש יתרון לחכ' מן הסכלות כו', דיתרון החכ' הוא מן הסכלות דוקא שע\"י בירור הסכלות דוקא נעשה יתרון בחכ' כו', וכמו ותרב חכמת שלמה מכל חכמת בני קדם דמחכ' בני קדם מזה ותרב כו' וכמ\"ש במ\"א, והיתרון בחכ' היינו גילוי בחי' עצמות החכ' כמו שהיא למע' מהשתל' וגם גילוי בחי' הכתר בחכ' שהוא בחי' אור הגנוז כו', וזהו ג\"כ ענין ויתורו את ארץ כנען ל' יתרון וכמו ויתרון ארץ בכל הוא כו', להיות יתרון אור ע\"י הבירור דבחי' ארץ דעשי' בפו\"מ שעי\"ז נמשך האור הגנוז להיות הגילוי למטה כו', ובעבודה הו\"ע קיום מצות מעשי' דכל המצות מלובשים בדברים גשמי' שעי\"ז נעשה הבירור שלהם, וכמו האתרוג כשעושין אותו למצוה ה\"ה מתברר עי\"ז וגם עושה הבירור בכללות מין הצומח כו' (וכמ\"ש בסש\"ב פל\"ד בענין הקרבנות), וכן בקלף התפילין וצמר דציצית כו', וגם שנעשה"],[3601331264,"עי\"ז בירור דנה\"ב, ובפרט במצות צדקה שנעשה בירור כללות דנה\"ב שהרי הריווח בא ע\"י היגיעה בכל כחות נפשו, וגם הי' יכול לקנות בזה דבר לחיי נפשו החיונית וכשנותן לצדקה ה\"ז בירור כללות נפשו החיונית כו' וכמ\"ש בסש\"ב פל\"ז, וכן בכל מצוה יש בזה כפי' פרטי' דנה\"ב וכמו בתפילין לשעבד הלב והמוח כו', וז\"ע מעשה גדול שע\"י מעשה המצות ממשיכים בחי' גדול ה' היינו בחי' אור א\"ס שלמע' מהשתל' כו'. אמנם בכדי שיהי' הבירור ע\"ז צריכים המשכה מלמע' כי הבירור הוא מש' ב\"ן וצריכים המשכה ע\"ז מש' מ\"ה להיות הבירור כו', וכמו שההעלאה מלמטלמ\"ע הוא ע\"י המשכה מלמע', וכמו לכה דודי לקראת כלה דשבת הוא העלאת כל הבירורים שעולים למעלה כמשי\"ת, ע\"ז צ\"ל תחלה המשכה מלמע' כו', וכמו\"כ בכדי להיות הבירור זהו ע\"י המשכה מלמע' כו', וע\"ז שלח משה לתור את הארץ דמשה הוא בחי' מ\"ה והיינו להמשיך מבחי' ש' מ\"ה להיות בירור הארץ ועי\"ז יהי' היתרון אור כו'. וענין לתייר הוא כמו שא' בגמ' ב\"ק דקט\"ז ע\"ב ואם שכרו תייר ההולך לפניהם ופרש\"י מראה להם הדרך, וי\"ל שזהו להיות\nההמשכה מלמעלמ\"ט, דהנה משה רצה לפעול בנש\"י שיהי' בהם עבודה בדרך מלמעלמ\"ט וע\"ז בקש לראות את הארץ אעברה נא ואראה כו' כנודע, שע\"ז צריכים תחלה ההמשכה מלמע', וכמו חנוך לנער שצריך תחלה החנוך ע\"י גדולים ואח\"כ ילך מעצמו כו', וכמו\"כ צ\"ל תחלה ההמשכה מלמע' בכדי שיהי' בנש\"י העבודה באופן כזה בבחי' המשכה מלמעלמ\"ט כו', וזהו לתייר בחכ' להיות שזהו מבחי' ראי' דחכ' כו' כנודע, וכ\"ז הי' צ\"ל ע\"י משה דוקא בחי' ש' מ\"ה כו'. וזהו שלח לך אנשי משה דוקא שימשיכו את האור מלמע' וגם ליתן כח על בירור הארץ כו', וזהו שלח לך אנשים ויתורו כו' דהכוונה הוא לעשות תייר בחכ' בבחי' המשכה מלמעלמ\"ט וגם לעשות יתרון להמשיך האור שיהי' הגילוי למטה כו', וע\"כ שלח לך אנשי משה דוקא, ועי\"ז ויתורו להיות ויתרון ארץ בכל כו'."],[3601331265,"<h3>בס\"ד. ש\"פ קרח, העת\"ר</h3>\n<b>ויקח</b> קרח בן יצהר בן קהת בן לוי, וצ\"ל מהו\"ע ויקח קרח מה לקח. גם צ\"ל מפני מה לא חס על כבוד אבותיו הקדושים ומזכיר אותם על מחלקותו, הלא יעקב אינו נזכר כאן משום ובקהלם אל תחד כבודי, ולמה מזכירים אבותיו אלו. והנה רש\"י הביא בשם המדרש מה כתי' למע' מהענין ועשו להם ציצית לקח קרח טלית שכולה תכלת ובא לפני משה ואמר זו חייבת בציצית או פטורה א\"ל חייבת בציצית, התחיל לשחק עליו ומה טלית של מין אחר חוט א' של תכלת פוטרה זו שכולה תכלת לא תפטר עצמה, וצ\"ל מה שייכות זה למחלוקתו שהוא חלק על הכהונה מה שייך לזה ענין טלית שכולה תכלת אם פטורה או חייבת בציצית כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דוהחיות רו\"ש קאי על האור האלקי המחי' את"],[3601331266,"העולמות שהוא בבחי' רו\"ש, ונת' הטעם שזהו בשביל התחדשות האור ממקורו דהאור הנמשך בעולמות צריך להתחדש מפני שהוא בבחי' חלישות היינו בבחי' מיעוט האור כו', כי להיות שבא ע\"י הצמצום ה\"ה בבחי' ריחוק ממקורו משו\"ז הוא בבחי' חלישות ומיעוט כו', ולכן בהמשכת האור ממדרי' למדרי' הנה במדרי' התחתונות האור הוא בבחי' מיעוט וזהו מפני שכללות האור הוא בבחי' חלישות ומיעוט כו', וע\"כ צריך להתחדשות ועז\"נ ובטובו מחדש בחי' האור כי טוב בחי' אור הגנוז שזהו אוא\"ס שלמע' מהשתל' שעי\"ז מתחדש האור דס' השתל'. וענין ההתחדשות נת' שזהו בחי' הכח והעוז בהאור להיות בגילוי גם למטה, דהאור מצ\"ע הרי יש בו חילוקי מדרי' ובמדרי' תחתונות הוא בבחי' מיעוט לגמרי, והתחדשות הכח שיהי' גם למטה בעשי' כו'.\n<b>אמנם</b> בכדי שתהי' ההתחדשות זהו ע\"י הרצוא, שע\"י הרצוא בכל המדרי' הנ\"ל הן בנשמות ונבראים בכלל והן בכלים ואורות כו', ה\"ה מתחדשים באור וחיות חדש שזהו בחי' השוב כו', וכמו התחדשות חיות הדם הוא ע\"י שהדם עולה ונתעלם בהלב שעי\"ז מתחדש חיותו מהרוח חיים שבלב להיות התפשטותו בכח כו', כמו\"כ ברוחני' ההמשכה בבחי' שוב זהו ע\"י הרצוא תחלה כו', והטעם הוא כי האור הנמשך צריך להיות לו דבר על מה שיחול ושיהי' דבר הראוי לקבל את האור כו', וזהו שע\"י הרצוא נעשה המקבל בבחי' כלי הראוי לקבל כו', דהנה האור הרי נתרחק ממקורו ובא בבחי' הגבלה בבחי' מציאות דבר כו' וכמשנת\"ל, וממילא ה\"ה באין ערוך לגבי האוא\"ס שלמע' מהשתל' כו', וענין הרצוא הוא בחי' הביטול בהאור כו' ועי\"ז מתחדש בבחי' אור חדש להיות בו תוקף ההמשכה כו' כנ\"ל, וכ\"ש שהוא כן בבחי' הכלים ובנבראים שצ\"ל בהם הביטול שעי\"ז דוקא נמשך האור לחדש אותם כו'. וביאור הענין יובן עד\"מ בגשמיות הרי הדם נעשה מהמאכל שאוכל שמתברר באצטומכא שהפסולת נדחה לחוץ ומהמובחר נעשה דם שמתברר\nתחלה בכבד ועולה המובחר ללב כו', והיינו שמתברר הדם ונעשה זך ונקי וגם דק בעצם מהותו להיות חומר דק שיהי' כלי לקבל את הרוח חיים שבלב כו', והוא החיות הנמשך מהמוח אל הלב כו' וכמשנת\"ל (ד\"ה נשא). וכמו\"כ הוא ברוחני' עבודת האדם בעבודה דתפלה שהוא בירור וזיכוך הנה\"ב לזככו מחומריותו ולנקות הסיגים והפסולת שבו כו', דהנה\"ב הוא מקלי' נוגה שמעורב טו\"ר, והטוב שבנה\"ב הוא הכח המתאווה שבו שאינו רע בעצם, דגם בדברים הגשמי' שמתאווה בהם רק לקיום גופו לא למלאות תאוות נפשו א\"ז רע, והוא טוב שבנוגה כמ\"ש בסש\"ב ח\"א פ\"ז, ובהכח המתאווה יכול לרצות אלקות כו', והרע הוא התאוה רעה שזהו הציור שבו הנק' יצה\"ר, והיינו מה שמתאווה בזה למלאות תאות נפשו שזהו רע, ולאו דוקא בדברים האסורים שזהו רע גמור מגקה\"ט, אלא אפי' בדברים המותרים מה שהוא רוצה למלאות תאות נפשו ה\"ז רע כו', וזה צריכים להפריד ולדחות לגמרי, וע\"ז הוא עבודת האדם להפריד הרע שבנה\"ב ולנקותו מסיגים ופסולת שלא תהי' התאוה רעה, והטוב שבו יתעלה היינו שבכח המתאווה ירצה באלקות כו',\nולהיות שהכח המתאווה הוא חומר עב וגס, הנה בכדי שיהי' כלי לאור אלקי צריכים לזככו מחומריותו, וזהו ע\"י העבודה וע\"י שקידת העבודה, וכמשנת\"ל (ד\"ה במד\"ס) דע\"י התעסקות במושכלות מזדכך חומר המוח"],[3601331267,"כו', וכן ההשגה מזדכך ע\"י עסק המושכלות כו', כמו\"כ ע\"י העבודה שהנה\"ב יבין ענין אלקי, וע\"י שקידת העבודה בזה, ה\"ה מזדכך מחומריותו להיות כלי לאור אלקי היינו שיאיר בו אור הנשמה ואור אלקי כו'. וזהו מ\"ש אכלתי יערי עם דבשי יערי יוצ\"א שהוא ההתבוננות בביטול המלאכים שרפים ואופנים כו', איך שהשרפים אומרים קדוש שעומדים ברצוא ותשוקה גדולה להכלל בעצמות אוא\"ס עד שכל מהותם נשרף ברצון זה כו', והאופנים וחיוה\"ק ברעש גדול אומרים ברוך שרוצים להיות המשכת אלקות למטה כו', ובד\"כ כולם עומדים ברום עולם בתכלית הביטול לאלקות כו', ועי\"ז נעשה הזזה גדולה בנה\"ב להיות בו ג\"כ הביטול כו', וה\"ז כמשל איש המוני כשרואה את המלך הנה להיותו המוני אינו מבין כ\"כ גדולת המלך כ\"א ממה שרואה שרים רבים ונכבדי ארץ שכורעים ומשתחוים לפני המלך ובטלים אליו עי\"ז תפול עליו ג\"כ אימה ופחד מגדולת המלך כו', וכמו\"כ הוא ע\"י ההתבוננות איך שהמלאכים שמופשטים מהגשם ומשיגים אלקות איך שהם בטלים ומקדישים ומעריצים כו', עי\"ז נופל אימה ופחד גם על הנה\"ב כו',\nובפרט אשר שרשו ומקורו הוא משמרי האופנים, וע\"כ ההתבוננות בביטול שרשו ומקורו ה\"ז עושה הזזה גדולה בנה\"ב כו'. וזהו אכלתי יערי דמלאכים נק' עצי היער וכמ\"ש אז ירננו עצי היער דקאי על המלאכים כו', והוא ההתבוננות בביטול המלאכים כו', ועם דבשי הוא ק\"ש שהוא בבחי' ביטול פנימי כו', והעיקר הוא בהביטול דנה\"א שהוא בחי' המתיקות והעונג בההשגה ובהאוי\"ר כו', אך כמו\"כ הוא ביטול הנה\"ב שנעשה ע\"י השגה והתבוננות אלקי (לא רק מביטול המלאכים) שמשיג הענין האלקי ומתבטל עי\"ז בבחי' ביטול פנימי כו', ואו' ע\"ז אכלתי יערי שזהו כמשל האכילה שמהמאכל נעשה דם ומתברר מכל סיג ופסולת ומזדכך מחומריותו עד שנעשה כלי להחיות כו' כנ\"ל, כמו\"כ הוא בתפלה העבודה לברר ולזכך את הנה\"ב עד שיהי' כלי לאלקות כו'. וקודם לזה כתי' אריתי מורי עם בשמי, ופי' מורי הוא ל' מרירות והיינו מה שמתמרמר על ריחוקו מה' ועל גלות נפשו כו' וכמשנת\"ל (ד\"ה וכל העם רואים), והוא הכובד ראש שקודם התפלה שעי\"ז נעשה הפרדת הרע הגס ודחיית הרע כו', וכן בשעת התפלה שאז מכיר יותר את\nפחיתותו כי בהיותו יותר קרוב לה' מכיר יותר את ריחוקו כל היום כו', וגם שאז נרגש גם דקות הרע, שז\"ע מה שאומרים סלח לנו בשמו\"ע דלכאו' מהו המקום לזה בשמו\"ע שהוא בתכלית העלי' לומר אז סלח לנו כו' והול\"ל זה קודם התפלה כו', אך הענין דקודם התפלה כל דרך איש ישר בעיניו דכאשר לא עבר עבירה בפו\"מ ועוד עשה מצוה או עסק בתו' נדמה לו שהוא קרוב לאלקות, אבל כאשר מתחיל לעלות במעלות התפלה אז הוא רואה איך שהוא מרוחק כו', וזהו דבשמו\"ע דוקא בהיותו בתכלית הקירוב אז מרגיש יותר את הריחוק גם בדקות ומתמרמר ע\"ז ונעשה עי\"ז דחיית הפסולת, וכידוע בענין תרומת הדשן כו'. ובכ\"ז הוא שמתברר הנה\"ב עד שיהי' כלי לאלקות כו', וכמו המאכל שנתברר ונעשה דם זך ונקי הראוי לחיות הנפש כו', כמו\"כ הנה\"ב מתברר ע\"י הנה\"א להיות כלי לאלקות כו', וכן גם הדברים התחתונים שהאדם מקבל חיות מהם וכמו המאכל הגשמי וכה\"ג כאשר האדם מתפלל בכח זה ה\"ז נכלל באלקות כו', ועי\"ז מתחדש האדם באור וחיות חדש בגילוי אור עליון שמאיר בו גילוי אור הנשמה וגילוי אור האלקי כו', דבתחלה הוא"],[3601331268,"בבחי' העלם בהאדם כו', וע\"י העבודה בבירור וזיכוך הנה\"ב מאיר בו גילוי אור כו'.\n<b>וכשם</b> שהוא בהאדם בפרט כ\"ה בהעולמות בכלל שע\"י העלי' דעולמות בי\"ע שעולים באצי' עי\"ז נמשך בהם תוס' אור מבחי' אצי' ומלמע' מאצי' כו', וכידוע בענין השבת שהוא עליית העולמות שז\"ע ג\"פ הבו לה' שאומרים בקבלת שבת שזהו עליית עולמות בי\"ע כו', ואומרים השתחוו לה' כו' שזהו עלייתם באצי' כו' ומאיר גילוי אור האצי' בבי\"ע כו', וכמשנת\"ל (ד\"ה על ג' דברים) בענין ביום השביעי נתעלה וישב כו', וגם למטה בבי\"ע מאיר בשבת גילוי אור עליון יותר וכידוע דגם חיצוני' העולמות מקבלים בשבת חיותם מבחי' המח' כו' וכמ\"ש במ\"א, ובפנימי' הגילוי בשבת הוא שמאיר בחי' התענוג וכמ\"ש וקראת לשבת עונג כו', וכ\"ז הוא ע\"י העבודה דששת ימי החול שהוא העבודה בכל המדרי' דעולמות בי\"ע בבחי' ביטול היש שהוא הבירור והזיכוך בכל מדרי' ומדרי' לפי מעלתה כו', ובשבתא דמעלי שבתא הכל עולה ונכלל בבחי' מל' דאצי' כו', ועי\"ז נמשך גילוי האור בבחי' המל' וע\"י המל' נמשך הגילוי בעולמות בי\"ע כו'. והענין הוא דהנה כתי' ותקם בעוד לילה ותתן טרף לביתה וקאי על בחי' מל'\nשנשפלת בבי\"ע לברר בירורים היינו ניצוצות דתהו שנפלו בנוגה דבי\"ע שבחי' נוגה מסתיר על הניצוץ האלקי להיות נראה ליש ודבר נפרד כו' (דבאמת מתעבה ומתגשם הניצוץ ע\"י ההסתר והעלם דנוגה שמתרחק עי\"ז מאד ממקורו כו' וכמו\"כ ע\"י תערובות הפסולת שבו כו', ויובן זה במכ\"ש מהתלבשות הנה\"א בהנה\"ב שבהתלבשות זאת ה\"ה בא בהגשמה דהכחות דנה\"א בהתלבשותם בנה\"ב כמו ההשגה האלקי' אינו בערך כלל לגבי השגת הנשמה קודם התלבשותה בגוף וכן באהוי\"ר וכה\"ג כו', וגם מתעלם אורה ע\"י הסתר הנה\"ב מפני שמתרחק עי\"ז הנה\"א משרשו ומקורו האלקית, דהנה\"א כאשר לא יש דבר המסתיר מאיר אורו ביותר וע\"י הסתר הנה\"ב מתעלם אורו כו', וכמו עד\"מ אור השמש כאשר יש ענן המפסיק בין האור והשמש אינו מאיר שהרי גם אחרי הפסק יש אור השמש דיומא דעיבא כולו שמשא רק שאין האור מאיר כו', וכמו\"כ הנה\"ב נעשה כמו מסך שמפסיק בין הנה\"א ובין האלקות וכמ\"ש כי עוונותיכם מבדילים כו', ועוונותיכם אינו עון ממש כ\"א הוא ל' עיוות ועיקום והיינו שמעקם דרכו בעניני הנה\"ב יהיו איזה ענינים שיהיו\nה\"ה מבדילים בין הנה\"א והאלקות ועי\"ז מתעלם האור דנה\"א כו', ועוד זאת שנעשה מעורב בפסולת וחומרי' הנה\"ב כו' והוא מה שהנה\"א נסרך ונדבק בהענינים החומרי' כו' (ועמ\"ש בסדור בד\"ה זכר רב טובך דמ\"מ הנה\"א אינו מתפעל בזה כו', ואפשר יש בזה הפרש במדרי' הנשמה אם היא בבחי' דקות או בבחי' גסות הרוח כו' וכמ\"ש בלק\"ת בד\"ה להבין מ\"ש מי אל כמוך), וכ\"ז הוא בהנה\"א שההתלבשות אינו בדרך גלות ח\"ו שהרי בכח הנה\"א להתגבר כו', וכ\"ש בהניצוץ האלקי שבנוגה שהוא בבחי' גלות שמתעלם ומסתתר ביותר ונעשה בבחי' הגשמה מאד כו'), והבירור הוא שמתברר הניצוץ ונפרד ממנו הרע ומזדכך מכל סיג ופסולת בדרך עלייתו ממדרי' למדרי' מעשי' ליצי' ומיצי' לברי' דבפרטי' יש בזה מדרי' רבות מאד שבכל מדרי' ה\"ה מזדכך יותר עד שמתעלה ונכלל באלקו' כו'. וזהו העבודה דנש\"י למטה בששת ימי החול וכן בבחי' מל' למע' לברר בירורי הנוגה דבי\"ע כו', ובשבת הוא עליית המל' עם כל"],[3601331269,"בירורי הניצוצות המתבררים כו' (וז\"ע עליית העולמות דבשבת כו'), ועי\"ז נמשך בחי' עונג עליון בשבת בבחי' המל' (וכן גם בהעולמות העולים ונכללים בחי' מל' כו'), דהנה נת\"ל (ד\"ה על ג' דברים) שהכלים ממשיכים אור וזהו מפני שהכלי קדמה בשרשה, וענין הקדימה של הכלי הוא שהכוונה בהאור הוא להאיר את הכלי וע\"כ הכלי ממשיך את האור כו', וכמו\"כ הוא בענין הזה שהרי הכוונה היא שיתבררו ויזדככו הניצוצות ויהי' ביטול היש כו', וע\"כ ע\"י הבירור שמתהפך החשך ונעשה כלי לאלקות עי\"ז מאיר גילוי האור והוא גילוי בחי' התענוג העליון כו', וההמשכה הוא בבחי' תוס' אור מפני שנשלם בזה הכוונה שקדמה במח' תחלה כו', דכ\"ה גם בעליית הכלים שהוא בחי' הביטול שלהם שעי\"ז מאיר בהכלי אור עליון יותר מן האור שבתחלת המשכת האורות בכלים כו', ובפרט בעליית בי\"ע בבירור הנוגה שעי\"ז נעשה הגילוי ביותר כו'. וכמו עד\"מ בהתנשאות המלוכה כאשר עם רב מנשאים כבוד מלכותו יהי' המלך מלא חדוה ותענוג מזה וכ\"ש מביטול מדינות הרחוקות, כך עד\"מ בחי' מח' ורצון אנא אמלוך שעלה במח'\nלהיות התפשטות בחי' המלוכה ואין מלך בלא עם שהוא בחי' נפרדים דוקא, ומזה שהם מתבטלים ומקבלים עליהם עול מלכותו ית' יהי' זה לנח\"ר ועונג כבי' לפניו ית' וכמא' נח\"ר לפני שאמרתי ונעשה רצוני כו', ולכך נמצא העונג העליון מלובש ושורה במדת מל' דאצי' כו'. וביאור הענין הוא דהנה בחי' הארת תענוג העליון נמשך ומתלבש בכל הע\"ס דאצי' והוא עיקר חיות כל הע\"ס כו', ועז\"א במא' דפתח אליהו ואיהו שקיו דאילנא כו' וכמיא דאשקי לאילנא ואתרבו בההוא שקיו כו', דבד\"כ הוא אור הקו המאיר בע\"ס ובפרטי' הוא בחי' הארת העונג המתלבש בהם כו', וע\"ה דשרש ומקור הע\"ס הוא מבחי' א\"א בחי' חיצוני' הכתר ותענוג ידוע שזהו בחי' עתיק בחי' פנימי' הכתר שמובדל בערך מן הנאצלים כו', מ\"מ עיקר חיות כל הע\"ס וסבת ההתרחבות שלהם הוא דוקא ע\"י הארת התענוג שבהם כו', וי\"ל שזהו בחי' הכוונה פנימי' שבאצי' הע\"ס שזהו עיקר חיותם כו', ולכן התרחבות והתפשטות האור בהע\"ס הוא דוקא כאשר נשלם הכוונה כו', וכמו תנאי התנה הקב\"ה במע\"ב שאם יקיימו ישראל את תורתי מוטב כו' דהכוונה\nהוא שעי\"ז נמשך תוס' אור בהע\"ס כו', וכמארז\"ל במד\"ר ע\"פ אלה תולדות השוה\"א אלה בזכות מי הן עומדין ובזכות מי הן קיימים בזכות ואלה שמות בנ\"י ואלה כו' בזכות אלה העדות והחוקים והמשפטים כו', וכמו ועתה יגדל נא כח אד' דבזמן שישראל עושין רש\"מ מוסיפין כח בגבו' של מע' כו', וי\"ל דז\"ע ואיהו שקיו דאילנא דהיינו בחי' פנימי' הקו כו'. ובזה י\"ל הכפל ל' שאו' אח\"כ דאשקי לאילנא בההוא נביעו וההוא נביעו איהו כנשמתא כו', דמ\"ש וההוא נביעו איהו כנשמתא זהו בחי' חיצוני' הקו והיינו מה שמאיר באצי' בסוד שרש כו', ומ\"ש דאשקי לאילנא הוא בחי' פנימי' הקו כו'. וכמו שאנ\"ר בחוש בהאדם דעיקר חיות כל כחות הנפש שכל ומדות הוא מבחי' העונג שנמשך בהם, ולכן אנ\"ר דעיקר התגלות והתרחבות הכחות הוא לפ\"ע העונג שבהם, וכמו התגלות והתרחבות כח השכל הוא לפ\"ע העונג שיש לו באותה החכ', וזהו שארז\"ל לעולם ילמד אדם במקום שלבו חפץ כי החפץ והתשוקה היא בחי' התענוג ובאותו הענין שחפץ בו יצליח וישכיל יותר כו'. וכן במדות ג\"כ נמשך ומלובש בהם בחי' התענוג, וכמו במדת החסד הנה אברהם שהי' מדת החסד הי' מתענג מאד במדת חסדו וזהו סבת"],[3601331270,"התרחבות המדה הזאת, וההוראה ע\"ז הוא שמצינו שכשלא הי' לו למי לגמול חסד הי' בצער גדול מזה, וכמו שפרש\"י בפ' וירא שהי' מצטער ע\"ז שלא הי' לו אורחים, וא\"ז נמשך מצ\"ע מדת החסד, כי הנה מדה זו היא שכשיש מי שצריך לחסדו אזי ישפיע לו חסדו אבל למה יומשך הצער כשלא יהי' מי שיקבל חסדו, אלא זהו נמשך מצד העדר התענוג דהתענוג מלובש במדת החסד וכאשר לא בא התענוג לפועל יצטער בזה כו', וגם במדת הגבו' שבאדם שהוא טבע האכזריות והכעס לשפוך חמתו על בנ\"א הנה זהו התענוג שלו, דכאשר ישפוך חמתו אזי ינוח וישקט כי הגיע למחוז חפצו ותענוגו וכאשר ימנעוהו מזה יצטער כו', וכמו בשלוחי הדין כשפועלים הדין ר\"ל זהו חיותם כו', וכן בכל אדם שיש לו תענוג במלאכתו, וכמארז\"ל ב\"מ דע\"ז א' אוכלשי דמחוזא אי לא עבדי חלשי, אוכלשי הם נושאי משאות או חופרי אדמה אי לא עבדי חלשי, הרי שגם בעבודה קשה יש בזה תענוג וזהו המוסיף לו כח וחיות כו', ובגמ' ברכות דמ\"ג ע\"ב ע\"פ את הכל עשה יפה כו' מלמד שכאו\"א יפה לו הקב\"ה אומנתו בפניו, ופרש\"י דאפי' בורסי נאה אומנתו בעיניו כו', וכן בכל המדות יש בהם תענוג שזהו חיותם וקיומם וסבת התרחבו' והתפשטו' שלהם כו'.\n<b>והדוגמא</b> מזה יובן למע' דע\"ס דאצי' חב\"ד חג\"ת כו' עיקר חיותם הוא ע\"י בחי' עונג העליון אשר נמשך ומלובש ומתפשט בכל הע\"ס ובו תלוי עיקר התפשטותם והתרחבותם כו' (כמדומה דבמ\"א מבו' ההפרש בין חיות לעונג דחיות הוא מה שמוכרח ועונג הוא השפעה יתירה, וכמו בורא נפשות רבות וחסרונן ועל כל מה שבראת להחיות בהם כו', ופי' הטור סי' ר\"ז בורא נפשות רבות וחסרונן הוא מה שחסר בלא זה, ועל כל מה שבראת להחיות הוא דברים שהן לעידון ולתענוג כו', וא\"כ חיות הוא מילוי החסרון לבד שזהו בחי' אצי' מצ\"ע כו', ועונג הוא מבחי' עשירות בחי' פנימי' הכתר כו' וכמשנת\"ל ד\"ה ויקח קרח והלאה וד\"ה פדה בשלום נפשי), דכמו\"כ בחי' המל' יש בה בחי' עונג שהוא התענוג בענין המלוכה כו'. וכ\"ז הוא בחי' הארת העונג לבד שנמשך בכל הע\"ס וראשית ההמשכה הוא בבחי' חכ', וכמו שראשית גילוי הקו הוא בחכ' כמ\"ש ה' קנני ראשית דרכו כו', כמו\"כ גם הארת העונג ראשית המשכתו הוא בבחי' חכ', וכמו כשמשכיל איזה השכלה חדשה הנה בסקירה ראשונה של ההשכלה שמתחדש אצלו מתמלא\nעונג, וכמו צהבו פניו כו', וכמו חכמת אדם תאיר פניו שזהו מבחי' העונג כו', וכך למע' ראשית התגלות הארת העונג הוא בחכ' ראשית האצי' ומחכ' נמשך במדות כו', וסיום ההמשכה הוא בבחי' מל' סופא דכל דרגין דאצי' כו'. וכידוע בהארת הקו מא\"ס ב\"ה המלובש בעולם האצי' הוא מסתיים במל' דאצי' ואינו נמשך בבי\"ע, והיינו ע\"י המסך והפרסא המפסיק בין אצי' לבי\"ע שהוא המונע ומעכב שלא יומשך הארת הקו בבי\"ע רק יופסק אורו בבחי' מל' דאצי' כו', ולכן הנבראים דבי\"ע הן בבחי' יש, דע\"ס דאצי' הן אלקו' גם בחי' המל' היא אלקות ממש כו', והכלים דע\"ס דברי' וגם האורות נ\"ר הן בחי' נברא בבחי' יש ומציאות כו' מפני שאינו מאיר שם הארת הקו כו'. וכמו\"כ הארת התענוג מסתיים במל' דאצי' כו', וזהו לפי שהיא רק הארה לבד ע\"כ יש בזה חילוקי מדרי', וכמו שאנ\"ר בנפש שאינו דומה התענוג שבחכ' להתענוג שבמדות ובשארי הכחות, וכמו\"כ הוא למע' שיש חילוק בין הארת התענוג שבחכ' ובין התענוג שבז\"א ומל' כו' וזהו לפי שהוא הארה לבד כו'. אמנם ע\"י הבירורים"],[3601331271,"שבחי' המל' מבררת בנוגה דבי\"ע עי\"ז נמשך מבחי' עצמי' העונג בבחי' מל' שלמע' מבחי' הארת העונג שבחכ' ראשית הע\"ס (ובהעלם יש בבחי' מל' מבחי' עצמי' העונג שז\"ע נעוץ תחב\"ס כו', דנעיצת התחלה הוא בסוף יותר מבראש המתפשט כו', וראש המתפשט הוא בחי' חכ' ובבחי' המל' שהיא סופא דכ\"ד יש בה מבחי' תחלה יותר מבראש כו' וזהו כח ההתהוות שבבחי' מל' דוקא כו', וכמו\"כ בחי' עצמיות התענוג יש במל' בהעלם כו' ומתגלה בה ע\"י הבירורים כו'), והוא בחי' טלא דנטיף מעתיקא שזהו בחי' טלא דבדולחא והיינו בחי' גבו' דעתיק המלובש במו\"ס כו', וידוע דגבו' דעתיק הוא בחי' עצמו' עתיק כו', דהרי לית שמאלא בהאי עתיקא והגבו' היא בחי' תגבורת העצמית דהיינו בחי' עצמי' עתיק כו' (והגם שנת\"ל ד\"ה אדם כי יהי' דחסד הוא גילוי בחי' עצמות עתיק כו', היינו בענין הגילוי לבד להיות דחסד הוא בחי' גילוי כו', אבל בעצם מדריגתן בחי' גבו' הוא בחי' עצמות וחסד בחי' התפשטות והארה לבד כו' וכמ\"ש במ\"א) ומלובש במו\"ס כו', ובחי' זו הוא שנמשך בבחי' מל' ע\"י הבירורים כו'. והענין\nהוא דהנה ידוע דשרש הבירורים הוא מבחי' ח\"ס וזהו שא' בזהר בחכ' אתברירו שהכוונה היא בחי' ח\"ס כו', וז\"ש באד\"ר דקכ\"ח ב' דח\"ס שקיט ואשתכך כחמר טב דשקיט ושכיך על דורדי' כו', והוא להיות דבירורים הם מבחי' ח\"ס וכל מברר צ\"ל תחלה מבורר בעצמו וכמו קשוט עצמך כו', וכמו\"כ בחי' ח\"ס מברר תחלה הסיגים שבו עד שנעשה ברור וצלול ונק' חמר טב והשמרים נופלים למטה כו' וזהו דשקיט ואשתכיך כו', ואח\"כ יורד הארה מבחי' ח\"ס למטה באצי' בכדי לברר כו' וכמ\"ש בבה\"ז על מאה\"ז הנ\"ל. ויובן ע\"פ משנת\"ל (ד\"ה ויקחו לי תרומה וד\"ה אח\"מ) בענין ההבדלה בין חכ' דתו' לחכ' דמע\"ב שזהו הבדלה בבחי' חכ' גופא, דכל מע\"ב שרשם מבחי' חכ' דאצי' וכמ\"ש כולם בחכ' עשית שכל מה שנתהווה הוא מבחי' חכ' דאצי', רק שהחכ' דמע\"ב היא בחי' פסולת לגבי החכ' דתו' כו', וההבדלה היא מבחי' ח\"ס כו' (והיא ההבדלה שע\"י יגת\"ד שמבדילים בין עצמות החכ' שהיא חכ' התו' ובין בחי' אחורים וחיצוני' דחכ' שהיא חכ' דמע\"ב כו'). והנה הרצון ג\"כ בכ\"מ בשוה דהרי הרצון הוא על כל דבר כו' דהכל עלה\nבמח' כו', וכמ\"ש במ\"א דתהו ותיקון שניהם עלו במח' וכן ישראל ועכו\"ם כו', רק שזהו בפנימי' וזה בחיצוני' כו', הרי דבחיצוני' הרצון הכל שוה כו', וזשארז\"ל במד\"ר והארץ היתה תהו אלו מעשיהן של רשעים ויאמר אלקים יהי אור אלו מעשיהן של צדיקים ועדיין איני יודע באיזה מהן חפץ כו', והיינו דמצד הרצון הרי כחשיכה כאורה שניהם שוה לפניו כו' (ובמ\"א מבו' דהתהוות התהו הוא מהעדר הרצון וכמא' דין לא הניין לי' כו', וזהו בבחי' הפנימי' דוקא וזש\"א הניין ולא הניין דהיינו בבחי' העונג כו', אבל בחיצוני' הרצון הכל שוה כו'). והבירור וההבדלה בהרצון זהו מבחי' ח\"ס שהוא בחי' טעם כמוס לרצון כו', דגם ח\"ס הוא בחי' חכ' וטעם אלא שהיא חכ' נעלמה שלמע' מהשגת הנאצלים וכמא' שתוק כך עבמ\"ח כו', וכאשר הרצון מתלבש בחכ' הנעלמה שהוא בחי' טעם לרצון נעשה הבדלה בהרצון לרצות בהטוב ולשנוא את הרע מחמת הטעם שכן הוא ראוי ע\"פ החכ' כו', וע\"ה שהרצון הוא בלתי מוגבל בעצם ה\"ה בא בבחי' הגבלה ע\"י בחי' ח\"ס כו', וזהו ע\"י בחי' גבו' דעתיק שמלובש במו\"ס והו\"ע בחי' קו המדה שמודד ומגביל את הרצון להיות הרצון דוקא בזה ובאופן כך כו' (וא\"ז קו המדה המודד"],[3601331272,"בחי' חיצוני' האור דס' השתל' שבהמדידה בא האור בבחי' הגבלה ממש, וכאן היא מדידה פנימי' והיינו דגם כמו שהוא מדוד הוא בלתי מוגבל כו' ועמשנת\"ל ד\"ה ראשי המטות). וזהו הבירור שמבחי' העונג, דהנה הרצון הוא בהכל בשוה כו' אבל העונג הוא דוקא במה שמוכשר הוא כו', וכאשר העונג בא בבחי' ח\"ס נעשה עי\"ז הבירור וההגבלה בבחי' הרצון והיינו הבירור מה שהוא עצמות הרצון שבזה דוקא הוא עצם הרצון והחפץ כו', וזהו שרש הבירורים שהוא מבחי' גבו' דעתיק המלובש במו\"ס כו', וע\"כ ע\"י הבירורים שמל' מבררת נמשך בבחי' מל' בחי' עצמות התענוג שבח\"ס כו', והמשכה זו במל' הוא בשבת דאז הוא עליית העולמות דהיינו שכל הבירורים שמתבררים עולים בבחי' מל' כמו שהיא באצי' כו' ועי\"ז נמשך בחי' התענוג בבחי' מל' וע\"י המל' נמשך הגילוי גם בבי\"ע כו'. והענין הוא כמ\"ש בפע\"ח ובסי' בכוונת רצה והחליצנו שהוא בחי' חליצת הנעל דמט\"ט שהוא המסך וישלוט אצי' עצמו שלא ע\"י הנעל כו' (בפע\"ח שער השבת פי\"ז אי' חליצת נעל דמט\"ט לעלות לברי', ובסי' האריז\"ל אי' וישלוט אצי' עצמו או\nברי' וכ\"כ במ\"ח ובפי' הרמ\"ז חקת דקפ\"א ע\"א), והיינו שנמשך גילוי האצי' בבי\"ע כו', וזהו ע\"י הזיכוך ובירור דעולמות בי\"ע בעבודה דששת ימי החול ועולים בבחי' העלאת מ\"ן בליל שבת בחי' שבתא דמעלי שבתא וראוים הם לגילוי האצי' כו', עי\"ז נמשך אור האצי' בבי\"ע כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ויקח קרח כו', דהנה ידוע דקרח רצה להגביר הגבו' על החסדים וזה הי' מחלקותו על הכהונה, דכהנים ולוים הם חו\"ג כהן הוא בחי' חסד כמ\"ש אתה כהן לעולם ולוים בחי' גבו' כמ\"ש ועבד הלוי הוא כו', ורצה להגביר הגבו' כו', דהנה אי' בזהר חילא דאורייתא שמאלא אתכליל בימינא והיינו שצ\"ל בחי' שמאלא אבל שיהי' כלול בימינא כו', וכמו ברצו\"ש שהן בחי' חו\"ג דהשוב הוא ע\"י הרצוא דוקא דהרצוא הוא הביטול והיינו הבירור והביטול דנבראים להיות ראוים לאור האצי' ועי\"ז דוקא נמשך בהם אור האצי' כו', אבל תכלית הכוונה הוא השוב והגילוי והרצוא שהוא העלי' הוא בשביל הירידה כו', וזהו דשמאלא אתכליל בימינא כו'. אבל קרח רצה להגביר הגבו' מפני שראה שהגבו' קודמים לחסדים, וכמו הצמצום הראשון שקדם לגילוי הקו שזהו הוראה שהגבו' קודמים בשרשן, וכמא' בתחלה עבמ\"ח לברוא את העולם במדה\"ד ואח\"כ שיתף מדה\"ר כו' וכמשנת\"ל (ד\"ה וכל העם רואים), וכן הרצוא הו\"ע עיקרי שאא\"ל השוב בלי הקדמת הרצוא כו', וכן בהשתל' הרי גבו' דעת\"י למע' במדרי'\nמבחי חסד דעתי' דגבו' בחי' עצמו' עתיק כו', מכ\"ז חשב להגביר הגבו' כו'. אבל טעה בזה דקדימת הצמצום בשרשו הוא מה שנמצא כלול בהגילוי דאוא\"ס שלפה\"צ שהכוונה בהגילוי הוא שיהי' ע\"י הצמצום דוקא וכמשנת\"ל ד\"ה הנ\"ל, וא\"כ הרי הצמצום הוא בשביל הגילוי כו' (ומעלת הצמצום מצ\"ע שיש לו קדימה בעצם זה יתגלה לעתיד אבל הקדימה בהגילוים הוא רק שעי\"ז יהי' הגילוי כו'), ואם תופס הצמצום עצמו היינו שנאחז בהצמצום ה\"ז היפך הכוונה לגמרי כו' וכמשנ\"ת שם, וכן ברצו\"ש הרי העיקר הוא השוב שהרי לא לתהו בראה אלא לשבת יצרה שאין הכוונה בהעלי' מצ\"ע כ\"א שעי\"ז תהי' ההמשכה כו', וכן במעלת גבו' דעתיק הנה הגילוי הוא ע\"י בחי' החסד דוקא, וגילוי בחי' גבו' דעתיק"]]});
